    [129] = {n="Золотий Грифон", d="У Стормвінді люблять левів, а грифон — наполовину лев. Щоправда, їм може не сподобатися, яка саме половина. — Майстер грифонів Талонекс"},
    [130] = {n="Чорний Грифон", d="У Стормвінді люблять левів, а грифон — наполовину лев. Щоправда, їм може не сподобатися, яка саме половина. — Майстер грифонів Талонекс"},
