    [187] = {n="Лазуровий Дракон Нетерокрилих", d="Пообіцявши донести тебе аж до краю Аутленду, дракон Нетерокрилих зрештою й сам потягнувся до блакитних небес Азероту."},
    [188] = {n="Кобальтовий Дракон Нетерокрилих", d="Пообіцявши донести тебе аж до краю Аутленду, дракон Нетерокрилих зрештою й сам потягнувся до блакитних небес Азероту."},
