    [190] = {n="Смарагдовий Дракон Нетерокрилих", d="Пообіцявши донести тебе аж до краю Аутленду, дракон Нетерокрилих зрештою й сам потягнувся до блакитних небес Азероту."},
    [191] = {n="Фіалковий Дракон Нетерокрилих", d="Пообіцявши донести тебе аж до краю Аутленду, дракон Нетерокрилих зрештою й сам потягнувся до блакитних небес Азероту."},
    [196] = {n="Примарний Тигр", d="Як і личить справжньому гоблінові, Ландро Лонгшот міцно тримає в руках усю торгівлю цими загадковими безтілесними їздовими тваринами."},
    [197] = {n="Прудкий Примарний Тигр", d="Історики стверджують, що ці безтілесні звірі постали тоді, коли вибухнув Дренор, вивільнивши енергії, які спотворили флору й фауну світу."},
    [199] = {n="Бойовий Ведмідь Амані", d="Лише найметкіші герої, що наважилися ступити до тролячого храму Зул'Аман, спромоглися приборкати цих рідкісних бойових їздових тварин."},
    [201] = {n="Баран Бровар-фесту", d="Бровари вивели цю їздову тварину з рекламної служби після скарг на те, що ці звірі «надто норовливі», щоб давати їм раду у великих містах."},
    [202] = {n="Прудкий Баран Бровар-фесту", d="Дворфи приписують лагідну вдачу цієї породи суворому вишколу, та інші раси переконані, що тут не обійшлося без щоденної порції міцного елю."},
    [203] = {n="Кенарійський Бойовий Гіпогриф", d="Члени Кенарійського Кола здавна підтримують довгий і плідний союз зі своїми побратимами-гіпогрифами. Коли ж конфлікту не уникнути, на службу прикликають Кенарійського Бойового Гіпогрифа."},
    [204] = {n="Турбонаддувна Летюча Машина", d="Лише найталановитіші інженери мають відвагу й витримку, щоб створити летючу машину, яка вирізняється стійкістю та безпекою. А наддути її турбіною — це вже просто божевілля!"},
    [205] = {n="Літальна машина", d="Кістяк повітряних сил Альянсу складається переважно з ґномських літальних машин — за їхню маневреність і швидкість."},
    [206] = {n="Безжальний Дрейк Нижнього Світу", d="Найагресивніших дрейків Нижнього Світу вручали тим героям, які виявили неабияку звитягу й відданість на гладіаторській арені."},
    [211] = {n="Незер-Ракета X-51", d="Спершу X-51 розробляли як прискорювач для значно більшої ракети, та виявилося, що вона дає ідеальну тягу для одного вершника."},
    [212] = {n="Незер-Ракета X-51 X-TREME", d="Чого їй бракує в безпеці, те вона з лишком надолужує швидкістю та стилем. Не для боязких."},
    [213] = {n="Швидкий білий яструбоступ", d="Я можу мати сумніви щодо вірності принца Кель'таса, але ніколи — щодо його смаку. — Елродан"},
    [219] = {n="Верхівець Вершника без Голови", d="Чи крізь повінь, чи крізь вогонь — цей помчить туди, куди скажеш."},
    [220] = {n="Чорний Бойовий Елекк", d="Винятково агресивних і войовничих биків-елекків відбирають зі стада й продають торговцям-ефіріалам. Ті привчають биків до бою й перепродають господарям, яким байдуже до безпеки."},
    [221] = {n="Бойовий Кінь Смерті з Акеруса", d="Деякі коні лише переймають темряву. Цей кінь народився в ній і нею був витворений."},
    [222] = {n="Прудка Жевра", d="Жевр рідко використовують як їздових тварин в Азероті через їхню вперту вдачу та звичку кусатися."},
    [223] = {n="Мстивий Дрейк Нижнього Світу", d="Найагресивніших дрейків Нижнього Світу вручали тим героям, які виявили неабияку звитягу й відданість на гладіаторській арені."},
    [225] = {n="Їздовий Кодо Пивного Свята", d="Ти не пам'ятаєш точно, як здобув цю їздову тварину. Утім, ти взагалі мало що пам'ятаєш із того, що діється на Пивному Святі."},
    [226] = {n="Великий Кодо Пивного Свята", d="Корен Дайрбрю виграв цей приз, перепивши друїда-таурена — а той був у ведмежій подобі. Це була одна з найгордовитіших митей у житті Дайрбрю."},
    [230] = {n="Великий Бойовий Ведмідь", d="Він великий, він готовий до бою, і він ведмідь. Чого ще можна бажати від верхового звіра?"},
    [236] = {n="Крилатий Скакун Чорного Клинка", d="Живий чи мертвий — ти йдеш зі мною."},
    [237] = {n="Білий Полярний Ведмідь", d="Морозні врайкули вірять, що намисто з кігтів полярного ведмедя дарує власникові неземну силу."},
    [238] = {n="Швидкий Примарний Грифон", d="Навіть мертвим час від часу потрібно когось підвезти."},
    [240] = {n="Механо-Кабан", d="Хоч їх складно збудувати й важко доглядати, ці кабани з лишком виправдовують свою ціну однією лише крутістю."},
    [241] = {n="Лютий Дракон Порожнечі", d="Найагресивніших драконів Порожнечі віддавали тим героям, що виявили неабияку звитягу й відданість на гладіаторській арені."},
    [243] = {n="Великий Ведмідь Blizzard", d="Щоразу, осідлавши цього верхового звіра, ти відчуваєш нестримне бажання вигукнути: «Сійте хаос і спустіть мурлоків війни!»"},
    [246] = {n="Лазуровий дрейк", d="Завжди говори чемно з розлюченим драконом."},
    [247] = {n="Синій дрейк", d="Не ставай між драконом і його гнівом."},
    [248] = {n="Бронзовий дрейк", d="Втрачений час уже ніколи не повернути. О, та ні, ось він, знайшовся. — Хронорму"},
    [249] = {n="Червоний дрейк", d="Не варто слухати вигадки менестрелів. Дракон ніколи не скривдить ані душі — хіба що його самого спробують скривдити першим."},
    [250] = {n="Сутінковий дрейк", d="Та найважливіше правило, правило, яке ти ніколи не маєш забувати: хай як він плакатиме, хай як благатиме, ніколи не годуй його після опівночі."},
    [251] = {n="Чорний Полярний Ведмідь", d="Таунка використовують шкури чорних полярних ведмедів у своїх релігійних обрядах, зазвичай на похоронах тих, хто полює на чорних полярних ведмедів."},
    [253] = {n="Чорний дрейк", d="Ніколи не варто скидати з рахунку живого дракона."},
    [254] = {n="Чорний Бойовий Мамут", d="Зазвичай сумирні, ці розумні тварини утворюють міцний зв'язок зі своїми вершниками, що робить їх відданими й безстрашними в бою."},
    [256] = {n="Шерстистий мамонт", d="Прямі нащадки першого прабатька роду мамонтів, шерстисті мамонти вважаються дикішими й первіснішими за своїх короткошерстих родичів."},
    [258] = {n="Крижаний Мамут", d="Сини Годіра вірять, що їзда на білосніжному мамуті захистить вершника від обмороження та снігової сліпоти."},
    [262] = {n="Червоний Протодракон", d="Врайкули першими розпізнали їхній потенціал. Або, можливо, другими — залежно від того, як на це поглянути."},
    [263] = {n="Чорний Протодракон", d="Виведений спеціально, щоб вшанувати тих героїв, які виявили виняткову стійкість і витривалість перед лицем небезпек Нортренду."},
    [264] = {n="Синій Протодракон", d="Штормові Вершини! Там ми знайдемо звіра, достатньо сильного, щоб нести мене в битву. — Скаді Безжальний"},
    [265] = {n="Загублений у Часі Протодракон", d="Єдина причина існування часу в тому, щоб усе не сталося водночас."},
    [266] = {n="Зачумлений Протодракон", d="Виведений спеціально, щоб вшанувати тих героїв, які виявили неабияку відвагу й наполегливість перед лицем небезпек Нортренду."},
    [267] = {n="Фіолетовий Протодракон", d="Не можу не замислитися, чи все склалося б інакше, якби титани піднесли хоча б ще один драконяча зграя. — Алекстраза"},
    [268] = {n="Дрейк-альбінос", d="Навіть випробування Товариства Природничих Драконів не дали певної відповіді на те, чи пов'язаний дрейк-альбінос із якимось відомим драконячою зграєю. — Бреанні"},
    [269] = {n="Броньований Бурий Ведмідь", d="Швидкість цієї ведмежої їздової тварини посилена важкою бронею, наповненою магією магів Кірін-Тор."},
    [271] = {n="Чорний Бойовий Ведмідь", d="Убивати ватажків Орди — нагорода сама по собі, та цей грізний звір стане чудовою згадкою про звитягу."},
    [273] = {n="Великий Караванний Мамонт", d="Лише цьому громоподібному, велетенському, мов гора, скакуну довіряють купці свій захист, наважуючись пройти найнебезпечнішими торговими шляхами Азероту."},
    [275] = {n="Чопер Мехінженера", d="Утілення бездоганної інженерної майстерності, цей чопер — одна з небагатьох особистих машин Азероту, розрахованих на двох."},
    [276] = {n="Броньований сніжний грифон", d="Приємно те, що коли вони нападають, кров майже ніколи не плямує їхнє пір'я. — Мей Френсіс"},
    [277] = {n="Броньований Синій Вершник Вітру", d="Вони родом не з Нортренду, але надзвичайно добре призвичаїлися до холоду. — Мей Френсіс"},
    [278] = {n="Зелений Протодракон", d="Врайкули першими розгледіли їхній потенціал. Або другими — як подивитися."},
    [279] = {n="Розкішний Летючий Килим", d="Стандартна комплектація: міцний каркас із наповненої магією морозоткані та нитки зі справжнього павутиння крижаного павука. Запасна подушка під голову продається окремо."},
    [280] = {n="Тундровий Мамонт Мандрівника", d="Стародавні рукописи зображують купців, що мандрують замерзлою тундрою на цих колосальних звірах, тож учені вважають їх першими прирученими їздовими тваринами."},
    [285] = {n="Летючий Килим", d="Сідай на цей летючий килим, щоб побачити осяйний, мерехтливий і прекрасний світ Азероту — диво за дивом."},
    [286] = {n="Великий Чорний Бойовий Мамонт", d="Колись велетні використовували їх, щоб нести важкоброньованих воїнів, тож ці великі бойові мамонти легко можуть везти не одного вершника не велетенського зросту."},
    [288] = {n="Великий Крижаний Мамонт", d="Як удома почуваючись на вузьких крижаних стежках Штормових Вершин, ці мамонти — єдині їздові тварини, яким крижані велетні довіряють возити важкі вантажі та кількох вершників одразу."},
    [291] = {n="Синій Драконояструб", d="Драконояструби належать до найсмертоносніших відомих хижаків. Вони здатні помітити здобич на величезній відстані, стрімко налетіти й роздерти її пазурами та дзьобом."},
    [292] = {n="Червоний Драконояструб", d="Драконояструби належать до найсмертоносніших відомих хижаків. Вони здатні помітити здобич на величезній відстані, стрімко налетіти й роздерти її пазурами та дзьобом."},
    [293] = {n="Ілідарський Згубний Яструб", d="Раз на рік у часі виникає розлом, і трапляються дивні речі. Розвідники ілідарі та Згубоход були неабияк здивовані, опинившись у Танарісі."},
    [294] = {n="Стормвіндський Скакун", d="Хоч цю породу й виведено в Стормвінді, вона виявила незвичну здатність переносити холод Крижаної Корони."},
    [295] = {n="Раптор Темного Списа", d="Цю породу рапторів спершу плекали дракарі, та згодом її перейняло плем'я Темного Списа в Нортренді."},
    [296] = {n="Баран з Айронфорджа", d="Перевіряч фактів з Дикого Молота стверджує, що саме ця порода стала першим видом баранів, якого приручили дворфи, коли оселилися в Дун Морогу."},
    [297] = {n="Дарнасський Нічний Шабель", d="Коли їздова тварина нічного ельфа гине, за звичаєм вершник зберігає одне з великих іклів шабеля як пам'ятну річ."},
    [298] = {n="Номереганський Механоступ", d="Коли тобі край як треба бути на місці просто зараз. — Ріллі Шпиндельгоріх"},
    [299] = {n="Екзодарський Елекк", d="Елекки з Екзодара — це елекки, яких благословив О'рос, наару, що разом із Веленом та його послідовниками вирушив з Дренора до Азероту."},
    [300] = {n="Оґриммарський Вовк", d="Якийсь час багато орків полюбляли казати, що вони \"голодні, мов оґрімарський вовк\". Дехто з ельфів крові й досі вживає цей вислів з іронією."},
    [301] = {n="Кодо з Тандер Блафу", d="Ватажок стада, цей кодо — взірцевий приклад могутніх створінь, що громовою ходою долають простори Мулгору."},
    [302] = {n="Сільвермунський Яструбоступ", d="Отож кажу я, що сьогодні маю настрій на курятину. А наступної миті вже лежу горілиць, і ця тварюка намагається з'ясувати, які на смак мої очі. — Боззл Бластболт"},
    [303] = {n="Бойовий Кінь Покинутих", d="Коли полеглих героїв піднімають у нежиття, та сама доля спіткає і їхніх коней."},
    [304] = {n="Голова Мімірона", d="Взірець майстерності титанів, що його збирав Древній Бог Йоґг-Сарон. Наразі найбільша механічна голова гнома в усьому Азероті."},
    [305] = {n="Срібний Гіпогриф", d="Срібні гіпогрифи стають у пару лише з найхоробрішими й найгартованішими в боях поборниками."},
    [306] = {n="Окутий Залізом Протодракон", d="Його шкура за мідь твердіша була, що ні меч, ні спис не пробивали — ціла й жива."},
    [307] = {n="Іржавий Протодракон", d="Блищить не так, як інші, та все одно це чудова знахідка, друзі. — Бранн Бронзбірд"},
    [308] = {n="Синій Бойовий Кінь-Скелет", d="Рідкісне видовище. Більшість із них зникла, коли в Стратгольмі запанував барон Рівендер."},
    [309] = {n="Білий Кодо", d="\"Кодо — опора нашого народу. Куди б не йшла Орда — торгувати, селитися чи воювати — там завжди побачиш могутнього кодо.\" — Гарб Кіготь-Копито"},
    [311] = {n="Отрутошкірий Равазавр", d="Ти виростив це створіння з лускатого малюка — Мор'век так пишався б тобою. Та все одно змусив би тебе прибрати безлад, який воно влаштувало в кутку."},
    [312] = {n="Морська Черепаха", d="Цих їздових тварин часто ловлять рибалки ще зовсім молодими, і у воді вони почуваються значно затишніше, ніж на суходолі."},
    [313] = {n="Крижаний Вірм Смертоносного Гладіатора", d="Ці оживлені знаряддя руйнування не бояться смерті — вони її несуть."},
    [314] = {n="Чорний Кінь-Скелет", d="Покинуті вірять, що без мети навіть в'ючні тварини страждають у нежитті."},
    [317] = {n="Крижаний Вірм Лютого Гладіатора", d="Деяких із найгрізніших драконів Азерота прикликали крізь завісу між життям і смертю, щоб вони служили новим господарям із незгасною відданістю."},
    [318] = {n="Великий Червоний Елекк", d="Перших червоних телят елекків ніколи не бачили в Награнді — вони народилися в Азероті вже після прибуття «Екзодара». Дехто з заводчиків припускає, що цей незвичайний окрас якось пов'язаний із тим самим випромінюванням, що спустошило острів Кривавої Імли."},
    [319] = {n="Прудкий місячний шаблезуб", d="Багато нічних ельфів шанують цих гордих їздових тварин, адже їхнє мерехтливе хутро символізує богиню місяця Елуну."},
    [320] = {n="Прудкий Червоний Яструбоступ", d="Що значить «це фарбоване»? А, ви про птаха. Так, ми трохи підправили той червоний колір. — Трелліс Морнінгсан"},
    [321] = {n="Прудкий Сірий Скакун", d="Ветеран кількох найважчих битв Срібного хрестового походу."},
    [322] = {n="Великий Золотий Кодо", d="Альфа свого стада, цей кодо — взірець могутніх створінь, що з гуркотом носяться Південним Степом."},
    [323] = {n="Турбоступ", d="Дзеркало не для того, щоб ти озирався, а щоб вороги бачили хоч щось, окрім твоїх вихлопних труб. — Ріллі Спіндлнат"},
    [324] = {n="Прудкий Фіолетовий Баран", d="Товстий кістлявий череп і величезні роги барана з Барак Тор'ола роблять його ідеальною їздовою твариною, щоб проривати ряди закутих у броню ворогів."},
    [325] = {n="Прудкий Пурпуровий Раптор", d="Давні союзники тролів, ці мисливці джунглів утворюють особливий зв'язок зі своїми господарями. Вони стають для них їздовою твариною, охоронцем і другом."},
    [326] = {n="Білий Кістяний Бойовий Кінь", d="Коли полеглих героїв піднімають у нежиття, така ж доля чекає й на їхніх коней."},
    [327] = {n="Прудкий Бордовий Вовк", d="З вовками Орди заводять дружбу, а не приручають їх."},
    [328] = {n="Магічний Півень", d="Магія в руках генія здатна на дивовижні, неймовірні речі. Магія в руках телепня здатна зробити велетенського півня."},
    [329] = {n="Гіпогриф Срібного Завіту", d="Гіпогрифи Срібного Завіту відчайдушно віддані — і своїм вершникам, і Альянсу."},
    [330] = {n="Драконояструб Сонцехапів", d="Сонцехапи Даларану обирають собі за верхових тварин лише найпрудкіших і найгрізніших драконояструбів."},
    [331] = {n="Скакун Квел'дорай", d="Походить від роду шляхетних коней, що колись паслися біля берегів Криниці Вічності."},
    [332] = {n="Яструбоступ Сонцехапів", d="На полі бою я вимагаю швидкості, грації та дисципліни. Цей слугуватиме чудово. — Ересея Світанкоспівка"},
    [336] = {n="Вохристий Кістяний Бойовий Кінь", d="Коли полеглих героїв піднімають у нежить, та сама доля спіткає і їхніх коней."},
    [337] = {n="Смугастий Світанковий Шаблезуб", d="Нічні ельфи колись вірили, що зустріти таку світлошерсту породу шаблезубів у дикій природі — лиха призвістка."},
    [338] = {n="Срібний Скакун", d="Привчений приймати в сідло лише поборників Світла."},
    [340] = {n="Крижаний Вірм Невблаганного Гладіатора", d="За життя його не вдавалося приборкати, та некромантія разом із таємними ритуалами поєднання нарешті схилили цю нескорену істоту до волі її вершника."},
    [341] = {n="Срібний Бойовий Кінь", d="Дається лише тим, хто довів себе як поборник на Срібному Турнірі."},
    [342] = {n="Прудкий Вовк Орди", d="Кілька найпрудкіших верхових тварин Срібного Хрестового походу було вручено тим членам Орди, які особливо відзначилися під час турніру в Крижаній Короні."},
    [343] = {n="Прудкий Скакун Альянсу", d="Кілька найпрудкіших верхових тварин Срібного Хрестового походу було вручено тим членам Альянсу, які особливо відзначилися під час турніру в Крижаній Короні."},
    [344] = {n="Білий Бойовий Кінь Хрестоносця", d="Вручаються лише найвправнішим поборникам Випробування Хрестоносця; цих скакунів обрали для членів Альянсу з власної стайні Тіріона Фордрінга."},
    [345] = {n="Чорний Бойовий Кінь Хрестоносця", d="Вручаються лише найвправнішим поборникам Випробування Хрестоносця; цих скакунів обрали для членів Орди з власної стайні Тіріона Фордрінга."},
    [349] = {n="Оніксійський Дрейк", d="Вона має багато спільного зі своєю матір'ю, окрім того, що не була вбита й піднята з мертвих. Та вона ще зовсім юна. — Малоріак"},
    [350] = {n="Кодо Сонцехода", d="Цей розкішний звір, оздоблений священними оберегами й розписаний святими знаками, випромінює тепло сонця."},
    [351] = {n="Великий Кодо Сонцехода", d="На світанку шляхетні сонцеходи часто проводять ритуали, щоб благословити своїх верхових тварин і наповнити їх святою магією."},
    [352] = {n="Серцеїд X-45", d="Аптекар Гуммель пофарбував цей шедевр у яскраво-рожевий через нерозділене кохання."},
    [358] = {n="Крижаний Вірм Гнівного Гладіатора", d="Багато хто вважає, що на початку свого життя ці вірми були змушені битися зі своїми ж родичами на втіху іншим. Можливо, саме тому вони мають особливо войовничу вдачу."},
    [363] = {n="Непереможний", d="Уславлений скакун Артаса Менетіла, що служить своєму господареві в житті й у смерті. Осідлати його — то справжній подвиг сили."},
    [364] = {n="Крижаний Переможець Морозного Виводку", d="Підняті з холодних глибин Крижаної Корони, Переможці Морозного Виводку вважаються одними з найлютіших і найневгамовніших серед усіх крижаних вірмів."},
    [365] = {n="Скривавлений Переможець Морозного Виводку", d="Скривавленими Переможцями називають тих піднятих крижаних вірмів, які загинули особливо жахливою й кривавою смертю."},
    [366] = {n="Багряний смертний скакун", d="Утримується в стайнях цитаделі Крижаної Корони, щоб служити найулюбленішим посіпакам Короля-Ліча."},
    [367] = {n="Елекк Екзарха", d="Екзархи дренеїв здавна йшли на війну верхи на цих величних верхових тваринах, виведених заради їхніх гострих, мов лезо, бивнів."},
    [368] = {n="Елекк Великого Екзарха", d="Лише найвидатніші паладини отримують честь їздити на цьому елекку. Його пластинчастий обладунок і пурпурові оздоби благословив сам Пророк Велен."},
    [371] = {n="Полум'яний Гіпогриф", d="Гіпогрифи — надзвичайно розумні, свідомі істоти; вони значно більше, ніж просто «верхові тварини»."},
    [372] = {n="Білий Шерстистий Носоріг", d="Спійманий Тобі \"Матінкою Гускою\" Айронболтом у Бореальній тундрі, цей кудлатий звір затаїв величезну образу за те, що його загнуздав ґном."},
    [373] = {n="Морський Коник Вашжіру", d="Уперті, доки їх не приборкаєш, ці підводні їздові тварини — найшвидший спосіб подорожувати глибинами Вашжіру."},
    [375] = {n="Морозний Летючий Килим", d="\"Пам'ятаю свій перший летючий килим... шерсть єті й мішковина. І близько не такий гарний, як оцей.\" — Фрозо Уславлений"},
    [376] = {n="Небесний Скакун", d="Промінь надії; дороговказне світло в темряві."},
    [382] = {n="Туристична Ракета X-53", d="Летіти самотужки на велетенському циліндрі, повному вибухонебезпечного ґоблінського ракетного пального, — справжнє божевілля... тож бери з собою друга."},
    [386] = {n="Скам'янілий раптор", d="Легенди оповідають про чари, накладені на мисливського раптора, що наважився загарчати на юну Тіранду Віспервінд, коли вона купалася в озерці серед джунглів. Звір приречений блукати Азеротом — доки не вибачиться."},
    [388] = {n="Гоблінський Трайк", d="Зібрання гайок, болтів, шестерень і оброблених дерев'яних панелей дарує напрочуд плавну їзду."},
    [389] = {n="Гоблінський турбо-трайк", d="Триколісна будова турбо-трайка дає більшу стійкість і менший радіус повороту порівняно з його двоколісними родичами."},
    [391] = {n="Вулканічний Кам'яний Дрейк", d="Вогонь здатен дивовижно перетворювати камінь, та ніколи не кажіть Кам'яній Матері, що це сказала я. — Закличниця землі Євая"},
    [392] = {n="Дрейк Східного Вітру", d="У своєму божевільному прагненні створювати нових драконів Дезвінг знехтував дивовижними породами, яких ще ніколи не бачили в Азероті. — Тралл"},
    [393] = {n="Фосфоресцентний Кам'яний Дрейк", d="Кам'яна Матір майже не зважала на бунтівного Еонакса, навіть дозволивши забрати його поріддя зі свого володіння."},
    [394] = {n="Дрейк Західного Вітру", d="Підкоривши стихійну силу бурі, ці величні створіння тріщать, наче блискавка, і ревуть, наче грім."},
    [395] = {n="Дрейк Північного Вітру", d="Хто пізнав бурю, того втомлює спокій."},
    [396] = {n="Дрейк Південного Вітру", d="Ніжний, мов літній бриз, та це мало про що говорить, як зважити, звідки він родом. — Ітеш"},
    [397] = {n="Склистий Кам'яний Дрейк", d="Оце було б ідеальне для підвіски, а з того вийшов би неймовірний перстень. Дай знати, якщо ця штука линяє чи скидає шкіру абощо. — Калінда"},
    [398] = {n="Бурий Їздовий Верблюд", d="Феннімору Квіґлі приписують те, що він першим видоїв верблюда і побив рекорд із «найдовшого ненавмисного польоту» — і все це за один день."},
    [399] = {n="Світло-бурий Їздовий Верблюд", d="Феннімору Квіґлі приписують те, що він першим видоїв верблюда і побив рекорд із «найдовшого ненавмисного польоту» — і все це за один день."},
    [400] = {n="Сірий Їздовий Верблюд", d="Феннімору Квіґлі приписують те, що він першим видоїв верблюда і побив рекорд із «найдовшого ненавмисного польоту» — і все це за один день."},
    [401] = {n="Темний Фенікс", d="Попри свою назву, темні фенікси відомі теплою і веселою вдачею."},
    [403] = {n="Золотий король", d="Хай тебе не обманює сідло: він дикий, а не приручений лев."},
    [404] = {n="Ультрамариновий Бойовий Танк Кіраджі", d="Подейкують, що тол'вірський чаклун Азж'Акір мав скіпетр, який дозволяв йому керувати бойовим танком кіраджі за межами їхньої домівки в Силітусі."},
    [405] = {n="Примарний Скакун", d="Темні духи тікають перед сяйвом його присутності."},
    [406] = {n="Примарний Вовк", d="Боїться лише вогню."},
    [407] = {n="Пісковиковий Дрейк", d="Пісковикових дрейків колись ретельно вивчав уславлений алхімік Воллай Спрайспрокет. Кажуть навіть, що Воллай створив зілля, здатні відтворити фізіологію цих дрейків."},
    [408] = {n="Плямистий Дрейк", d="Я думала, що ця тварина хвора, аж поки вона не злетіла. Літає так само вправно, як і будь-хто з моїх власних. — Алекстраза"},
    [409] = {n="Кор'кронський Нищитель", d="Лютий у бою й напрочуд вірний, цей бойовий скорпіон служить лише тим, хто виявляє справжню відданість могутній гільдії."},
    [410] = {n="Броньований Раптор Раззаші", d="Ці чистокровні королівські раптори Зул'Гуруба стали рідкісним видовищем у Стренглторні. Кажуть, що ґурубаші впадають у шал, побачивши будь-кого, крім троля, верхи на одній зі своїх дорогоцінних тварин."},
    [411] = {n="Прудка Зуліанська Пантера", d="Тролі джунглів давно жадають пантерячих іклів, використовуючи їх у ритуалах або як складники для моджо."},
    [412] = {n="Драконояструб амані", d="Драконояструби, звільнені з тролячого рабства, вважаються одними з найвірніших серед усіх своїх родичів."},
    [413] = {n="Полум'яний Гіпогриф-Сторож", d="Полум'яні гіпогрифи-сторожі тішаться поразкою Раґнароса, Володаря Вогню."},
    [415] = {n="Чистокровний Вогняний Сокіл", d="Легенди стверджують, що рід чистокровних сягає корінням самого створення Вогняних Земель."},
    [416] = {n="Сокіл Скверноогню", d="Скверноогонь смертоносний навіть на дотик. На щастя, сокіл здатен приборкати полум'я, не обертаючи свого вершника на смарагдову подобу."},
    [417] = {n="Зіпсований Вогняний Сокіл", d="Міллаґазор був вогняним соколом, вірним Раґнаросу. Досі невідомо, скільки яєць Міллаґазора зазнали псування."},
    [418] = {n="Лютий Раптор", d="Колишній супутник Канґи Первісного, полеглого тролячого героя. Ім'я цього раптора невідоме, бо Канґа розмовляв із ним лише в подобі ведмедя."},
    [419] = {n="Амані бойовий ведмідь", d="Тролі амані прикрашають цих лютих їздових тварин магічними амулетами й церемоніальними масками на знак шани ведмежому богові Налоракку."},
    [420] = {n="Приборканий Морський Коник", d="«Той, хто не відчував припливної течії у своєму волоссі верхи на величному морському конику, по-справжньому й не жив», — не казав ніхто. Ніколи."},
    [421] = {n="Крилатий Вартовий", d="Нещодавно відкопаний у стародавній гробниці, цей могутній крилатий лев колись, можливо, служив одному зі стародавніх принців тол'вірів."},
    [422] = {n="Лютий Бойовий Скакун", d="Закутий у броню, щоб витримувати зіткнення в бою."},
    [423] = {n="Лютий бойовий вовк", d="За наказом вождя Гелскріма приборкувачі Орди почали вирощувати вовків, щоб ті розкривалися сповна в жасі й шаленстві затяжного бою."},
    [424] = {n="Сутінковий Дрейк Лютого Гладіатора", d="Герої, які довели свою силу на гладіаторських аренах за часів Катаклізму, отримували найвинятковіших представників сутінкового драконячого виводка."},
    [425] = {n="Полум'яний Кіготь Алісразора", d="Як і в їхньої матріархи Алісразор, лють і запал цих стихійних птахів невгамовні."},
    [426] = {n="Прудкий Береговик", d="Рідкість серед порід довгоногів Калімдору, але його легко впізнати за різким запахом мертвих водоростей."},
    [428] = {n="Сутінковий Дрейк Безжального Гладіатора", d="Герої, які довели свою силу на гладіаторських аренах за часів Катаклізму, отримували найвинятковіших представників сутінкового драконячого виводка."},
    [429] = {n="Прудкий Лісовий Ходун", d="Цю яскраву породу можна знайти лише в лісах острова Темного Місяця."},
    [430] = {n="Прудкий Весняний Ходун", d="Радощі Шляхетного Саду найкраще святкувати разом із цим відданим, лагідним і непоказно забарвленим дивом природи."},
    [431] = {n="Прудкий Папужка-Нерозлучник", d="Він наче червоний, та не зовсім."},
    [432] = {n="Білий Верховий Верблюд", d="Феннімор Квіглі прославився тим, що першим подоїв верблюда й побив рекорд найдовшого ненавмисного польоту, і все це за один день."},
    [433] = {n="Зіпсований Гіпогриф", d="Сумно визнавати, та навіть мудрий і величний гіпогриф може стати жертвою псування."},
    [434] = {n="Танцюючий Ведмідь Темного Місяця", d="Ці грізні їздові тварини мають звичку раптово пускатися в танок просто посеред бою, на превелику досаду своїх вершників."},
    [435] = {n="Гірський кінь", d="Зображення цієї породи часто можна побачити на діжках із розведеним дворфівським пивом."},
    [436] = {n="Бистрий гірський кінь", d="Прагне дня, коли зможе повернутися додому, до Ґілнеасу."},
    [439] = {n="Бойовий Кінь Тіраеля", d="Символ справедливості в усіх відомих світах."},
    [440] = {n="Примарний Грифон", d="Коли ти сказав, що повернеться давній друг, я уявляла собі дещо інакше.\n— Бралла Клаудвінг"},
    [441] = {n="Примарний Вітрокрил", d="Як ти крізь нього не провалюєшся?\n— Мазта"},
    [442] = {n="Палаючий Ящер", d="Палаючі ящери мають безмежну жагу до життя, і багато хто вважає їх одними з найвідданіших їздових тварин Азероту."},
    [443] = {n="Сутінковий Вісник", d="Яка б темна магія колись не скоряла Сутінкового Вісника, тепер вона зруйнована... чи справді?"},
    [444] = {n="Прислужниця Життєв'язі", d="Алекстраза, колишній драконячий Аспект Життя, відома як добра й терпляча наставниця. Під її опікою лише найвідданіші учениці здобувають титул «Прислужниці Життєв'язі»."},
    [445] = {n="Експеримент 12-B", d="Одні вважають, що Експеримент 12-B — це наслідок таємної ініціативи ШІ-7, інші бачать у ньому результат ембріональних експериментів ґоблінських науковців. Хай там як, одне напевно: зважаючи на його силу, швидкість і спритність, Експеримент 12-B виявився успіхом!"},
    [446] = {n="Серце Аспектів", d="Ви — справжні охоронці Азероту, і майбутнє цього світу у ваших руках, адже настав світанок доби смертних.\n— Алекстраза"},
    [447] = {n="Скверноящер", d="Тисячоліття тому, борючись із Палаючим Легіоном, цей звитяжний ящер скорився скверні, коли його тіло просочила чиста демонічна магія."},
    [448] = {n="Нефритовий хмарозмій", d="Нефритові хмарозмії легкі та спритні; стрімкі й смертоносні."},
    [449] = {n="Лазурова водомірка", d="«Зазвичай комах беруть за наживку, та хіба можна зазирнути цьому в очі й навіть подумати про таке?» — Нат Пейгл"},
    [451] = {n="Самоцвітна Оніксова Пантера", d="Торговий принц Ґаллівікс нещодавно замовив кілька десятків цих блискучих, всипаних самоцвітами їздових тварин, щоб вони походжали володіннями його палацу втіх."},
    [452] = {n="Зелена драконяча черепаха", d="Цінованих за здатність нести важкі вантажі та за впевнену ходу, цих витривалих тварин більшість корінних пандаренів обирає за їздових тварин найперше."},
    [453] = {n="Велика червона драконяча черепаха", d="«Серед уже встановленого: подвійні ліхтарі-протитуманки, барило аварійного варива та сидіння зі справжньої шкіри танджі.» — Черепахівниця Одай"},
    [454] = {n="Жарогривий Бойовий Кінь", d="Створений самим Рагнаросом як дарунок доньці, якої він ніколи не мав."},
    [455] = {n="Обсидіанове нічнокрило", d="Коли не можеш бігти — повзеш, а коли не можеш повзти — знаходиш когось, хто тебе понесе."},
    [456] = {n="Сапфірова Пантера", d="Легенди кажуть, що один прадавній пандаренський імператор виготовив першу самоцвітну пантеру для свого сина, після того як брат-близнюк хлопчика помер від хвороби."},
    [457] = {n="Нефритова Пантера", d="Легенди кажуть, що один прадавній пандаренський імператор виготовив першу самоцвітну пантеру для свого сина, після того як брат-близнюк хлопчика помер від хвороби."},
    [458] = {n="Рубінова Пантера", d="Легенди кажуть, що один прадавній пандаренський імператор виготовив першу самоцвітну пантеру для свого сина, після того як брат-близнюк хлопчика помер від хвороби."},
    [459] = {n="Сонячна Пантера", d="Легенди кажуть, що один прадавній пандаренський імператор виготовив першу самоцвітну пантеру для свого сина, після того як брат-близнюк хлопчика помер від хвороби."},
    [460] = {n="Як Великої Експедиції", d="Ці в'ючні тварини відомі тим, що несуть понад уп'ятеро більше за власну вагу та здатні витримати кілька днів без їжі та води."},
    [462] = {n="Кафа Як", d="Незрозуміло, чи назвали ґраммли цього яка за його кольором, чи за призначенням."},
    [463] = {n="Бурштиновий Скорпіон", d="Клаксі їдуть у бій проти своїх ворогів верхи на велетенських скорпіонах. Панцир, загартований бурштином, дає чудовий захист на полі бою."},
    [464] = {n="Лазуровий хмарозмій", d="Пандарени вірять, що лазурові хмарозмії — провісники доброї долі."},
    [465] = {n="Золотий хмарозмій", d="Золоті хмарозмії — скарб, яким милується кожен, хто завітає на континент Пандарія."},
    [466] = {n="Громовий Нефритовий Хмарозмій", d="Змалечку громових хмарозміїв вабить до бур. Відомо, що вони женуться за блискавками крізь чорні буремні хмари й купаються в зливі."},
    [467] = {n="Сутінковий Дрейк Катаклізмічного Гладіатора", d="Герої, які довели свою міць на гладіаторських аренах за часів Катаклізму, отримали найвинятковіших нащадків сутінкових дрейків."},
    [468] = {n="Імперський Квілен", d="Улюбленці давніх моґуйських принців, квілени стають вірними й безстрашними супутниками та їздовими тваринами."},
    [469] = {n="Ракета зі Збідненого Кіпарію", d="Коли кіпарит втрачає свою бурштинову есенцію, він стає доволі стійким до корозії від ракетного пального."},
    [470] = {n="Геосинхронний Світокрут", d="Цю ракету спершу створили, щоб пришвидшити обертання світу й зробити ночі коротшими. Ґноми, що страждають на безсоння, ставлять перед собою високі цілі."},
    [471] = {n="Оніксовий хмарозмій", d="Оніксові хмарозмії, як відомо, агресивніші й відважніші за своїх родичів — небесних оніксових хмарозміїв."},
    [472] = {n="Багряний Хмарозмій", d="Багряні хмарозмії схильні до примх: можуть зірватися в, здавалося б, безладну мандрівку за одним лише поривом, інколи на кілька днів поспіль."},
    [473] = {n="Небесний Оніксовий Хмарозмій", d="Небесні оніксові хмарозмії народжуються з фіолетовою лускою, що вкриває все їхнє тіло. З часом ця луска темнішає до кольору оніксу."},
    [474] = {n="Небесний Багряний Хмарний Змій", d="Небесних Багряних Хмарних Зміїв вважають одними з найшляхетніших драконів."},
    [475] = {n="Небесний Золотий Хмарний Змій", d="Від цього величного створіння линуть тепло й надія, і сяє воно, наче схід сонця над горами."},
    [476] = {n="Ю'лей, Дочка Нефриту", d="Від цього величного створіння линуть тепло й мудрість, і сяє воно, наче місячне світло крізь найчистіший нефрит."},
    [477] = {n="Небесний Блакитний Хмарний Змій", d="Від цього величного створіння линуть тепло й спокій, і сяє воно, наче безхмарне небо літнього пообіддя."},
    [478] = {n="Астральний Хмарний Змій", d="Подейкують, що Астральні Хмарні Змії знають відповіді на деякі з найбільших таємниць життя. Шкода, що вони не вміють говорити."},
    [479] = {n="Блакитний Їздовий Журавель", d="Величний журавель — дорогоцінний друг пандаренів."},
    [480] = {n="Золотий Їздовий Журавель", d="Журавель — символ мудрості й шляхетності, а його здатність нести нас у небеса — справжнє диво. — Джалуу Щедрий"},
    [481] = {n="Величний Їздовий Журавель", d="Журавель — символ мудрості й шляхетності. Його здатність нести нас у небеса — справжнє диво. — Джалуу Щедрий"},
    [482] = {n="Джунглевий Їздовий Журавель", d="Улюблена їздова тварина на півдні Пандарії, джунглевий журавель славиться швидкістю і спритністю, відточеними за ціле життя втеч від красарійських тигрів."},
    [484] = {n="Чорний Їздовий Як", d="Ґрамли, що мандрують вершиною Кун-Лай уночі, обирають цього темношерстого яка, щоб лишатися непоміченими, але спершу знімають дзвіночки з його збруї."},
    [485] = {n="Скромний Експедиційний Як", d="На відміну від своїх в'ючних родичів, цей як полюбляє мандрувати без вантажу й долати за раз не більше милі."},
    [486] = {n="Сірий Їздовий Як", d="Їздових яків розводять стрункішими й спритнішими за їхніх родичів."},
    [487] = {n="Палевий Їздовий Як", d="Їздових яків виводять стрункішими та спритнішими за їхніх родичів."},
    [488] = {n="Багряна Водомірка", d="\"Зазвичай комах беруть на наживку, але хіба можна зазирнути їй в очі й бодай подумати про таке?\" — Нат Паґл"},
    [492] = {n="Чорна Драконяча Черепаха", d="Цих витривалих створінь, цінованих за здатність нести важкі вантажі та впевнену ходу, обирають за їздових тварин більшість корінних пандаренів."},
    [493] = {n="Синя Драконяча Черепаха", d="Цих витривалих створінь, цінованих за здатність нести важкі вантажі та впевнену ходу, обирають за їздових тварин більшість корінних пандаренів."},
    [494] = {n="Бура Драконяча Черепаха", d="Цих витривалих створінь, цінованих за здатність нести важкі вантажі та впевнену ходу, обирають за їздових тварин більшість корінних пандаренів."},
    [495] = {n="Фіолетова Драконяча Черепаха", d="Цих витривалих створінь, цінованих за здатність нести важкі вантажі та впевнену ходу, обирають за їздових тварин більшість корінних пандаренів."},
    [496] = {n="Червона Драконяча Черепаха", d="Цих витривалих створінь, цінованих за здатність нести важкі вантажі та впевнену ходу, обирають за їздових тварин більшість корінних пандаренів."},
    [497] = {n="Велика Зелена Драконяча Черепаха", d="\"До комплекту входять: подвійні ліхтарі протитуманного світла, аварійне барило з трунком і сидіння зі справжньої шкіри танджі.\" — Черепашиха-наставниця Одай"},
    [498] = {n="Велика Чорна Драконяча Черепаха", d="\"До комплекту входять: подвійні ліхтарі протитуманного світла, аварійне барило з трунком і сидіння зі справжньої шкіри танджі.\" — Черепашиха-наставниця Одай"},
    [499] = {n="Велика Синя Драконяча Черепаха", d="\"До комплекту входять: подвійні ліхтарі протитуманного світла, аварійне барило з трунком і сидіння зі справжньої шкіри танджі.\" — Черепашиха-наставниця Одай"},
    [500] = {n="Велика Бура Драконяча Черепаха", d="\"До комплекту входять: подвійні ліхтарі протитуманного світла, аварійне барило з трунком і сидіння зі справжньої шкіри танджі.\" — Черепашиха-наставниця Одай"},
    [501] = {n="Велика Фіолетова Драконяча Черепаха", d="\"До комплекту входять: подвійні ліхтарі протитуманного світла, аварійне барило з трунком і сидіння зі справжньої шкіри танджі.\" — Черепашиха-наставниця Одай"},
    [503] = {n="Багряний Пандаренський Фенікс", d="Кажуть, що оперення Багряного Фенікса уособлює процвітання і щастя."},
    [504] = {n="Громовий Величний Хмарозмій", d="Змалечку Громових Хмарозміїв вабить до бур. Відомо, що вони ганяються за блискавками крізь чорні буремні хмари і купаються у проливному дощі."},
    [505] = {n="Зелений Їздовий Тигр Шадо-Пан", d="\"Будиш тигра — бери довгу палицю. А ще краще — попроси розбудити тигра свого друга.\" — пандаренське прислів'я"},
    [506] = {n="Синій Їздовий Тигр Шадо-Пан", d="\"Будиш тигра — бери довгу палицю. А ще краще — попроси розбудити тигра свого друга.\" — пандаренське прислів'я"},
    [507] = {n="Червоний Їздовий Тигр Шадо-Пан", d="\"Будиш тигра — бери довгу палицю. А ще краще — попроси розбудити тигра свого друга.\" — пандаренське прислів'я"},
    [508] = {n="Бура Їздова Коза", d="Щоб привчити вперту гірську козу до верхової їзди, потрібні невичерпне терпіння і лагідна рука."},
    [509] = {n="Червона Літуча Хмара", d="Стародавній артефакт могу, що дарується тим, хто щиро відданий пізнанню та поширенню пандаренських переказів."},
    [510] = {n="Біла Їздова Коза", d="Щоб привчити вперту гірську козу до верхової їзди, потрібні невичерпне терпіння і лагідна рука."},
    [511] = {n="Чорна Їздова Коза", d="Щоб привчити вперту гірську козу до верхової їзди, потрібні невичерпне терпіння і лагідна рука."},
    [515] = {n="Син Галеона", d="Привчені змалечку, ці велетенські мушани вміють громоносно вриватися в бій, несучи на собі цілу бойову ватагу сауроків."},
    [516] = {n="Пандаренський Повітряний Змій", d="Цей знак шани — подарунок від Хронікерів Пандарії. Щоправда, посібник із керування, схоже, до нього не додається."},
    [517] = {n="Громовий Рубіновий Хмарозмій", d="Змалечку Громових Хмарозміїв вабить до бур. Відомо, що вони ганяються за блискавками крізь чорні буремні хмари і купаються у проливному дощі."},
    [518] = {n="Попелястий Пандаренський Фенікс", d="Вважають, що і назва, і барва цього величного фенікса символізують відродження."},
    [519] = {n="Смарагдовий Пандаренський Фенікс", d="Кажуть, що барви оперення цього рідкісного фенікса приносять велику удачу."},
    [520] = {n="Фіолетовий Пандаренський Фенікс", d="Кажуть, що оперення Фіолетового Фенікса символізує єднання протилежних сил."},
    [521] = {n="Нефритовий Пандаренський Змій", d="Мешканці Пандарії вітають твоє завзяття в захисті дикої природи. Щоправда, їх непокоїть, як прихистити 150 тварин за кожен візит."},
    [522] = {n="Небесний Голем", d="Славетне досягнення інженерії: небесний голем виводить традиційну технологію подрібнювачів на цілком новий рівень (і на нову висоту!)."},
    [523] = {n="Прудкий Вітровий Скакун", d="Одне з найневловиміших створінь Пандарії, що, як кажуть, приносить удачу своєму вершникові."},
    [526] = {n="Великий броньований грифон", d="Цей шляхетний грифон — настільки надійний бойовий товариш, про якого тільки може мріяти будь-який воїн Альянсу."},
    [527] = {n="Великий броньований віверн", d="Цей лютий звір, славетний серед приборкувачів вівернів, був однією з перших їздових тварин, обраних для Наступу Панування Орди."},
    [528] = {n="Величний Грифон", d="Гострий зір грифонів дозволяє їм бачити на величезні відстані й попереджати вершників про будь-яку небезпеку попереду."},
    [529] = {n="Величний Віверн", d="Віверни походять з одних із найнегостинніших країв Калімдору, тож вони майстри пристосовуватися до будь-якого середовища."},
    [530] = {n="Броньований Небокрик", d="Лише ті героїчні душі, що подолали кожне випробування, яке ставлять перед ними тирани-моґу, можуть гордо ширяти небесами на бойовому небокрику."},
    [531] = {n="Поріддя Горрідона", d="Коли бачиш, що насувається ураган, ти тікаєш геть. Горрідон же став би з ураганом до бою — і переміг би."},
    [532] = {n="Примарний Бойовий Кінь", d="Не всі жертви Медіва зникли назавжди."},
    [533] = {n="Кобальтовий Первісний Жахоріг", d="«Коли б'єшся пліч-о-пліч з рапторами, потрібна така їздова тварина, яку вони не з'їдять». — невідомий диномант"},
    [534] = {n="Бурштиновий Первісний Жахоріг", d="Є старе зандаларське прислів'я про диких жахорогів: «Тікай!»"},
    [535] = {n="Сланцевий Первісний Жахоріг", d="Маски не для того, щоб приборкати жахорога; вони для того, щоб ніхто не побачив твого обличчя, коли він обернеться проти тебе."},
    [536] = {n="Нефритовий Первісний Жахоріг", d="Святкове забарвлення приховує смертоносні наміри."},
    [537] = {n="Кістяно-Білий Первісний Раптор", d="«У вісім місяців вони смертельні, дуже смертельні». — Гемет Несінгварі-молодший"},
    [538] = {n="Червоний Первісний Раптор", d="Раптори розповзлися майже по всіх землях Азероту. Достеменно невідомо, чи тролі привели їх за собою, чи пішли за ними."},
    [539] = {n="Чорний Первісний Раптор", d="Швидкість, хитрість і лють — ось те, чим тролі й раптори захоплюються одне в одному."},
    [540] = {n="Зелений Первісний Раптор", d="«Раптори настільки ж віддані, наскільки й люті. Якщо ти не друг — ти їжа». — Кіджара"},
    [541] = {n="Хмарний Змій Лиховісного Гладіатора", d="Ці хмарні змії мають луску, що... власне, кольору хмар."},
    [542] = {n="Громовий Кобальтовий Хмарний Змій", d="Це нащадок дратівливого Налака. Блискавки б'ють з його луски й дугами здіймаються над сідлом. Наважишся сісти?"},
    [543] = {n="Виводок Джі-Куна", d="Хоч Джі-Кун і ласувала невдалими витворами формувальників плоті могу, її потомство охоче поїдає й буденніші туші."},
    [544] = {n="Броньоване Криваве Крило", d="Цей жахливий плотоїдний кажан — безперечний володар нічного неба."},
    [545] = {n="Золотий Первісний Жахоріг", d="Гострий з обох кінців і підступний посередині. Тільки тролі могли вважати, що це гарна ідея."},
    [546] = {n="Багряний Первісний Жахоріг", d="Звісно ж, ельфи крові обрали саме червоного."},
    [547] = {n="Картковий Скакун", d="Кожен крок відлунює люттю трьох твоїх суперників."},
    [548] = {n="Броньований Червоний Драконояструб", d="Ця рідкісна порода драконояструба — знак пошани в Орді, дарунок від ельфів крові. Вона відображає твої невтомні зусилля зібрати маленьку армію їздових тварин."},
    [549] = {n="Броньований Синій Драконояструб", d="Після того, як ти зібрав величезний звіринець із 200 їздових тварин, служба захисту тварин Альянсу надіслала тобі засіб тримати їх у покорі (і подалі від себе)."},
    [550] = {n="Кремезний Мушан Бійця", d="Роками пандарени вважали цих створінь нездоланними. Спитай-но першого пандарена, якому це вдалося, — Геньші «Кульгавого» Домоварива."},
    [551] = {n="Зачарований чарівний дракон", d="Це величне створіння — старший брат Брайтвінг. Він запевняє, що її, власне, удочерили."},
    [552] = {n="Залізокований Примарний Скакун", d="Залізна оболонка ледь стримує його ефірний дух. Ці могутні жеребці — передостаннє творіння Саланара Вершника, і колись вважалося, що всіх їх знищено."},
    [554] = {n="Лютий Калдорейський Бойовий Шаблезуб", d="Леза, що оздоблюють обладунок цієї їздової тварини, покликані і вселяти страх, і завчасно нарізати трапези для бойового шаблезуба."},
    [555] = {n="Лютий Кістяний Бойовий Кінь", d="Дістається лише тим, хто здолав своїх ворогів у битві."},
    [557] = {n="Поріддя Галакраса", d="Родовід цього грізного створіння можна простежити до Галакраса, а ще далі — до Галакронда, одного з найсумнозвісніших протодраконів."},
    [558] = {n="Бойовий Вовк Кор'кронів", d="Кор'крони беруть собі за верхових лише найдужчих вовків і вбирають їх у броню, що зламала б хребет слабшим створінням."},
    [559] = {n="Колос Кор'кронів", d="Колос Кор'кронів — це знаряддя нестримної руйнації, що зродилося в думках Ґарроша Хеллскріма і втілилося в життя руками його інженерів."},
    [560] = {n="Звір Мушан Попелястий", d="Дехто каже, що їзда на попелястому мушані принесе міцне здоров'я та зростання достатку. Цих людей називають \"торговцями верхових тварин\"."},
    [561] = {n="Громовий Оніксовий Хмарний Змій", d="Цей чорний як смола хмарний змій — оповите блискавицями видиво такої рідкості, що багатьох смертних довело до божевілля."},
    [562] = {n="Хмарний змій тиранічного гладіатора", d="У класичному чорному ці хмарні змії завжди виглядають елегантними й стрункими."},
    [563] = {n="Хмарний Змій Тяжкого Гладіатора", d="Ці яскраво забарвлені хмарні змії мають луску, що поєднує рубіновий, золотий і майже фіолетовий відтінки."},
    [564] = {n="Хмарний Змій Пихатого Гладіатора", d="Ці яскраво забарвлені хмарні змії мають луску в кольорах від золотого до рожевого. Або можна назвати її кораловою."},
    [568] = {n="Смарагдовий Гіпогриф", d="Ці величні тварини бувають різних кольорів, але смарагдовий різновид можна приборкати лише магією дружби."},
    [571] = {n="Залізний небесний грабіжник", d="Звіроводи Залізної Орди виростили цього рилака для війни, а потім спорядили його до бою чорною крицею та жевріючим полум'ям."},
    [593] = {n="Бойовокований Кошмар", d="Кошмарний скакун із загартованої криці та мстивих духів, цей супутник без нарікань піде за тобою в самісінькі глибини Вогняних Земель і назад."},
    [594] = {n="Вишкірений Хижак", d="Різниця між усмішкою та вишкіром така ж, як різниця між поцілунком і скуштуванням."},
    [600] = {n="Моторошний ворон", d="Сповнені ненависті прадавнього бога, моторошні ворони — найвірніші охоронці аракоа."},
    [603] = {n="Повзучий Килим", d="Літати не вміє, зате повзає дуже швидко."},
    [606] = {n="Магмовий гончак", d="Розплавлений до самого осердя!"},
    [607] = {n="Кровоступ Ґроннлінг", d="Щойно з ним \"потоваришуєш\", ґроннлінг радо понесе свого вершника назустріч загибелі."},
    [608] = {n="Зморшкошкірий Скелетоп", d="Копита цього різновиду роздертокопита вкриті дрібними виямками, що дають йому змогу безпечно дертися гірськими краями в пошуках їжі."},
    [609] = {n="Приручений Льодокопит", d="Лише ставши власником цієї їздової тварини, ти зрозумів, скільки випробувань приготував тобі світ Дренору. Шерсть роздертокопита лізе геть усюди!"},
    [611] = {n="Тундровий Льодокопит", d="Прозорий шар пуху вкриває шкірясту шкуру цієї породи й слугує бездоганним захистом від холоду."},
    [612] = {n="Кривавокопитий Бик", d="Воїни клану Бойової Пісні віддавна полювали на цих роздертокопитів, аби з їхньої багряної шкури робити бойові стяги."},
    [613] = {n="Залізнокопитий Руйнівник", d="Кажуть, що Блекгенд власноруч створив вогняне спорядження для бойових роздертокопитів Залізної Орди."},
    [614] = {n="Плямистий Лукотоп", d="Довгий хобот елекка дає йому змогу винюхувати їжу, уникати небезпеки та красти ласощі з твоїх сумок, щойно ти відвернешся."},
    [615] = {n="Приручений Лукотоп", d="Дренеї віддавна довели до досконалості розведення елекків, оздоблюючи цих створінь просякнутими Світлом кристалами, щоб зробити їх сумирнішими."},
    [616] = {n="Тіньошкірий Перлозуб", d="За одними переказами, дренеї вперше потоваришували з елекками після того, як один із цих звірів врятував пораненого розвідника від зграї лютих стручкових."},
    [617] = {n="Запорошений Скелешкір", d="Відколи ти отримав цю їздову тварину, тебе мучать дивні гарячкові сни про тупотливих, цокотливих елекків на параді."},
    [618] = {n="Броньований Залізозуб", d="Кажуть, елекк ніколи нічого не забуває. Тож не дивно, що цей звір зневажає Залізну Орду, зважаючи на ті муки, яких йому завдали орки."},
    [619] = {n="Чорносталевий Бойовий Вепр", d="Відмовляється бігти, доки його голова не вкрита важким металом із шипами. Це питання гордості."},
    [620] = {n="Бойовий Вепр-Скелезуб", d="Партнерів приваблює не металевий шолом, а крутий ірокез."},
    [621] = {n="Броньований Морозний Вепр", d="Харчується майже виключно мерзлими ягодами. Хоч повільні чужинці теж видаються йому смачними."},
    [622] = {n="Броньований Гострохребет", d="Ніколи... нізащо... НІКОЛИ... не дай йому занюхати на тобі бекон."},
    [623] = {n="Бойовий Вепр Морозних Рівнин", d="Якби не це круте кільце в іклі, він почувався б геть безглуздо в такому вбранні."},
    [624] = {n="Дикий Кровозуб", d="Якщо хочеш лагідну поїздку, то пошукай собі якогось \"приручений щасливозуб\" чи щось таке."},
    [625] = {n="Одомашнений Гострохребет", d="\"Одомашнений\" не означає \"дружній\". Прихопи трохи ласощів."},
    [626] = {n="Велетенський Холодноморд", d="Його морда не лише холодна, а й мокра. Не надто приємний спосіб прокинутися."},
    [627] = {n="Могутній Сірозуб", d="Скидає ікла раз на рік. Поки вони не відростуть, надзвичайно сором'язливий."},
    [628] = {n="Приручений Скелезуб", d="Ретельно навчений хрюкати, гарцювати й топтати обличчя своїх ворогів."},
    [629] = {n="Приручений Річкобрід", d="Річкоброди — одні з найміцніших звірів Дренору, звідки й їхня підвищена витривалість та характерне забарвлення."},
    [630] = {n="Сапфіровий Річковий Звір", d="Забарвлення цієї тварини повторює чисту блакить мілин драенорських річок, тож для водяних хижаків вона майже невидима."},
    [631] = {n="Багнистоспинний Річковий Звір", d="Особлива перетинка, що росте на підошвах лап багнистоспинного, дає йому додаткове зчеплення в багні та на слизькій місцевості."},
    [632] = {n="Мохошкірий Річковий Валько", d="Агресивний і територіальний, мохошкірий славиться тим, що ховається в чагарниках на берегах річок і нападає із засідки на необачних перехожих."},
    [633] = {n="Пекельний Інфернал", d="З надр Нижнього світу прикликають істоту з чистої ненависті, що прагне спопелити будь-яке життя на своєму шляху."},
    [634] = {n="Сонячний Шпильовий Яструб", d="Глянути в очі цьому містичному звіру — однаково що зазирнути в саме серце сонця. Під час їзди радимо вдягати окуляри."},
    [635] = {n="Тіньогривий Бойовий Кінь", d="Драенейські поети порівнюють забарвлення цього талбука з тінями, що їх відкидає місячне сяйво в попелястому лісі."},
    [636] = {n="Прудкий Вітроступ", d="Драенеї покладаються на цю їздову тварину, найпрудкішу з усіх талбуків, щоб гінці та їхні послання безпечно діставалися до місця призначення."},
    [637] = {n="Приручений Сріблошкірий", d="Цінований за свій розум, цей різновид талбука можна навчити захисних копняків та ударів рогами в бою."},
    [638] = {n="Жеребець Вітроступів", d="Червоне забарвлення цих вітроступів відбиває їхню вдачу: запальну, люту й відважну."},
    [639] = {n="Блідий Колючкоїд", d="Цей талбук живиться виключно будяками й колючками, тому всередині він такий самий міцний, як і ззовні."},
    [640] = {n="Лютий Бойовий Баран", d="Доки він не буцне тебе головою нижче пояса, він іще не визнав тебе своїм вершником по-справжньому."},
    [641] = {n="Лютий Бойовий Раптор", d="Бо самих лише гострих зубів і пазурів виявилося замало."},
    [642] = {n="Гарн Сталепащий", d="Якось дресирувальник спробував прикрасити пащу свого сталепащого вовка металевими оздобами. Минуло три дні, перш ніж він отримав їх назад."},
    [643] = {n="Лютоікл Бойової Пісні", d="Має залізну волю, але стає справжнім лагідним другом, якщо дати йому погризти кістку рваноступа."},
    [644] = {n="Броньований Морозний Вовк", d="Його привчили виживати в суворому кліматі Хребта Морозного Полум'я, тож він горнеться до тебе так, ніби від цього залежить його життя."},
    [645] = {n="Залізнобокий Бойовий Вовк", d="На його хвості — броньований шип. Чухай йому черево на власний ризик."},
    [646] = {n="Холодополум'яний Інфернал", d="Дивні крижані язики полум'я змушують тебе водночас пітніти й тремтіти від холоду."},
    [647] = {n="Приручений Гарчун", d="Цуценям був неймовірно милий. Тепер уже трохи менше."},
    [648] = {n="Прудкий Морозний Вовк", d="Серед холодних вершин Морозного Полум'я морозні вовки полюють на все, що можуть упіймати. Найшвидші з них їдять досхочу."},
    [649] = {n="Димчастий Лютововк", d="Вважають, що мешкають вони здебільшого на півночі. Ненавидять весілля."},
    [650] = {n="Пилогривий Лютововк", d="Обережний за мірками лютововків, пилогривий погодиться нести вершника лише за щось, що вважає особливим."},
    [651] = {n="Колесо Смерті Воєначальника", d="Цього ревучого велетня часто звуть «ґоблінською газонокосаркою», адже з ворогами він поводиться так, ніби вони з трави... готової до косовиці."},
    [652] = {n="Гусеничний Клинок Чемпіона", d="Викуваний руками людини, ґнома й дворфа, цей броньований шедевр створено, щоб одним рухом керма нарізати таурена на вечерю зі стейка."},
    [654] = {n="Бойовий Єті Претендента", d="На щастя, вони рухаються швидко й здебільшого лишають свій запах позаду."},
    [655] = {n="Сонцешкірий Ґроннлінг", d="Любить сонце, ненавидить усе інше."},
    [656] = {n="Лотієнський Нишпорка", d="Ці гнучкі лиси здатні нечутно скрадатися поміж свіжоопалого листя, навіть маючи такі розміри."},
    [657] = {n="Нічновий Ґарн", d="Ґарни — найлютіші хижаки Дренору, і полюють вони завжди зграєю."},
    [663] = {n="Кривавоіклова Вдова", d="З її довгих зазубрених лап скрапує кров ворогів та/або її пари."},
    [664] = {n="Смарагдовий Дрейк", d="«Чи рідкісний смарагдовий дрейк? Ви й гадки не маєте. Якби я мала по срібняку щоразу, коли мене про нього питають, я б давно вже пішла на спочинок». — Мей Френсіс"},
    [678] = {n="Механосвин із водієм", d="Навіщо кермувати самому, коли можна найняти когось, хто зробить це за тебе?"},
    [679] = {n="Чопер робогенія з водієм", d="Перевезення — справа, що вимагає точності."},
    [682] = {n="Кіготь Порожнечі Темної Зорі", d="Зіпсовані присутністю Темної Зорі над Дренором, кігті Порожнечі опиралися спробам клану Шедоумун зламати їх і зрештою були винищені Нер'зулом. Лишилося єдине яйце, загублене в порожнечі."},
    [741] = {n="Містичний Рунний Шаблезуб", d="Просочений арканною силою, містичний рунний шаблезуб довго був прихований хаотичними енергіями Нижнього світу. Нещодавно ці створіння вийшли з тіні в пошуках силових ліній, щоб втамувати свою спрагу до магії."},
    [751] = {n="Сквернокрицевий Нищитель", d="Викуваний у глибинах Цитаделі Пекельного Вогню божевільним ковалем, сквернокрицевий нищитель поєднує ковальське вміння Залізної Орди з хаотичними енергіями Скверни Палаючого Легіону — нечестивий союз криці та полум'я."},
    [753] = {n="Зіпсована Лиховісна Крилань", d="Скупані в крові демонів, ці зіпсовані лиховісні круки значно агресивніші й нерідко вбивають одне одного, якщо тримати їх разом у неволі."},
    [755] = {n="Лютий Бойовий Механоступ", d="Оснащений наголовним Винищувачем Звіряток 9000."},
    [756] = {n="Лютий Бойовий Кодо", d="Шипаста куля на хвості достатньо міцна, щоб трощити навіть найукріпленіші оборонні споруди Альянсу."},
    [758] = {n="Пекельний Лютововк", d="Могутній вовк Дренору, торкнутий енергіями Скверни, які Ґул'дан вивільнив у джунглях Танаану. Він ще не збожеволів цілком... поки що."},
    [759] = {n="Ґроннлінг Скверної Крові Первісного Гладіатора", d="Один із ґроннлінгів джунглів Танаану, захоплений виверженням енергій Скверни, що їх вивільнив Ґул'дан, і нині одержимий невгамовною жагою хаосу."},
    [760] = {n="Ґроннлінг Скверної Крові Несамовитого Гладіатора", d="Один із ґроннлінгів джунглів Танаану, захоплений виверженням енергій Скверни, що їх вивільнив Ґул'дан, і нині одержимий невгамовною жагою хаосу."},
    [761] = {n="Ґроннлінг Скверної Крові Войовничого Гладіатора", d="Один із ґроннлінгів джунглів Танаану, захоплений виверженням енергій Скверни, що їх вивільнив Ґул'дан, і нині одержимий невгамовною жагою хаосу."},
    [762] = {n="Ґроннлінг Вугільного Кулака", d="Цей маленький ґроннлінг відомий тим, що силоміць вривається до корчем гарнізону й влаштовує безлад серед горщиків та сковорідок."},
    [763] = {n="Сквернохід Іллідарі", d="Іллідарі приборкали кількох нижчих демонів, щоб обернути їх проти їхніх володарів із Легіону."},
    [764] = {n="Вартовий Гаю", d="Ці чарівні супутники є вартовими мирних, прадавніх гаїв Смарагдового Сну."},
    [765] = {n="Наїжачений Пекельний Вепр", d="Єдине джерело рідкісного кулінарного інгредієнта: проклятого бекону."},
    [768] = {n="Смертоіклий Вепр Скверни", d="Ветерани битви за Півострів Пекельного Вогню в Аутленді досі здригаються від спогадів про цих звірів."},
    [769] = {n="Прислужник Бурчуна", d="Ніхто достеменно не знає, коли в Дренорі зародилася легенда про Бурчуна, та його іграшки просто жахливі."},
    [772] = {n="Величний Жах Небес", d="Надлегке спорядження цього хроматичного рилака дає йому змогу легко шугати й ширяти крізь хмари, вільному від пут землі внизу."},
    [773] = {n="Осквернитель Гаю", d="Вартові Гаю Смарагдового Сну були одними з перших, хто впав під згубним впливом Жахіття."},
    [775] = {n="Престижний Бойовий Кінь", d="Споряджений бронею, щоб витримувати зіткнення в бою."},
    [776] = {n="Швидкий Примарний Рилак", d="Навіть мертвим час від часу треба підвезтися."},
    [778] = {n="Драконояструб Затемнення", d="Захоплені в полон у відступників ельфів крові біля точки Затемнення, ці бузкові драконояструби часто були бажаною здобиччю для Провидців, що несли службу в Святилищі Зірок."},
    [779] = {n="Дух Ечеро", d="Дух ручного лося Гулна Гаймаунтіна."},
    [780] = {n="Шабельник Скверни", d="Особливе творіння лорда Іллідана, подароване його найвірнішим мисливцям на демонів."},
    [781] = {n="Нескінченний Викрадач Часу", d="Примхливі й люті, ці дрейки ковзають крізь час, доки не знайдуть гідного вершника."},
    [784] = {n="Престижний Бойовий Вовк", d="За наказом вождя Гелскріма тренери Орди почали вирощувати вовків, які розкривають усю свою силу в страху та люті затяжного бою."},
    [791] = {n="Інфернал Полум'я Скверни", d="Іллідари зуміли приборкати одного з цих вогняних звірів, щоб використати його як нестримну й безстрашну їздову тварину проти Легіону."},
    [793] = {n="Хижий кровогляд", d="Величезна кількість сирих червоних ягід, яку поглинають ці люті всеїдні створіння, надає їхнім очам характерного кольору."},
    [794] = {n="Осяйний лютодзьоб", d="Мерехтлива шкура цих оманливо лютих і злагоджених звірів призначена збивати з пантелику та дезорієнтувати здобич."},
    [795] = {n="Снігопер мисливець", d="Здатний ховатися в смузі туману, доки здобич не наблизиться, а тоді розпороти її одним стрибком із піднятими пазурами."},
    [796] = {n="Смарагдовий гострокіготь", d="Майстерно зливається з густими магічними лісами, на кшталт тих, що оточують Розбиті острови."},
    [797] = {n="Скутий сталлю пожирач", d="Лише найміцніше викувані ланцюги здатні стримати цього звіра."},
    [799] = {n="Інфернал палахкого ядра", d="Легіон підкорив тисячі інших планет, вносячи диявольські зміни до своїх бойових машин, коли стикався з вкрай суворими умовами."},
    [800] = {n="Донний Хижак Солоних Глибин", d="Ці невловимі риби воліють причаюватися в найглибших закутках Великого моря, вишукуючи поживу в темряві."},
    [802] = {n="Давно забутий гіпогриф", d="Ти єдиний, хто пам'ятав."},
    [803] = {n="Майстерне Могильнокрило", d="Виготовлене вручну самою Каменотескою, це майстерно створене каменероджене створіння довіряють лише тим, кого вона вважає гідними."},
    [804] = {n="Щурогривий", d="Роки безперервного жлуктіння зілля в каналізації Даларану зробили його великим, спритним і стійким до тіні."},
    [826] = {n="Престижний Бронзовий Скакун", d="Один із відважних коней Розбитих островів, незрівнянний серед скакунів Азероту в лютості й силі."},
    [831] = {n="Престижний Королівський Скакун", d="Один із відважних коней Розбитих островів, незрівнянний серед скакунів Азероту в лютості й силі."},
    [832] = {n="Престижний Лісовий Скакун", d="Один із відважних коней Розбитих островів, незрівнянний серед скакунів Азероту в лютості й силі."},
    [833] = {n="Престижний Слоновокостяний Скакун", d="Один із відважних коней Розбитих островів, незрівнянний серед скакунів Азероту в лютості й силі."},
    [834] = {n="Престижний Лазуровий Скакун", d="Один із відважних коней Розбитих островів, незрівнянний серед скакунів Азероту в лютості й силі."},
    [836] = {n="Престижний Опівнічний Скакун", d="Один із відважних коней Зламаних Островів, неперевершений серед скакунів Азероту за лютістю і силою."},
    [838] = {n="Мешканець Глибин", d="У голодних безоднях Великого моря рої Мешканців Глибин колишуться, наче величезний плавучий килим, сліпо ширяючи в темряві."},
    [841] = {n="Лютий Ґілнеаський Бойовий Кінь", d="Народжений, вирощений і випробуваний у боях Ґілнеасу."},
    [842] = {n="Лютий Бойовий Трицикл", d="Найнищівніша технологія, яку лише можна купити за гроші."},
    [843] = {n="Лютий Бойовий Скороход", d="Витончений, поважний і смертоносний."},
    [844] = {n="Лютий Бойовий Елекк", d="Улюбленець воїнів Екзодару."},
    [845] = {n="Механізований Лісовидобувач", d="Джепетто, певно, трохи перестарався..."},
    [846] = {n="Гіпогриф Магічного Пера", d="Прадавні їздові тварини високорідних, нині полишені дичавіти на Зламаних Островах. Через приховану магічну силу їх украй рідко вдається знайти."},
    [847] = {n="Аркадійська Бойова Черепаха", d="Вирощена для нищення божевільним воєначальником у далекому краю, але сідло принаймні тепле."},
    [848] = {n="Штормовий Дракон Мстивого Гладіатора", d="Народжений у горах Штормгейму, цей жахливий сплав бурі й луски запалює небо, переслідуючи свою здобич."},
    [849] = {n="Штормовий Дракон Безстрашного Гладіатора", d="Народжений у горах Штормгейму, цей жахливий сплав бурі й луски запалює небо, переслідуючи свою здобич."},
    [850] = {n="Штормовий Дракон Жорстокого Гладіатора", d="Народжений у горах Штормгейму, цей жахливий сплав бурі й луски запалює небо, переслідуючи свою здобич."},
    [851] = {n="Грозовий Дракон Лютого Гладіатора", d="Народжений у горах Штормгейму, цей жахливий сплав бурі та луски запалює небо, переслідуючи свою здобич."},
    [852] = {n="Грозовий Дракон Шаленого Гладіатора", d="Народжений у горах Штормгейму, цей жахливий сплав бурі та луски запалює небо, переслідуючи свою здобич."},
    [853] = {n="Грозовий Дракон Панівного Гладіатора", d="Народжений у горах Штормгейму, цей жахливий сплав бурі та луски запалює небо, переслідуючи свою здобич."},
    [854] = {n="Великий Північний Старорог", d="Один із найвитриваліших видів, що населяють схили Високогір'я, ці створіння здатні місяцями виживати в крижаних хуртовинах."},
    [855] = {n="Темноводний Скат", d="Про цей невловний вид ската відомо мало, адже трапляється він лише в темних водах довкола острова Даркмун."},
    [860] = {n="Призматичний Диск Архімага", d="Три стихії було сплавлено воєдино, щоб створити цей магічний диск, налаштований на твою власну чаклунську силу."},
    [861] = {n="Світлоприсяжний Шукач Верховного Жерця", d="Колись численні, нині на Азероті лишилося тільки троє шукачів — після поколінь боротьби зі зіпсуттям космосу."},
    [864] = {n="Бан-Лу, Супутник Великого Магістра", d="Дитя Сюеня, Бан-Лу багато років вірно служив кожному Великому Магістрові."},
    [865] = {n="Вірний Вовкояструб Майстра Ловів", d="Дух Великого Мисливця визнав тебе гідним, і відтепер його діти повік відповідатимуть на твій поклик."},
    [866] = {n="Винищувач Лихого Виводку Володаря Смерті", d="Могутній червоний дракон, піднятий у нежиття власною життєвою енергією, — справжня наруга над життям."},
    [867] = {n="Кровожерний Бойовий Вірм Воєначальника", d="Відгукується також на ім'я «Пан Кусака»."},
    [868] = {n="Скверноламаний Верескун Винищувача", d="Зламав — то й купив."},
    [870] = {n="Лютий Вовкояструб Ловчого", d="Клубок пазурів і кігтів, що вміє літати й плавати. Ніхто не в безпеці."},
    [872] = {n="Грізний Вовкояструб Ловчого", d="Якщо попросити його щось принести, він радше за все притягне тобі голову дрібного звіра чи гуманоїда."},
    [873] = {n="Лютий Бойовий Ведмідь", d="Майже вдвічі лютіший за свого побратима з Орди."},
    [875] = {n="Полуніч", d="Досі один з найлютіших скакунів у стайнях Каражана."},
    [876] = {n="Лютий Бойовий Лев", d="Чимало зброєносців постраждало, поки створювали цю їздову тварину."},
    [877] = {n="Слоновокостий Яструбоступ", d="\"Мої крилаті діти заповнюють небеса. Та не оце.\"\n\n-Авіана"},
    [878] = {n="Кремезний Базиліск Бійця", d="Шипи цього звіра без зусиль пробивають латну броню — лише найдосвідченіші вершники взагалі наважуються осідлати цю смертоносну подушку для голок."},
    [881] = {n="Манашаблезуб Арканіста", d="Повернувшись до Нічної Фортеці, Перша арканістка Талісра подбала про те, щоб шукачі пригод, які допомогли їй звільнити Сурамар, отримали в нагороду коштовних їздових тварин з королівської стайні.\n\nЯкщо викликати цю їздову тварину в місті Сурамар, також застосовується Маскарад."},
    [882] = {n="Лютий Бойовий Скорпіон", d="Має дуже мало негострих кінців."},
    [883] = {n="Попелястий Вірм Жаротління", d="Арканаґос намагався відвернути Медіва від дослідів з арканною магією, та вплив Саргераса надто глибоко спотворив чарівника, і великий дракон сплатив за цей переступ вічною, пекучою агонією."},
    [884] = {n="Вбивче Знамення Тіньового Клинка", d="Улюблений засіб пересування для вбивць: під час польоту він не видає ані звуку — чудово підходить, щоб підкрастися до когось непомітно."},
    [885] = {n="Золотий Скакун Верховного Лорда", d="Найвишуканіший з усіх коней."},
    [888] = {n="Лютий Буревій Дальновидця", d="Лють вітру. Перевантаження: (2)."},
    [889] = {n="Смертоносний Знак Тіньового Клинка", d="Вони ніколи не почують, як ти наближаєшся."},
    [890] = {n="Згубний Знак Тіньового Клинка", d="Для тих, хто має схильність до отрут."},
    [891] = {n="Багряний Знак Тіньового Клинка", d="Кров твоїх ворогів на ньому навіть не помітна — зливається з кольором."},
    [892] = {n="Мстивий Бойовий Кінь Верховного Лорда", d="Чого це він такий розлючений?"},
    [893] = {n="Пильний Бойовий Кінь Верховного Лорда", d="Той порожній кінський погляд — це насправді «пильність»."},
    [894] = {n="Звитяжний Бойовий Кінь Верховного Лорда", d="Має чимало очок звитяги."},
    [896] = {n="Первинний Полум'яний Шаблезуб", d="Колись первісні землі Азероту аж кишіли елементальними створіннями всіх видів."},
    [898] = {n="Хаотичний Гнівний Кінь Володаря Нижнього Світу", d="Смертоносне поєднання скверни й коня."},
    [899] = {n="Черв Безодні", d="Тіні, що стікають з його луски, мовби з іншого світу. Невже це створіння з глибин океанів Азероту?"},
    [900] = {n="Лютий Бойовий Черепах", d="Тепер ти можеш буквально сховатися в панцир у кімнаті з прапором."},
    [905] = {n="Тканий зі Силових Ліній Летючий Килим", d="Нитки такі тонкі й майстерно зшиті, що годі й уявити, ніби його зробили не магією — волокно за волокном."},
    [906] = {n="Темноспоровий Скат Мани", d="Деякі з природних мешканців Аргуса, як-от скат мани, вижили й пристосувалися до життя на розколотому світі."},
    [926] = {n="Алебастрова Гієна", d="Цих гієн волдунаї використовують, щоб швидко й непомітно пересуватися пісками."},
    [928] = {n="Дюнний Падальний гриф", d="Ці витривалі стерв'ятники здатні місяцями виживати в пустках Вол'дуну, маючи обмаль їжі та води."},
    [930] = {n="Сірчаний Кінь Гніву Нетерлорда", d="Запах не надто приємний, і він ДУЖЕ міцно до тебе чіпляється."},
    [931] = {n="Проклятий Кінь Гніву Нетерлорда", d="Тінь плюс вогонь — що тут може піти не так?"},
    [932] = {n="Бойовий каркас Загартованих Світлом", d="Армія Світла завдає швидких і нещадних наскоків, використовуючи ці спритні бойові машини."},
    [933] = {n="Обсидіановий Кролуск", d="Цей кролуск несе на собі сліди того, що пережив безліч випробувань і поневірянь."},
    [934] = {n="Швидкий Примарний Гіпогриф", d="Навіть мертвим час від часу потрібно когось підвезти."},
    [935] = {n="Синій Бойовий Танк Кіраджі", d="Бойовий танк кіраджі бачили лише нещодавно під час Поклику Скарабея — чи не натяк це на повернення смертоносних створінь?"},
    [936] = {n="Червоний Бойовий Танк Кіраджі", d="Бойовий танк кіраджі бачили лише нещодавно під час Поклику Скарабея — чи не натяк це на повернення смертоносних створінь?"},
    [937] = {n="Чорний Бойовий Танк Кіраджі", d="Бойовий танк кіраджі бачили лише нещодавно під час Поклику Скарабея — чи не натяк це на повернення смертоносних створінь?"},
    [939] = {n="Соболиний Руїноступ", d="Талбуки, що мешкають на Аргусі, у ході еволюції набули хітинових пластин, щоб пережити десятиліття безперервної війни, яка спустошує цей край."},
    [941] = {n="Старорог з Високогір'я", d="Улюблена їздова тварина мисливців Високогір'я. Вона легко перестрибує через бурхливі річки Соснокам'яної улоговини, навіть коли під сідлом у неї дорослий таврен."},
    [942] = {n="Дикий мрієбіг", d="Мрієбіги за власним бажанням снують між цим світом і Смарагдовим Сном, тішачись своєю дикою вдачею."},
    [943] = {n="Хмарокрилий Гіпогриф", d="Ще більше за звичайних гіпогрифів, хмарокрилі з Азсуни полюбляють вити гнізда високо в гірських печерах, далеко над межею хмар."},
    [944] = {n="Штормокрил Валар'ярів", d="Удари його крил лунають, мов далекі розкоти грому."},
    [945] = {n="Лютий Бойовий Лис", d="Лютий, мов лис."},
    [947] = {n="Розумочерв Загадника", d="Він живиться твоїми думками, навіть тими, що ти думаєш просто зараз, читаючи це."},
    [948] = {n="Штормовий Дракон Демонічного Гладіатора", d="Народжений у горах Штормгейму, цей моторошний сплав бурі та луски запалює небо, переслідуючи свою здобич."},
    [949] = {n="Осяйний Зореловець", d="Енергійні верховні хижаки Аргуса, пантари полюють, відчуваючи енергію всередині живих істот. Наблизившись до потужного джерела енергії, пантара помітно змінює колір і стає збудженішою."},
    [954] = {n="Закутий Ур'зул", d="Зліплений із змучених тіл і душ полеглих воїнів Армії Світла, Ур'зул водночас заворожує й жахає."},
    [955] = {n="Мерзенна Нечисть", d="Налита кислотною кров'ю через моторошний ритуал, ця потвора ледь тобі підкоряється — і ти це відчуваєш."},
    [956] = {n="Стрибучий жилошукач", d="Спрей від комах і капелюх із сіткою мало чим зарадять у болотах Назміру — бери дубця."},
    [958] = {n="Примарний Птерокрил", d="Світ духів навколо Дазар'алора кишить мстивими привидами."},
    [959] = {n="Небоходець Стормвінда", d="\"Дайте мені всі двигуни, що маєте.\" — інженер Кеґшпиндель"},
    [960] = {n="Перехоплювач Оґриммару", d="Гармата у формі вовчої голови, спрямована вперед, робить цей винищувач панування в небі особливо вправним у повітряному бою."},
    [961] = {n="Ясне Жахіття", d="Коли ти їдеш на цій їздовій тварині, твої думки часто линуть до далеких країв."},
    [962] = {n="Дирижабль Тьмяного Місяця", d="Сайлас замислювався, чи не використати свій флот дирижаблів для реклами, але вирішив, що продавати їх напряму — це вся реклама, якої йому треба."},
    [963] = {n="Кровожерний Крог", d="Цього крога залишили самого бенкетувати спотвореною кров'ю та гниттям Ґ'хууна. Він був такий щасливий."},
    [964] = {n="Аметистовий Руїноход", d="Талбуки, рідні для Аргусу, за роки еволюції відростили хітинові пластини, щоб пережити десятиліття невпинної війни, яка спустошує ці землі."},
    [965] = {n="Лазуровий Руїноход", d="Талбуки, рідні для Аргусу, за роки еволюції відростили хітинові пластини, щоб пережити десятиліття невпинної війни, яка спустошує ці землі."},
    [966] = {n="Берилієвий Руїноход", d="Талбуки, рідні для Аргусу, за роки еволюції відростили хітинові пластини, щоб пережити десятиліття невпинної війни, яка спустошує ці землі."},
    [967] = {n="Умбровий Руїноход", d="Талбуки, рідні для Аргусу, за роки еволюції відростили хітинові пластини, щоб пережити десятиліття невпинної війни, яка спустошує ці землі."},
    [968] = {n="Рудий Руїноход", d="Талбуки, рідні для Аргусу, за роки еволюції відростили хітинові пластини, щоб пережити десятиліття невпинної війни, яка спустошує ці землі."},
    [970] = {n="Знавіснілий Хаосоход", d="Армія Світла змогла врятувати лише частину рідних видів Аргусу; незліченна їх кількість загинула в хаосі."},
    [971] = {n="Анторанський Жароспес", d="Власний пес Саргераса колись, можливо, був скверноловом, але за роки Темний Титан перекував і переформував свого супутника на щось набагато могутніше. Коли врешті він був задоволений своїм творінням, то взявся створювати ще більше таких псів, наповнюючи їх тінню та полум'ям."},
    [972] = {n="Анторанський Морокоспес", d="Хорт самого Саргераса колись, можливо, був скверноловом, та з роками Темний Титан перекував і переробив свого супутника на щось значно могутніше. Коли нарешті він був задоволений своїм творінням, то взявся створювати ще більше таких хортів, наповнюючи їх тінню та полум'ям."},
    [973] = {n="Осяйний Скат Мани", d="Декотрі з природних мешканців Аргуса, як-от скат мани, вижили й пристосувалися до життя на розбитому світі."},
    [974] = {n="Барвистий Скат Мани", d="Декотрі з природних мешканців Аргуса, як-от скат мани, вижили й пристосувалися до життя на розбитому світі."},
    [975] = {n="Скверносяйний Скат Мани", d="Армія Світла змогла врятувати лише частину рідних видів Аргуса; незліченна їх кількість загинула в хаосі."},
    [976] = {n="Мерехтливий Скат Мани", d="Декотрі з природних мешканців Аргуса, як-от скат мани, вижили й пристосувалися до життя на розбитому світі."},
    [978] = {n="Фіолетове Чарокрило", d="Дарунок від Ради Шести за те, що знову врятував Азерот від загрози Легіону."},
    [979] = {n="Багряна Слинопаща", d="Відгукується на низку звуків, які не здатна видати жодна недемонічна істота, та які приблизно перекладаються як «Смертеслинь»."},
    [980] = {n="Кислотний Плювака", d="Удвічі більше наповнений кислотою, ніж звичайне поріддя."},
    [981] = {n="Жовчозубий Гризун", d="Його укус однозначно гірший за схоже на гавкіт булькотіння."},
    [982] = {n="Ставкова Кропив'янка", d="Цей дивовижний водяний вид здатен вижити в найсуворіших умовах, можливо, навіть у пустці космосу."},
    [983] = {n="Славетний Сквернотрощій", d="Після того як Аллерія й Тураліон пояснили, наскільки корисні давні тварини-супутники дренеїв, Армія Світла взяла кількох із них на вишкіл."},
    [984] = {n="Благословенний Сквернотрощій", d="Після того як Аллерія й Тураліон пояснили, наскільки корисні давні тварини-супутники дренеїв, Армія Світла взяла кількох із них на вишкіл."},
    [985] = {n="Месницький Сквернотрощій", d="Коли Аллерія і Тураліон розповіли, наскільки корисною є тварина, що віддавна супроводжує дренеїв, Армія Світла взяла кількох таких до себе на вишкіл."},
    [986] = {n="Похмурокопитий Руїнохід", d="Армія Світла зуміла врятувати лише частину рідних видів Аргуса; незліченну їх кількість поглинув хаос."},
    [993] = {n="Скрекіт", d="Здогадайся, чому його так звуть? Аж ніяк не тому, що це милий і тихий улюбленець."},
    [994] = {n="Королівське Моропір'я", d="Гострі дзьоби цих папуг здатні з легкістю розколювати великі горіхи."},
    [995] = {n="Акулоприманка", d="Акулоприманка віддана тому, хто не скупиться на крекери."},
    [996] = {n="Жеребець Морської Гриви", d="Коней у війську Кул-Тіраса змалечку привчають не боятися моря, тож вони залюбки галопують уздовж берега крізь солоні бризки."},
    [997] = {n="Позолочений Равазавр", d="Верхівець, гідний верховних жерців і радників зандаларі, оздоблений лише найвишуканішими прикрасами і благословлений Резаном, великим лоа-дияволозаврів."},
    [999] = {n="Всюдихід Хівіллаґ", d="Кажуть, що цей винахід створили за подобою одного дуже багатого ґобліна. Щоправда, інші схожості не вбачають."},
    [1006] = {n="Загартований Світлом Сквернотрощій", d="Цей міцний елекк — дарунок подяки від загартованих Світлом дренеїв, привчений безстрашно мчати просто в темряву."},
    [1007] = {n="Громокопит з Високогір'я", d="Дарунок від тауренів, які навчили цього впевненого в кроці гірського лося безпечно долати стежки й вершини Високогір'я."},
    [1008] = {n="Манашаблезуб Нічнонароджених", d="Цей шляхетний кіт від народження чує згустки арканної енергії, тож його піднесли на знак подяки перевіреному союзникові нічнонароджених."},
    [1009] = {n="Зорепроклятий Ходак Порожнечі", d="Цей просякнутий тінню ходак уособлює рішучість ельфів приборкати силу Порожнечі в ім'я Альянсу."},
    [1010] = {n="Жеребець Адміралтейства", d="Ці витончені білі жеребці — одні з небагатьох їздових тварин, яким дозволено сходити на кул-тираські кораблі."},
    [1011] = {n="Шу-Зен, Божественний Вартовий", d="Поки Золотий Лотос невтомно відновлював Долину Вічного Цвітіння, одна-єдина статуя ожила й без жодного слова захистила їх від ша, що на них нападали. Одні вважають Шу-Зена знаком удачі, інші — даром Світла. Він стає вірним супутником кожному, хто боронить Азерот від божевільного шепоту Прадавніх Богів."},
    [1012] = {n="Зелений Болотяний Стрибунець", d="Ґоттум збирає виводок Краг'ви по всьому Жабоболоту, але їздовими тваринами стають лише найпухкіші."},
    [1013] = {n="Медовоспинна збиральниця", d="Поки більшість збиральниць мріє лише про мед і квіти, ця сповнена жаги пригод бджола задивляється на широкий світ за межами Долини Штормової Пісні."},
    [1015] = {n="Сіра в Яблуках", d="Улюблена їздова тварина морських жерців, що звуть Штормову Пісню домівкою."},
    [1016] = {n="Димчастий Бойовий Кінь", d="Одна з найдавніших порід коней у Кул-Тірасі, ці скакуни вели за собою не одну атаку ще в первісній боротьбі з друстами."},
    [1018] = {n="Переляканий В'ючний Мул", d="Цей бідолашний мул був у Друстварі, коли владу захопили відьми. Він побачив надто багато."},
    [1019] = {n="Голденмейн", d="Лорд Штормсонг наказав своїм поплічникам викрасти цього коня з маєтку Норвінгтонів у Тірагарді, бо запалав жагою до його розкішної золотої гриви."},
    [1025] = {n="Рій Свідомості", d="Справжнє єднання розумів."},
    [1026] = {n="Лютий Бойовий Василіск", d="Його подих гірший за його укус."},
    [1028] = {n="Механо-магнат Мод. II", d="Мод. II — оновлена модель, де ставку зроблено на комфорт і надійність, а не на вогневу міць."},
    [1030] = {n="Протодракон Грізного Гладіатора", d="Кажуть, протодракони чують страх. А ця закута в залізо потвора ним ЖИВИТЬСЯ."},
    [1031] = {n="Протодракон Зловісного Гладіатора", d="Кажуть, протодракони чують запах страху. Це закуте в залізо чудовисько ним ЖИВИТЬСЯ."},
    [1032] = {n="Протодракон Сумнозвісного Гладіатора", d="Кажуть, протодракони чують запах страху. Це закуте в залізо чудовисько ним ЖИВИТЬСЯ."},
    [1035] = {n="Протодракон Зіпсутого Гладіатора", d="Кажуть, протодракони чують запах страху. Це закуте в залізо чудовисько ним ЖИВИТЬСЯ."},
    [1038] = {n="Зандаларський Жахоріг", d="Зандалари пишаються тим, що першими навчилися вирощувати й приручати всіх найлютіших ящерів Азероту."},
    [1039] = {n="Могутній Караванний Брутозавр", d="Брутозаврів імперія Зандаларів використовує і як знаряддя війни, і як величезні рухомі торгові пости."},
    [1040] = {n="Гробничий Переслідувач", d="Цих лютих звірів ховають разом із королями, щоб вони несли своїх володарів крізь потойбіччя."},
    [1042] = {n="Мулокрилий Альбатрос", d="Один із найрідкісніших птахів на островах Великого Моря і жадана здобич для торговців, якщо їм вдасться його впіймати."},
    [1043] = {n="Куа'фон", d="Колись маленьке дитинча, яке дбайливий доглядач виплекав у могутнього птеродакса. Літати він так і не навчився."},
    [1044] = {n="Лютововк Маг'хар", d="Ці вовки родом із Дренору, і Маг'хари цінують їх за лютість, відданість, а ще за те, що до них приємно пригорнутися холодними зимовими ночами."},
    [1045] = {n="Лютий Бойовий Розкопит", d="Маг'хари вирощували розкопитів не лише як витривалих в'ючних тварин, а й як потужне знаряддя війни."},
    [1046] = {n="Баран Темної Кузні", d="Вірний скакун захисників Айронфорджа."},
    [1047] = {n="Баран Світанкової Кузні", d="Вірний скакун захисників Айронфорджа."},
    [1048] = {n="Темнозалізний пес магми", d="Гарячіших за нього псів просто не буває."},
    [1049] = {n="Чумний кажан Андерсіті", d="Один з останніх гігантських кажанів, що втекли з Андерсіті після облоги Лордерона."},
    [1050] = {n="Лютий Бойовий Річковий Звір", d="Попри свій вигляд, річкові звірі насправді одні з найнебезпечніших тварин Азероту."},
    [1051] = {n="Жахосплав", d="Корабель, не схожий на жодний інший, що тримається в повітрі завдяки дару незнаного бога глибин з обличчям кракена."},
    [1053] = {n="Краг Підгнилля", d="Вічний морок Підгнилля позбавив цього крага будь-якого забарвлення."},
    [1054] = {n="Гіпогриф Тельдрассилу", d="Один з останніх великих броньованих гіпогрифів, що врятувалися від пожежі Тельдрассилу. Він виніс у безпеку стількох останніх мешканців, скількох зміг, перш ніж упав від виснаження."},
    [1057] = {n="Кривавий Змій Назджатару", d="Жахливі змії, просякнуті псуванням, слугують їздовими тваринами для високопоставлених лейтенантів Н'зота у Великому морі."},
    [1058] = {n="Кобальтовий Птеррордакс", d="Ці птеродакси, ширяючи над узбережжями Зандалару, виглядають ворожі флоти."},
    [1059] = {n="Спійманий Болотяний Скрадач", d="Болотний підвид птеродаксів, відомий тим, що ласує молодими кровожерами."},
    [1060] = {n="Дюнодряпач Волдунаїв", d="Цих яскраво забарвлених літунів рідко вдається спіймати в дикій природі через їхню від природи недовірливу вдачу."},
    [1061] = {n="Кровороївник Експедиції", d="Осиротілий під час розгрому Кривавих Тролів, цей кровороївник пройшов перенавчання у доглядачів Таланджі."},
    [1062] = {n="Сутінковий Грифон Вейкреста", d="Поширені в темних лісах Друствару, ці грифони мовчазні й стрімкі. Здатність діяти як самостійно, так і їздовими тваринами робить їх придатними для засідок і раптових ударів."},
    [1063] = {n="Береговий Дозорець Штормсонгів", d="Берегові дозорці Штормсонгів літають у безперервних патрулях, наглядаючи за морем у пошуках небезпек, що насуваються."},
    [1064] = {n="Морський Розвідник Праудмурів", d="Лише кількох грифонів обирають морськими розвідниками, що діють із флагманських кораблів флоту. Їхня далека розвідка — невід'ємна частина панування Кул-Тіраса на морі."},
    [1166] = {n="Скат Великого Моря", d="Скати великого моря здатні долати багато миль під час своїх великих міграцій."},
    [1167] = {n="Морозний Інфернал", d="Ці крижані прислужники прийшли з невідомого виміру, що лежить далеко від цього світу."},
    [1168] = {n="Вогняний Затишний Скакун", d="Ці летючі створіння, мов грім, незримо мчать небесами. Яке щастя, що це показалося саме тобі!"},
    [1169] = {n="Прибійна Медуза", d="Час між укусом і тим, як тебе огорнуть та поглинуть, такий короткий, що варто двічі подумати, перш ніж плавати у Великому морі."},
    [1172] = {n="Косопащ Завойовника", d="Загартований у битвах панцир цього могутнього звіра здатен відбити навіть найважчий молот чи найгострішого списа."},
    [1173] = {n="Приборканий Високогірний Мустанг", d="Один із коней Араті, захоплений і приборканий завойовниками з Орди після падіння Стромґарда."},
    [1174] = {n="Високогірний мустанг", d="Звитяжний скакун нагір'я Араті, що не знає страху."},
    [1175] = {n="Сутінковий Месник", d="Мало відомо про долю сутінкової зграї драконів, хоча, схоже, вони й донині існують у чималій кількості в Грім-Батолі."},
    [1176] = {n="Скелеріг Стрибун Ущелин", d="Ці могутні стрибуни пристосувалися до острівного життя, навчившись ловити чайок, що шугають поміж скель і ущелин."},
    [1178] = {n="Вічний Пес Кіньшо", d="Кіньшо викував свого вічного охоронця з чистого золота й наділив його непохитністю самої землі."},
    [1179] = {n="Блідошкірий Жахоріг", d="Жахороги з блідою шкірою трапляються вкрай рідко, тож і коштують недешево."},
    [1180] = {n="Швидкий Раптор-Альбінос", d="Колись воїн Візербарків, звіровершник Кама, верхи на такому чудовиську сіяв кривавий жах і смерть по всьому Араті."},
    [1182] = {n="Ослик", d="Цього стійкого ослика, певно, викрали з Ньюстеда в Араті, і кобольди мали його з'їсти."},
    [1183] = {n="Черепокрад", d="А вона кмітлива дівчинка."},
    [1185] = {n="Лютокрил Візербарків", d="У Араті лишилася всього жменька цих велетенських кажанів, яких дбайливо вирощують лісові тролі Візербарки, що першими привели їх сюди."},
    [1190] = {n="Рисак Чистого Серця", d="Про існування цих рисаків відомо давно, та вони здружуються лише з тими, хто доклав чимало зусиль заради дружби."},
    [1191] = {n="Шалений Скверн-Кіготь", d="Легіон ставив досліди над зараженням найрізноманітніших тварин, як-от цього виду вогняних птахів із розпеченого світу."},
    [1192] = {n="Престижний Кровокований Рисак", d="Викуваний у вогняній ненависті, нащадок жаху й мрії, цей скакун живиться зерном, политим сльозами твоїх ворогів."},
    [1193] = {n="М'ясний Віз", d="Улюблена бойова одиниця Короля-Ліча — і за міць облогової зброї, і за приємний звук жбурнутого м'яса."},
    [1194] = {n="Лютий Білий Бойовий Шаблезуб", d="Спробуєш почухати йому черевце — сам напросишся на халепу."},
    [1195] = {n="Лютий Чорний Бойовий Шаблезуб", d="Єдине, що ці великі коти приносять додому в подарунок, — це відтяті кінцівки твоїх ворогів."},
    [1196] = {n="Лютий Чорний Кістяний Скакун", d="Ці кістяні скакуни не знають страху, не їдять зерна й здатні долати неймовірні відстані."},
    [1197] = {n="Лютий Білий Кістяний Скакун", d="Мало який інший спосіб вирушити в бій може похизуватися такою кількістю шипів і кісток."},
    [1198] = {n="Бойовий Скакун Кул-Тіраса", d="Військо Кул-Тіраса пишається своєю перевагою як на морі, завдяки величезному флоту, так і на суходолі, завдяки озброєній кінноті."},
    [1199] = {n="Чорнолап", d="Чорнолап мирно спав у зимовій сплячці, нікого не чіпаючи, аж раптом просто перед ним розгорнувся фронт війни."},
    [1200] = {n="Химера Ясенового Лісу", d="Калдораї часто використовували химер Ясенового Лісу, щоб руйнувати споруди в битвах проти людей, орків і нежиті."},
    [1201] = {n="Наляканий Кодо", d="Ніщо не лякає кодо так, як ведмідь із рогами."},
    [1203] = {n="Темно-Бурий Нічний Шаблезуб", d="Нічні шаблезуби — невід'ємна частина армії калдораї, що слугують водночас і верховою твариною, і зброєю для атаки."},
    [1204] = {n="Піщаний Нічний Шаблезуб", d="Рідкісне забарвлення для нічного шаблезуба, яке нечасто побачиш, тож мисливиці його дуже цінують."},
    [1205] = {n="Нічний Шаблезуб Калдораї", d="Зв'язок між нічним шаблезубом і його мисливцем чи мисливицею майже неможливо розірвати."},
    [1206] = {n="Синій Болотяний Стрибунець", d="Те чвакання за кожним його кроком? Це особлива риса, а не вада."},
    [1207] = {n="Жовтий Болотяний Стрибунець", d="Ніхто не плодить таких велетенських і слизьких нащадків, як Краг'ва Велетенський."},
    [1208] = {n="Морський Коник Солоних Вод", d="Ці велетенські морські коники від природи допитливі, тож їх часто можна побачити, коли вони нишпорять у затонулих кораблях у пошуках блискучих дрібничок."},
    [1209] = {n="Камінношкірий Старорог", d="Камінношкірі старороги — один з небагатьох видів лосів, що населяють острівний клімат, — мають тоншу шерсть, ніж більшість старорогів."},
    [1210] = {n="Кровожерне Жахокрило", d="Відступники надають перевагу цим кровожерним мисливцям — і за швидкість як верхового звіра, і за той гнітючий вплив, який вони мають на ворогів."},
    [1211] = {n="Налита Кров'ю Мисливиця", d="Якби вона не наїлася так досхочу, ти б її нізащо не впіймав."},
    [1212] = {n="Острівний Громолуск", d="Один із найбільших корінних видів драконів Азероту; цей підвид живиться майже виключно рибою. І рибалками."},
    [1213] = {n="Повстала Кобила", d="Щось жахливе сталося в загубленому містечку Гейвенсвуд."},
    [1214] = {n="Блакитнопанцирний Кролуск", d="Спійманий серед безлюдних пісків Вол'дуну, цей верховий звір напрочуд сумирний у неволі."},
    [1215] = {n="Рубінопанцирний Кролуск", d="Спійманий серед безлюдних пісків Вол'дуну, цей верховий звір напрочуд сумирний у неволі."},
    [1216] = {n="Місячний Шаблезуб Жриці", d="Колись цих витончених котів отримували лише верховні жриці Елуни, та нині вони мчать у бій із будь-яким поборником, служачи помсті."},
    [1217] = {n="G.M.O.D.", d="Кричуще оздоблений надмірною дозою ґоблінського шику, цей Механізм Смерті Ґаллівікс замовив, щоб перевершити Меккаторка в бою, а ще важливіше — у стилі."},
    [1218] = {n="Вітрожнець із Дазар'алору", d="Ширяючи високо над Битвою за Дазар'алор, ці звірі линуть до найхитріших із переможців."},
    [1219] = {n="Льодовикова Припливна Буря", d="Хоч Джайна володіє розмаїттям магічних сил, вона завжди найкраще вміла призивати могутніх елементалів води та криги."},
    [1220] = {n="Брюс", d="БРЮС!"},
    [1221] = {n="Гоґрус, Свиня Доброї Долі", d="Гоґруса вперше побачив імператор Шаохао на третій день своєї медитації, і пандарени вважають його за знак того, що добра доля приходить до тих, хто діє."},
    [1222] = {n="Лисячий Фамільяр", d="Надзвичайно розумні й допитливі створіння, ці лисоподібні істоти мандрували Великою Темною Безоднею і знайшли шлях до Азероту. Їх вабить до захисників Азероту, бо вони прагнуть пригод і товариства."},
    [1223] = {n="Сильверійський сновида", d="Одна художниця в магічному місті Даларані заснула над пензлем і уві сні малювала прекрасного пернатого дракона. Її витвір зійшов зі сторінки, і коли вона прокинулася, то знайшла його, що тихо спав поруч із нею."},
    [1224] = {n="Дивокрил 2.0", d="Не питай, що сталося з першим — технологія Мехагона все одно лишається ґномською технологією!"},
    [1225] = {n="Жахорог Хрестоносця", d="Вірний скакун святих хрестоносців Зандалару."},
    [1227] = {n="Повітряний модуль R-21/X", d="Особистий повітряний модуль короля Мехагона з висувною вибуховою гарматою та грілками для ніг."},
    [1229] = {n="Іржавий Механоповзун", d="Лампочка перевірки двигуна горить завжди — хвилюватися треба тоді, коли вона згасне."},
    [1230] = {n="Хвильовий Скат Розкутих", d="Розкуті мають природну спорідненість із мешканцями глибоких морів, які зазнали жорстокості від рук наг."},
    [1231] = {n="Анкоанський Хвильовий Скат", d="Анкоани роками воюють із нагами, і завдяки природній прихильності до моря приручення місцевих створінь стало для них цілком природною стратегією."},
    [1232] = {n="Азшарський Здутий Скат", d="Наги вирощували цих скатів у неволі, забираючи їхні газові органи для алхімії, що дозволяла нагам легше дихати повітрям."},
    [1237] = {n="Королівський Кусачий Дракон", d="Спіймані замолоду й виховані для служби мисливцям наг, кусачі дракони — вірні й люті супутники."},
    [1238] = {n="Клацкоспинний Шкряботун", d="Велетенські краби походять із Назджатару й є улюбленою їжею наг. Цей, певно, був добре доглянутий, щоб вирости таким великим."},
    [1239] = {n="Механокіт X-995", d="X-995 — це вершина налаштовуваного котячого робота-супутника."},
    [1240] = {n="Обсидіановий Світоруйнівник", d="\"Упродовж історії я мав багато імен, і всі їх вимовляли зі страхом: Нелтаріон, Ксаксас і багато інших. Та найкраще ти знатимеш мене як Дезвінга, бо саме такий я є! Я — згуба життя, темрява в історії, володар смерті, повелитель руйнування. І кажу тобі нині, і це правда: цей світ — мій!\" — Нелтаріон, Хранитель Землі"},
    [1242] = {n="Залізоіклий Володаря Звірів", d="Одна з приручених звірюк Дармака; її ікла здатні пробити навіть найміцнішу сталь Залізної Орди."},
    [1243] = {n="Бойовий Вовк Володаря Звірів", d="Одна з приручених звірюк Дармака; вирощений у горнилі розплавленого вогню, він не знає страху."},
    [1245] = {n="Кроволанковий Скакун", d="Викрадений зі стаєнь Араті, цей вогнесердий скакун тепер мчить під сідлом Орди."},
    [1246] = {n="Закутий у Залізо Морозокіготь", d="Спійманий у снігах Альтеракської Долини, цей кровожерливий мисливець тепер реве за Альянс."},
    [1247] = {n="Мехацикл Модель W", d="Стрімкий технологічний поступ нащадків Мімірона почався з появи нового механізму передач, що привело до таких див, як трагічно недовипущена Модель W."},
    [1248] = {n="Бродяга Звалища", d="Коли тобі справді кортить, щоб тебе помітили... і ти не проти прив'язати себе до велетенського, ледь зібраного докупи колеса."},
    [1249] = {n="Дитя Торкалі", d="Ця донька великого лоа лютоногів, Торкалі, ніколи не втрачала віри, що її опікун допоможе їй розкрити весь свій потенціал."},
    [1250] = {n="Моллі", d="Завдяки лагідній вдачі альпаки стають ідеальними супутниками для безстрашного шукача пригод."},
    [1252] = {n="Миротворець Мехагона", d="Береже мир, розриваючи тебе на шматки."},
    [1253] = {n="Скований з Брухту Мехапавук", d="Ти збудував його сам, тож маєш пишатися, хай навіть він димить, іскрить і гуркоче."},
    [1254] = {n="Резистор Іржоболта", d="На сидінні грубими літерами вирізьблено \"О П І Р\", а поряд — кілька значно непристойніших написів."},
    [1255] = {n="Кусач-дракон Глибинних Коралів", d="У воді кусач-дракон — тихий мисливець, а от на суходолі ховатися йому виходить значно гірше."},
    [1256] = {n="Кусач-дракон Заростей Водоростей", d="Коли кусач-дракон тебе вкусить, страшний не сам укус, а отрута, що починає роз'їдати рану."},
    [1257] = {n="Безшумний Планер", d="Гази, що від природи накопичуються в тілі цієї істоти, дозволяли їй виживати в глибинах, і ці ж гази допомагають їй легко ширяти в повітрі."},
    [1258] = {n="Фабіус", d="Він виринає з води, плавці ліниво колишуться на вітрі, поцілована сонцем луска мерехтить. Він... Фабіус."},
    [1259] = {n="Срібний Жеребець Припливу", d="Цього жеребця припливу зі сріблястою лускою привабив блиск здобичі у твоїй кишені."},
    [1260] = {n="Багряний Жеребець Припливу", d="Криваво-червоне забарвлення цих істот ідеально приховує їх серед великих коралових заростей."},
    [1262] = {n="Чорнолуский Шукач Глибин", d="Зграї жеребців припливу люто врізаються у здобич мускулястими грудьми, щоб її повалити."},
    [1265] = {n="Неспотворене Крило Порожнечі", d="Це поріддя Вексіони, очищене Вратіоном, походить зі Зграї з понівеченим минулим і непевним майбутнім."},
    [1266] = {n="Алебастровий Грозокіготь", d="Висічений каменярами Стормвінда, цей кам'яний грифон уособлює незламну відвагу Альянсу."},
    [1267] = {n="Алебастрове Громокриле", d="Висічений каменярами Оґриммара, цей кам'яний наїзник на вітрі — символ непохитної сили Орди."},
    [1269] = {n="Швидкий Примарний Глибинний Скат", d="Навіть мертвим час від часу треба підвезтися."},
    [1270] = {n="Швидкий Примарний Магнітольот", d="Навіть мертвим час від часу треба підвезтися."},
    [1271] = {n="Швидкий примарний броньований грифон", d="Навіть мертвим часом треба десь підвезтися."},
    [1272] = {n="Швидкий примарний птеррордакс", d="Навіть мертвим часом треба десь підвезтися."},
    [1277] = {n="Медовоспинна матір рою", d="Їй судилося стати королевою свого вулика, тож вона обстежує Кул-Тірас і Зандалар у пошуках придатної домівки, де розквітне нова колонія."},
    [1282] = {n="Чорний Змій Н'Зота", d="Чорні змії Н'Зота — провісники того, що його остаточне видіння втілиться в реальність. Лише ті слуги чи вороги, що здатні ступати цим простором, мають бодай якийсь шанс приборкати їх."},
    [1283] = {n="Механоход Мехагона", d="Найкраща їздова тварина, цілком логічно, слугує одразу кільком цілям — іноді треба і дістатися кудись, І дотягнутися до чогось високо, коли вже прибув на місце."},
    [1285] = {n="Гарчун Морозних Вовків", d="Вирощений кланом Морозних Вовків у горах Альтерак, привчений кусати дворфів."},
    [1286] = {n="Караванна Гієна", d="Навіс над цією мандрівницею дюн можна лишити у вашому таборі, якщо вам захочеться відчути вітер у власному хутрі."},
    [1287] = {n="Дослідницький джунглельот", d="Для тих випадків, коли доводиться робити аварійну посадку посеред незвіданого болота, бо це єдиний спосіб дістатися до того стародавнього храму."},
    [1288] = {n="Дослідницький дюноход", d="Похмурий дюноход легко довезе гурт дослідників до найближчих руїн і назад, навіть не потребуючи відпочинку."},
    [1289] = {n="Зачарований вічновирм", d="Аніма — фундаментальна сила, що просякає Тіньові Землі. Вона тече крізь багатьох істот, але нею також торгують, її виміняють і за неї б'ються."},
    [1290] = {n="Пискун-витівник", d="Місцеві в Напівпагорбі присягаються: щоразу, коли зникає партія зерна, кудись дівається сільський інструмент чи не дошукатися кошика ягід, можна почути пустотливе попискування — і воно нагадує сповільнитися й приймати те, що дає життя."},
    [1291] = {n="Щасливчик Юнь", d="Пандарени вірять, що варто лише потерти руками блискучу шкуру цього вола — і він дарує добробут; уся складність у тому, щоб його впіймати."},
    [1292] = {n="Бойовий Баран Грозового Списа", d="Вирощений кланом Грозового Списа в Альтеракських горах і навчений бити орків головою."},
    [1293] = {n="Всевидець Ні'алоти", d="Щоб знайти його, утопися в Колі Зір."},
    [1297] = {n="Кладка Ха-Лі", d="Виводок Ха-Лі почувається вільно в блакитних небесах Пандарії, полюючи на необачну здобич."},
    [1298] = {n="Ґаргон-Надієтрощій", d="Колись вона була вірною їздовою твариною лорда дому Брайарбейн, та згодом обернулася проти господаря і його почту. Тепер члени дому Брайарбейн пошепки переказують про темного гаргона, що чигає в засідці й навіть приманює вентирів, які наважуються заходити в найтемніші куточки Чашного кварталу Ревендрету."},
    [1299] = {n="Бойовий Гаргон Вреднік", d="Вірний гаргон принца Ренатала, Вреднік супроводжує його вже тисячоліттями. У своїй сінвірській броні Вреднік самою лише появою сіє жах серед усіх, хто його бачить, мчачи свого вершника в бій."},
    [1302] = {n="Рунний Олень Світломрії", d="Рунні олені даруються тим, хто присягнув служити Зимовій Королеві та Двору Ночі."},
    [1303] = {n="Зачарований Рунний Олень Світломрії", d="Величні рунні олені здатні своїми вигадливими рогами витягувати аніму з розсіяного світла Арденвельду. Аніма слугує їм за поживу й живить швидкість та магію рунного оленя."},
    [1304] = {n="Ловець Душ Пащеслужбовців", d="Ловців душ використовують, щоб вистежувати заблукані душі, які тікають від своєї темної долі через пустища, і вони одні з небагатьох істот, яким легко мандрувати Пащею."},
    [1305] = {n="Твердопанцирник Темної Нори", d="Хітин твердопанцирника Темної Нори достатньо міцний, щоб витримати мінометні снаряди й драконове полум'я. До того ж він залюбки пожирає все, що позбавлене аніми, якщо в цьому є потреба."},
    [1306] = {n="Прудкий Похмурокопит", d="Балади Арденвельду твердять, що народження похмуробігуна провіщає відхід особливо доброзичливого дикого бога. Тож побачити похмуробігуна — це водночас благословення і прокляття."},
    [1307] = {n="Сонцетанець", d="Цей осяяний сонцем скакун безтурботно й вільно мчить світловими променями."},
    [1309] = {n="Скрекотливий Анімокліщ", d="Ці надзвичайно спритні літуни стають чудовими їздовими тваринами, щойно їх навчать не висмоктувати з вершника кожну краплю аніми."},
    [1310] = {n="Жахливий Дредвінг", d="Гаріка Жахлива тероризувала мешканців Лісового округу, а з її загибеллю виводок тепер може нести цей жах і до тих, хто живе далеко за його межами."},
    [1311] = {n="Кістяно-білий хмарний змій", d="Кістяно-білих хмарних зміїв часто плутають із гуркотом грому, коли вони шалено мчать небесами."},
    [1312] = {n="Гігантський Ґррлок", d="Це найбільший мурлок, якого ти будь-коли бачив!"},
    [1313] = {n="Бойовий змій раджані", d="Люті супутники послідовників Ра-дена, бойові змії раджані — це сила, з якою варто рахуватися."},
    [1314] = {n="Дрейк Чотирьох Вітрів", d="Скелі вивітрюються, вогні згасають, та вітер лишається могутнім, хай скільки спливе часу. — Фаоріс"},
    [1315] = {n="Поштожер", d="Прокладаючи собі шлях крізь мережу Поштмейстера, цей змій Н'Зота позбавив Азерот його головного магічного листування."},
    [1317] = {n="Мародер Пустища", d="Більший за більшість родичів, цей стерв'ятник показав і хворим, і дужим звірам, чому варто боятися небес."},
    [1318] = {n="Небесний Жах Блукачів Пустища", d="Сумніватися в здібностях Небесного Жаху Блукачів Пустища — це швидкий спосіб недорахуватися кінцівки."},
    [1319] = {n="Злостивий Трутень", d="Трутні акірів бенкетують і на героях, і на боягузах, щоб поповнити свої лави."},
    [1320] = {n="Тіньоколючий Трутень", d="Порожнеча, желе та добряче напхане черево — це все, що потрібно цьому трутневі."},
    [1321] = {n="Лиховісний Рійник", d="Коли Порожнеча простягла свою длань, акіри постали за її жахливою подобою."},
    [1322] = {n="Звивистий Паразит", d="Він такий звивкий! Сама лиш його метушня видається хаотичною й тривожною."},
    [1324] = {n="Невловний прудкокопит", d="Лагідна вдача альпак робить їх ідеальними супутниками для безстрашного шукача пригод."},
    [1326] = {n="Пробуджений Свердлій Розуму", d="Зараз він може здаватися загрозливим, та насправді він доволі милий, коли спить."},
    [1327] = {n="Вірний Пес Рена", d="Псар Рен використовував свого найдужчого квілена, щоб той ніс його через Пандарію, поки він підкорював Долину для імперії могу."},
    [1328] = {n="Сінлао", d="Єдине, що сильніше за відданість квілена, — це його шалене прагнення вкрити свого господаря поцілунками."},
    [1329] = {n="Весняношерста Альпака", d="Лагідна вдача альпак робить їх ідеальними супутниками для безстрашного шукача пригод."},
    [1330] = {n="Зігрітий Сонцем Хутровик", d="Поява велетенських котів провіщає початок кінця для птахів Азероту."},
    [1332] = {n="Шовковистий Мерехтливий Метелик", d="Метелики Арденвельду відіграють важливу роль в екосистемі, переносячи спори, аніму й пилок з однієї частини лісу до іншої, даруючи поживу й розмаїття мешканцям, що живуть унизу."},
    [1346] = {n="Паролускатий спопелювач", d="Божевільний ґномський винахідник мріяв осідлати дракона, тож створив цю металеву потвору. Він живив її ув'язненим демоном, аби витворити «справжню драконову душу», та не пережив її запуску."},
    [1350] = {n="Колосальний Різницький Кіготь", d="Лише найстійкіші доглядачі стайні Малдраксусу здатні зламати волю колосальних різницьких кігтів, даруючи всім поборникам Невмирущої Армії грізного союзника в Тіньових Землях."},
    [1351] = {n="Лютий Бойовий Павук", d="Коли того, що ти відважний член Альянсу, не досить, щоб уселити в супротивника належний страх, додай велетенського павука."},
    [1354] = {n="Тінелистий Рунний Олень", d="Тінелистих рунних оленів Дике Полювання плекає як за їхню лють, так і за вроду. Вони без страху мчать у лігво будь-якого хижака."},
    [1355] = {n="Рунний Олень Пробудника", d="Рунні олені люблять лежати поблизу диких насінин. Пробудники вірять, що ті чують сни сплячих. Під час своєї варти ці олені виявляють цілу гаму почуттів, виказуючи сни чи жахіття духів усередині."},
    [1356] = {n="Рунний Олень Зимороджених", d="Рунних оленів зимороджених благословила сама Зимова Королева. Їхні руни яскраво спалахують, коли поблизу хижаки, попереджаючи все стадо."},
    [1357] = {n="Зачарований Тінелистий Руноолень", d="Тінелистий руноолень здатен забити рогами навіть таких могутніх істот, як матріарх гормів, захищаючи своє стадо. Дикі Ловці верхи на цих оленях вирушають у небезпечні закутки Тіньових Земель, коли їхні володіння треба боронити від тих, хто загрожує дикій природі."},
    [1358] = {n="Зачарований Руноолень Пробудника", d="Руноолені пробудників люто оберігають свої гаї дикого насіння. Коли гаї почали в'янути, багато рунооленів впало в шалену лють."},
    [1359] = {n="Зачарований Зимороджений Руноолень", d="Руноолені зиморождені — улюблена їздова тварина самої Зимової Королеви, і вона дарує таку істоту лише найвірнішим зі своїх підданих."},
    [1360] = {n="Бігун Мерехтливого Туману", d="Між пустотливими спріґанами й долинними бігунами панує природна ворожнеча. Жоден долинний бігун не дозволить спріґанові осідлати себе, бо відчуває їхню вроджену злостивість. Це лютить хитрунів-спріґанів, які отримують збочену втіху, влаштовуючи жорстокі витівки цим величним істотам."},
    [1361] = {n="Сутінковокрилий Арденметелик", d="Ці арденметелики полюбляють темні й вологі ліси північно-західного Арденвельду, де безупинно квітнуть колонії грибів."},
    [1362] = {n="Колючопащий Гаєжер", d="Вершники-спріґани прив'язують шматки позбавленого аніми сміття до кінців палиць перед своїми їздовими тваринами-гормами, щоб ними керувати. Це... недосконале мистецтво."},
    [1363] = {n="Пожирач Душ Грішного Гладіатора", d="Ця їздова тварина має схильність ласувати душами, вигнаними з Ревендрету."},
    [1364] = {n="Бойововирощений Тавралус", d="Воїни Малдраксуса захищають Тіньові Землі, і їм потрібна їздова тварина, водночас уміла й незворушна перед лицем нездоланної переваги ворога."},
    [1365] = {n="Чумогнильний Тавралус", d="Тавралуса вважають хоробрим, хоча вчені Малдраксуса вже давно гадають, чи не пояснюється його безстрашність просто крихітним розміром мозку."},
    [1366] = {n="Костекопитний Тавралус", d="Є чимало причин не ставати позаду тавралуса, і копита та схожі на батоги хвости — далеко не найвагоміші з них."},
    [1367] = {n="Обраний Тавралус", d="Навіть неброньований тавралус — цінний союзник у бою, адже його величезні роги здатні пробити навіть латний обладунок."},
    [1368] = {n="Броньований Бойововирощений Тавралус", d="Тавралусам, що служать арміям Малдраксуса, через виведення породи витравили будь-яке співчуття, і броню вони отримують лише тоді, коли доведуть, що жоден меч чи закляття не завадить їм донести вершника до перемоги."},
    [1369] = {n="Броньований Чумогнильний Тавралус", d="У повному обладунку тавралус здатен витримати неймовірну кількість ушкоджень, перш ніж упаде, що робить його цінним союзником у бою."},
    [1370] = {n="Броньований Костекопитний Тавралус", d="Улюблена їздова тварина Дому Обраних, тавралус стає лише лютішим і злішим, коли потрапляє в бій."},
    [1371] = {n="Броньований Обраний Тавралус", d="Тавралус має два хвости, і обидва геть необхідні, щоб відганяти набридливу дрібноту, як-от кровоблоху."},
    [1372] = {n="Пухирчастоспинний Кровоіклий", d="Дім Обраних навчає своїх їздових тварин у найрізноманітніших тяжких умовах, щоб у будь-якому бою вони ніколи не дрогнули."},
    [1373] = {n="Кривавошип", d="Нерісса розтоптала незліченні тіла верхи на Кривавошипі, коли підіймалася до влади як командирка військ, присяглих лічу, Дому Ритуалів."},
    [1374] = {n="Череповепр Костетята", d="Сабріель була відома безжальною вправністю, з якою вона розчленовувала ворогів, згодовуючи їхні кістки своєму вірному череповепру."},
    [1375] = {n="Моторошний Кровоіклий", d="Лише ті кровоіклі, що виживають у Змаганні Завоювання, вважаються гідними стати їздовою твариною Невмирущого Війська."},
    [1376] = {n="Сріблокрилий Жахокрил", d="Виведені ревендретським принцом Ренаталом, ці рідкісні жахокрили несамовито віддані й дозволяють наближатися до себе лише тим, кого сам принц визнав гідними."},
    [1377] = {n="Верескун з Валу", d="Гніздячись на валах Замку Натрія, ці велетенські жахокажани слугують вартовими й навчені знешкоджувати загрози, що наближаються до замку з повітря."},
    [1378] = {n="Жахокрил Жнеця", d="Жахокрили Жнеців не бояться присяглих Пащі й залюбки вгризаються зубами в усе, що загрожує Сінфоллу."},
    [1379] = {n="Літун Кінцеболота", d="Приваблені крізь портали, про які майже нічого не відомо, ці летючі пожирачі знайшли собі домівку в Кінцеболоті Ревендрету, живлячись прихованою анімою."},
    [1382] = {n="Ґаргон Інквізиції", d="Ґаргони інквізиторів — одні з найлютіших, яких будь-коли вирізьблювали. Заприсяглені прагнуть знову приборкати цих звірів і повернути їх до праведного обов'язку — допомагати в очищенні душ, а не до збочень, які чинили над ними руки інквізиторів."},
    [1384] = {n="Гаргон Гріхопаду", d="Гаргони — це віддані їздові тварини та супутники вентирів. Ренатал знайшов багатьох із них покинутими в Гріхопаді, де вони чекали на пробудження й передачу гідним членам ковенанту."},
    [1385] = {n="Склеповий Гаргон", d="Вірні гончаки Кураторки, ці гаргони патрулюють склепи та катакомби, перешкоджаючи як вторгненню, так і втечі."},
    [1387] = {n="Бойовий Гаргон Жадання", d="Графиня тримає невелику стайню вишукано оздоблених верхових гаргонів лише для себе. Не один суперник спокусився цією пишнотою собі на згубу, адже вона особисто наглядає за їхнім смертоносним вишколом."},
    [1388] = {n="Бойовий Гаргон-Надгробок", d="Уособлення нового відданого поріддя гаргонів, ці готові до бою звірі понесуть найвірніших соратників Ренатала в останні битви проти Тюремника."},
    [1389] = {n="Бойовий Гаргон Сілесса", d="Сілесса доблесно билася пліч-о-пліч зі своїм господарем під час великого вторгнення Світла. Після битви господар поставив її охороняти сховище неоціненної вартості."},
    [1391] = {n="Вірний Ненажера", d="Виповзаючи з тріщин між світами, пожирачі мають ненаситний апетит до аніми. Про їхнє походження відомо мало, та всі мешканці Тіньових Земель убачають у їхній нещодавній зухвалості ознаку кінця часів."},
    [1392] = {n="Блідий Кислотопаст", d="Кислота в сукровиці цієї істоти вицідила барву з її панцира, лишивши його разючого сніжно-білого відтінку."},
    [1393] = {n="Дикий Мерехтливохутрий Скрадач", d="Яскраво-зелена шерсть цього скрадача вирізняє його серед синіх і фіолетових барв Арденвельду, через що іншим його родичам набагато легше помітити його в нічних лісах."},
    [1394] = {n="Фалінкс Вірності", d="Декотрі з Піднесених тримають фалінкса як улюбленця. Хоч він і не такий пухнастий, як ларіон, зате значно менш схильний з'їсти інших ваших улюбленців."},
    [1395] = {n="Фалінкс Смирення", d="Фалінкс не приносить кинутих речей, хоча чому саме так — невідомо."},
    [1396] = {n="Фалінкс Відваги", d="Фалінкса вважають і гідним супутником, і спритним суперником, на якому можна випробувати свої рефлекси."},
    [1397] = {n="Колиска Дикого Зерня", d="Найдорогоцінніший вантаж усього Арденвельду — дикі зерна — дбайливо колисає цей з любов'ю створений візок. Він просякнутий анімою, що дозволяє йому ширяти над землею."},
    [1398] = {n="Фалінкс Чистоти", d="Про походження технології фалінксів відомо небагато, адже таємниці їхньої будови викладають радше як релігію, ніж як інженерну справу."},
    [1399] = {n="Вічний Фалінкс Чистоти", d="Броньований фалінкс — улюблений супутник наймогутніших воїнів Піднесених, адже в бою він і безстрашний, і нещадний."},
    [1400] = {n="Вічний Фалінкс Відваги", d="Щоб викувати одну з цих сяйливих їздових тварин, потрібно багато злитків ґільденіту, та сам лише їхній вигляд вартий усього часу, витраченого на видобуток."},
    [1401] = {n="Вічний Фалінкс Вірності", d="Диво інженерної майстерності розпорядників, броньований фалінкс — рідкісне й величне видовище."},
    [1402] = {n="Вічний Фалінкс Смирення", d="Коли викувано броньованого фалінкса, розпорядники стукають молотами один об одного на знак поваги до майстерності, потрібної для його створення."},
    [1404] = {n="Срібновітровий Ларіон", d="Цей дар срібних вітрів дістається лише тим, хто шукає мудрість Бастіону повсюди, не цураючись жодних зусиль."},
    [1405] = {n="Смертоступ Відновлення", d="Зі смертю Тюремника та піднесенням нового Арбітра Тіньокрай повертається до свого великого Призначення. Деякі смертоступи визнають роль, яку відіграли смертні герої, і ладні служити їм їздовими тваринами."},
    [1406] = {n="Мозкоікло", d="Мозкоікло, нащадок Костеікла, заслужило повагу Амарта Жнеця своїм невгамовним апетитом, навіть коли той порушував усі досліди, які прагнув провадити цей садистичний командувач."},
    [1407] = {n="Недозрілий Білуватокрил", d="Білуватокрили — необхідна сила в колі життя Тіньокраю, що в суворих умовах Малдраксуса є водночас і здобиччю, і хижаком."},
    [1408] = {n="Моторошний Білуватокрил", d="Білуватокрилів Малдраксуса цінують за вміння легко злітати в небеса Тіньокраю, даючи вершникові несподівану нагоду вдарити по ворогах чи підтримати союзників."},
    [1409] = {n="Костезшитий М'ясарок", d="Лише вправні зшивачі плоті, які довели свою майстерність над магією Малдраксуса, достатньо могутні, щоб створити смерторока такого розміру."},
    [1410] = {n="Громіздкий Смерторок", d="Смертороки — це зшиті потвори з покинутих нутрощів, кісток та органів, які не знадобилися для створення солдатів Дому Конструктів."},
    [1411] = {n="Хижий Чумарок", d="Невгамовний голод Ґіґера легендарний серед Дому Конструктів, і жоден звір не буває надто великим чи кістлявим, щоб не вміститися в його велетенський шлунок."},
    [1413] = {n="Безстрашний Сутінковий Бігун", d="Шлях Вознесіння — це непросте випробування, і ті, хто виявляє всі чесноти, дорогі серцю кіріанів, отримають належну винагороду."},
    [1414] = {n="Грішобіжниця Бленчі", d="За життя Бленчі здавалася лагідною, слухняною конячкою з чудовою вдачею та апетитом. Які ж лиходійства мусила вона потай скоїти, щоб заслужити місце серед засуджених душ Ревендрета?"},
    [1415] = {n="Деревний Ковтач", d="Деревина й листя, що ростуть на цій жабі, — природна частина її тіла, яка допомагає їй вбирати аніму з повітря, щоб живитися."},
    [1416] = {n="Бойовий кінь Присяжних Пащі", d="Доля всіх їздових коней."},
    [1417] = {n="Длань Грестимораку", d="Підступність Грестимораку була сумнозвісною: він зрадив свій народ, щоб здобути владу. Опинившись перед прокляттям у Пащі, він спробував повалити Тюремника... безглуздий вчинок, що приніс йому вічність страждань."},
    [1419] = {n="Гріхоторкнутий Смертохід", d="Викуваний із гріхів незліченних диявольських мешканців підземель. Лише ті, хто має вправність їх подолати, можуть тримати його повід."},
    [1420] = {n="Сутінковий Серпоріг", d="Сутінкові ґорми — найлагідніші з усіх ґормів, та водночас у них виростають найбільші роги й мандибули. Мабуть, вони такі сумирні саме тому, що інші створіння уникають їх дратувати."},
    [1421] = {n="Двірський Грішноскак", d="Грішноскаки колись були скакунами темних душ, яких приносило до Ревендрета у вирі або їхніх власних гріхів, або гріхів їхніх господарів. Хоч дехто й обрав волю, багато хто й далі служить пітьмі по смерті так само, як служив за життя."},
    [1422] = {n="Бойовозшитий Темний Гончак", d="Цих бойових гончаків створює Дім Конструктів, щоб вони несли будь-якого вершника в самісінький вир битви, дорогою шматуючи й роздираючи ворожих верхівців."},
    [1423] = {n="Темногрива Буревію", d="Зреченці та їхні їздові тварини набувають похмурішого вигляду, щойно відрікаються від шляху, накресленого Архонтом. Хоч Темногрива Буревію й досить приборкана, щоб на ній їздити, вона має шалено незалежну вдачу."},
    [1424] = {n="Снігова Буря", d="Він прийшов із криги та снігу, під сонце Азерота, куди ступають шукачі пригод."},
    [1425] = {n="Позолочений Никалець", d="Могутній ларіон — найгрізніший хижак Бастіону, та це не заважає йому насолоджуватися приємним сном на сонячних луках."},
    [1426] = {n="Піднесена Небогрива", d="Лише ті, хто довів свою звитягу проти об'єднаної могутності Піднесених, зможуть осідлати цю їздову тварину."},
    [1428] = {n="Бурштиновий Арденметелик", d="Яскраво-помаранчевий відтінок бурштинового арденмотиля попереджає хижаків, що поїдати його небезпечно. Той, хто з'їсть таку істоту, поринає в сон без сновидінь на довгі роки."},
    [1429] = {n="Барвисте Тріпокриле", d="Ці м'ятно-зелені метелики дуже привітні. Особливо вони полюбляють, коли їм енергійно вичісують пушок на голові. А ще вони люблять музику та поезію."},
    [1430] = {n="Мисливець Пустельнокрил", d="Служачи великому Призначенню, мисливці-пустельнокрили були створені, щоб наповнювати далекі небеса забутих королівств Тіньових Земель."},
    [1431] = {n="Блідий Величний Цервід", d="Дивлячись на цих величних створінь, неважко уявити, як образ цервідів утілився в оленів, що блукають Азеротом та іншими світами смертних."},
    [1433] = {n="Веспоїдна Тріпотушка", d="Тріпотушка — це переросла робітниця-веспоїд, створена, щоб нести вершника. Замість того щоб коритися королеві, вона в усьому покладається на провід свого вершника."},
    [1434] = {n="Глибозоряний Аурелід", d="Один з останніх уцілілих поліпів невловимої істоти, цей аурелід почувається у воді так само вільно, як і в повітрі."},
    [1436] = {n="Загартований у Битвах Аквілон", d="Аквілон може стати цінним союзником у бою, адже його здібності переважають здібності фалінкса."},
    [1437] = {n="Бойовий Військовий Пес", d="Військові пси знаходять спокій у битві, тож Змагання Завоювання — досконале місце, де можна побачити, як ці звірі відточують свою майстерність."},
    [1438] = {n="Бульбастий Некроскат", d="Некроскати Малдраксуса воліють збиратися довкола величезних гнилих грибів цього краю."},
    [1439] = {n="Уражений Некроскат", d="Некроскати відкладають яйця невеликими гронами поміж пластинок і западин у тілах гнилих грибних наростів."},
    [1440] = {n="Заразний Некроскат", d="Коли некроскат вилуплюється, спори розлітаються навсібіч, лишаючи по собі справжній безлад."},
    [1441] = {n="Зв'язаний Тіньовий Гончак", d="Створений завдяки розшифруванню й застосуванню могутньої рунічної магії, цей Тіньовий Гончак прив'язаний до свого творця."},
    [1442] = {n="Коридорний Плазун", d="Віддані гончаки Тюремника скрадаються коридорами, винюхуючи запах душ."},
    [1443] = {n="Ненажерливий Пожирач", d="Вважається, що пожирачі походять із Межипростору — простору між землями Тіньових земель, який мало хто наважився дослідити."},
    [1444] = {n="Смарагдовий Фазовий Мисливець", d="Походячи від виду, що вже й так досконало володів природним маскуванням, ці створіння завдяки потойбічним енергіям, які перетворили Дренор на Аутленд, отримали здатність переміщатися крізь простір."},
    [1445] = {n="Слизовий Змій", d="Це таємниче створіння ховається під слизовими озерцями Чумопаду. Ніхто не знає, звідки воно взялося."},
    [1446] = {n="Механопланер Тазавеша", d="Посередники всіх мастей користуються цими планерами, щоб подорожувати Тазавешем і схожими сусідніми форпостами, а також перевозити свій товар."},
    [1448] = {n="Серенада", d="Ці прекрасні гелікіди з'являються лише вночі. Коли вони задоволені, їхні мушлі бринять радісною мелодією."},
    [1449] = {n="Володар Трупних Мух", d="Щоб стати Володарем Трупних Мух, доведеться відкласти БЕЗЛІЧ яєць."},
    [1450] = {n="Ширяюче Гострокриле", d="Шкура гострокрилого легка, тож воно здатне літати, але водночас доволі міцна, що дає змогу пережити дорогу до Пащі."},
    [1451] = {n="Лютий Бойовий Квакун", d="Ці створіння так захоплено кидаються в бій, що видають квакання, дуже схоже на «ЗА ОРДУ!»"},
    [1454] = {n="Приборканий Шматувальник", d="Щоб приборкати пожирача, потрібно лише трохи аніми й чимало терпіння. І чимало цілющих зіль."},
    [1455] = {n="Бериловий Колючошкур", d="Цим колючошкурам легко ховатися в чагарнику, тож приборканих особин зустріти вдається рідко."},
    [1456] = {n="Сапфіровий Небесний Палахкокрил", d="Ці сяйливо-сині птахи палають яскравіше (і гарячіше) за своїх помаранчевих родичів, хоча походження і тих, і тих лишається загадкою."},
    [1458] = {n="Мандрівний Прадавень", d="Незламні захисники лісів Азероту, прадавні відомі також своїми пишними кронами листя, що міняють колір зі зміною пір року."},
    [1459] = {n="Лютий Бойовий Горм", d="Горми обожнюють поїдати трупи твоїх ворогів, тож цей вибір видавався цілком природним."},
    [1465] = {n="Лютий Бойовий Переслідувач", d="Розчави Орду на порох, осідлавши величного протоформного вовка! За Альянс!"},
    [1467] = {n="Шляхетний Бруффалон", d="Це велика честь — коли тобі довіряють одного з вірних мисливських супутників маруків. Цей бруффалон надійний і стійкий за будь-яких негараздів."},
    [1468] = {n="Бурштинова Шурхокрилка", d="Подарунок від Дідуся Вуса для Торгового Поста — бурштинові шурхокрилки напрочуд сумирні."},
    [1469] = {n="Магмамушля", d="Хто тут гарненький новоскутий равлик, зроблений цілком зі стихійної лави? Це ти! Так, саме ти!"},
    [1471] = {n="Помста", d="Сильвана втратила частину себе того дня, коли Артас забрав її життя, і темрява всередині неї розрослася, заповнивши порожнечу."},
    [1474] = {n="Дарований Ватажок Зграї Громохребтів", d="Подарунок від Мерітри, яка благословила цих громохребтів, щоб клани маруків, хоч би куди вони мандрували, завжди були під захистом зеленої зграї драконів."},
    [1475] = {n="Рука Бахметри", d="Найлихіша й найжорстокіша з-поміж родичів, Бахметра зазнала всієї повноти кар Вигнанця, перш ніж упала."},
    [1476] = {n="Ногоруб Дикого Полювання", d="Влившись у поріділі лави Дикого Полювання, вершники оленят швидко збагнули, що могутні щелепи ґорма ідеально підходять, щоб косити щільні ворожі ряди в ближньому бою."},
    [1477] = {n="Невмирущий Темний Гончак", d="Частини Невмирущого Темного Гончака прикрашали чимало полів битв, та ця остання битва, можливо, стала першою, де вони всі билися разом."},
    [1478] = {n="Небошкірий Рогоступ", d="Нестабільність штормів первісників у можливих часових лініях іноді змушує істот вбирати в себе енергію самих цих штормів. Такі істоти зазвичай лагідні до тих, хто здатен встояти проти люті цих хрономатичних аномалій."},
    [1480] = {n="Пожирач Душ Розкутого Гладіатора", d="Погляд цього пожирача душ тривожить тебе. Краще не дивитися йому в очі надто довго."},
    [1481] = {n="Механопланер Майстра Картелю", d="Лише найбагатші очільники картелів можуть дозволити собі метали, потрібні для виготовлення Механопланера Майстра Картелю."},
    [1482] = {n="Механопланер Повіреного Ксай", d="Картель Ксай торгує багатьма валютами, та для його внутрішнього кола жодна з них не цінніша за вірність."},
    [1483] = {n="Механопланер Вандала", d="Рідкісніший, особливо налаштований планер, який найчастіше використовують для таємних зустрічей. Його безшумність робить його майже невловимим, тож він став улюбленим знаряддям тих, хто діє в тіні."},
    [1484] = {n="Дикун Арденвельду", d="Коли аніма знову тече до далеких гаїв Арденвельду, дикуни прокидаються й обережно вибираються зі своїх нір у кронах дерев."},
    [1485] = {n="Осінній Дикун", d="Дикуни — доброзичливі магічні створіння Арденвельду, яких ваблять сильні й чисті душі."},
    [1486] = {n="Зимовий Дикун", d="У битві дикуни слугують загонами підтримки: оберігають союзників і знешкоджують ворожу магію."},
    [1487] = {n="Літній Дикун", d="Упертий і норовливий, цей дикун вірний лише небагатьом. Але з тими небагатьма зв'язується на все життя."},
    [1489] = {n="Обсидіанове Могильнокрило", d="У потьмянілих небесах Ревендрету ти не помітиш наближення цих створінь, аж доки не стане надто пізно."},
    [1490] = {n="Могильнокрило з Сінфолу", d="Тепер, коли аніма знову струмує в Сінфолі, Каменотесці вдалося наситити нею цих Камінароджених, зробивши їх цінними союзниками в прийдешніх битвах."},
    [1491] = {n="Бліде Могильнокрило", d="Могильнокрилі не знають страху і майже невразливі — ідеальні для штурму Утроби."},
    [1492] = {n="Елізійський Аквілон", d="Тепер, коли аніма знову струмує до Вічної Кузні в Бастіоні, плани аквілона-центуріона можна втілити знову."},
    [1493] = {n="Аквілон Зреченого", d="Спершу їх створили Зречені за вкраденими кресленнями, та нині ці могутні центуріони здобувають собі славу по всьому Темному Краю."},
    [1494] = {n="Аквілон Піднесеного", d="Аквілон здатен швидко переносити з місця на місце аспірантів, управителів і навіть піднесених. Що поробиш, інколи крила втомлюються."},
    [1495] = {n="Малдраксуська трупна муха", d="Колись трупні мухи водилися по всьому Малдраксусу, та багато з них вимерло без аніми. Тепер, коли аніма знову струмує, вони роями повертаються."},
    [1496] = {n="Велична трупна муха", d="Лише війська Малдраксуса здатні назвати трупну муху «величною»."},
    [1497] = {n="Рій бойовища", d="Трупних мух нездоланно вабить запах мертвих тіл, і вони злітаються на бойовище, щойно впаде перший убитий."},
    [1500] = {n="Сутінковий Скакун Святилища", d="Лише найсильнішим поплічникам Тюремника даровано цих скакунів, щоб ті ширяли залами Вежі."},
    [1501] = {n="Прив'язаний Сутінковий Скакун", d="Ве'нарі знає чимало способів скрадатися Утробою і руйнувати плани Тюремника, зокрема й підкоряти його ж власних слуг."},
    [1502] = {n="Полеглий Скакун", d="Крики скакуна лунають Утробою, доки він мчить нескінченними перегонами по землі, навіки шукаючи порятунку від безкінечних мук, які змушений терпіти."},
    [1503] = {n="Рука Нілганімата", d="З усіх велетнів, що насмілилися кинути виклик Тюремникові, Нілганімат був найбундючнішим. За цей переступ відтяту руку велетня сховали за пеленою мук, а персні, здатні прикликати її назад, розкидали по всій Утробі."},
    [1504] = {n="Рука Саларанги", d="Саларанга була найхитрішою з-поміж свого роду й переховувалася серед Звіриних Нор. Вона вдарила по Вигнанцю з ордою союзних звірів. Та це не мало жодного значення."},
    [1505] = {n="Бурштиновий Колючошкур", d="Яскраві барви кортіанської фауни свідчать про те, що ці створіння або майже не мають хижаків, або достатньо міцні, щоб дати відсіч."},
    [1506] = {n="Багряний Колючошкур", d="Коли Кортію затягнуло в Пащу, вижило лише кілька витривалих видів."},
    [1507] = {n="Темнолап", d="Старший колючошкур Темнолап був доволі смирним і приязним до кортійців. Вважалося, що він загинув під час катастрофи."},
    [1508] = {n="Люте Гострокриле", d="Гострокрилі зазвичай тримаються осторонь інших кортіанських видів, але з часом і терпінням їх теж можна приборкати."},
    [1509] = {n="Гранатове Гострокриле", d="Колись Кортія славилася своїми яскраво-червоними квітами. Кілька видів були відомі тим, що поїдали їх або качалися в них, через що набували яскраво-червоного забарвлення."},
    [1510] = {n="Сутінкове Гострокриле", d="Гострокрилих можна побачити по всій Кортії — вони мостять гнізда на високих пагорбах і на деревах."},
    [1511] = {n="Мейлі Мандрівниця", d="Цікава й допитлива олениця, вона не хоче тривожити свого господаря — просто легко відволікається. Особливо ж від усього нового, що можна побачити в Кортії."},
    [1513] = {n="Оповідь Сержанта", d="Стривай-но, Сержант не такий уже й великий — мабуть, хтось у таверні Hearthstone наплів небилиць..."},
    [1514] = {n="Лютий Шматувальник", d="Можна подумати, що приборкати скажену їздову тварину складно, та коли навчишся скеровувати її шал у потрібному напрямку, вона стане навіть доволі корисною."},
    [1517] = {n="Приборкана Хуртовина", d="Сніжний, морозний друг, поцяткований інеєм — для крижаних розваг."},
    [1520] = {n="Душескручений Смертохід", d="Ревучий вир змучених душ, на якому їздять лише ті, хто бажає продемонструвати свою неабияку витривалість до болю й страждань."},
    [1521] = {n="Гіпогриф Вал'шари", d="Ці величні гіпогрифи ближчі до створінь Смарагдового Сну, ніж будь-який інший мешканець Азероту, і нелегко прив'язуються до вершника."},
    [1522] = {n="Серцесвітлий Вомбата", d="Осяянні шанують усі творіння Перших, та для багатьох вомбати Зерет-Мортісу найулюбленіші з усіх. Ці створіння — водночас і надійні в'ючні тварини, і любі супутники."},
    [1523] = {n="Допитливий Кристалонюх", d="Більшість вомбат полюбляють рити тунелі під землею, але ці нюхачі, схоже, наділені безпомильним чуттям знаходити кристали, заховані глибоко в надрах, і збираються довкола великих покладів."},
    [1524] = {n="Затемнений Вомбата", d="Креслення для створення цих затемнених вомбат, схоже, з'явилося як відповідь на вторгнення прислужників Пащі. Народжені з нього вомбати виглядають інакше — темнішими, схожими на загарбників, — та поводяться як завжди."},
    [1525] = {n="Оздоблений Вомбата", d="Осяянні вважають вомбат червоного забарвлення щасливим знаком. Адже саме червоний вомбата був поряд, коли вони вперше прибули до Зерет-Мортісу."},
    [1526] = {n="Смертобіг", d="Ці дикі олені знаходять справжній спокій лише тоді, коли біжать землями Смерті — чи поміж ними."},
    [1528] = {n="Розколотий Зеретскакун", d="Хоч би яким колись було призначення цих оленів, його давно забуто. Вони не підкорені, та їх осквернила непередбачена присутність прислужників Пащі у священному царстві Зерет-Мортіс."},
    [1529] = {n="Помазаний Протоолень", d="Лише найшанованішим серед Осяянних довіряють поводи цього рідкісного оленя."},
    [1531] = {n="Вен Ло, Край Ріки", d="Ріки Пандарії, як і Вен Ло, мають непередбачувану вдачу. Вони можуть лишатися спокійними, даючи воду полям, або вийти з берегів, несучи руїну. Вен Ло нагадує нам, що ми мусимо пристосовуватися до випробувань життя."},
    [1532] = {n="Летюча Чарокнига", d="У забутих глибинах бібліотеки Даларану знайшли цей величезний фоліант, що шалено пурхав по кімнаті. Розгорни сторінки цієї просякнутої арканною магією книги й вирушай у магічну пригоду."},
    [1533] = {n="Викуваний Злолетун", d="Ніщо не дає такого гострого відчуття життя, як політ царством Смерті на спині істоти, яка тебе ненавидить."},
    [1534] = {n="Канюк", d="Бзз бзз бзз, бзз бзз! Бзз бзз бзз бзз бзз. Бзз бзз бзз, бзз бзз бзз."},
    [1535] = {n="Бронзокрилий Веспоїд", d="Бронзокрилі веспоїди — це результат спроби синтезувати королеву веспоїдів без жодного іншого члена нового вулика. Хоча жодному смертному ще не вдалося розгадати, як синтезувати цілий вулик, бронзокрилі й самі по собі є надійними їздовими тваринами."},
    [1536] = {n="Пащепристосований Раптора", d="Після вторгнення Тюремника Зерет Мортіс синтезувала нових рапторів, здатних опиратися згубному впливу Пащі."},
    [1537] = {n="Стрімкокрилий Раптора", d="Стрімкокрилий раптора — одна з найлютіших версій свого виду, чудово пристосована до своєї екологічної ніші. Не потребуючи жодних додаткових змін, ті, кого синтезують нині, нічим не відрізняються від створених у минулому."},
    [1538] = {n="Бронзовий Гелікід", d="Деякі гелікіди Зерет Мортіс мають дивно металеві черепашки. Зазвичай вони бронзового кольору, що нічим не відрізняється від металу, з яким упорається будь-який гірник-початківець, — от тільки будова цієї істоти далеко переважає вміння будь-якого новачка."},
    [1539] = {n="Невдалий Прототип Прудкопода", d="Цю істоту створили не Першостворені, а невідома істота, яка намагалася зробити дуже швидкого бігуна. Зайве й казати, що спроба провалилася, бо ця їздова тварина надзвичайно повільна."},
    [1540] = {n="Багряний Гелікід", d="Незвичний червонуватий відтінок цього гелікіда — вочевидь навмисна риса його будови, але єдина інша відмінність між ним та іншими гелікідами полягає в дивовижній відсутності будь-якого слизу."},
    [1541] = {n="Повзун Генези", d="Просвітлені, що спостерігали за тарахнідами, вважають, що цей різновид може бути одним із перших створінь, які будь-коли ступали землями Зерет Мортіс."},
    [1542] = {n="Тарахнідний Повзун", d="Ці тарахніди мешкають у найтемніших закутках Зерет Мортіс і виходять лише на полювання (або іноді — щоб понести вершника на собі)."},
    [1543] = {n="Невимовна Дряпачка", d="Ці тарахніди рухаються з метою, незбагненною для інших, відповідаючи лише на вищий поклик. Хоч би яким він був, схоже, він включає звичну допомогу смертним, яким потрібна їздова тварина. Принаймні поки що."},
    [1544] = {n="Спустошений Смертохід", d="Сира вируюча енергія, зібрана в єдину суцільну форму, скориться лише волі тих, хто достатньо сильний, щоб її приборкати."},
    [1545] = {n="Божественний Поцілунок Он'агри", d="...наче його привітав сам вітер."},
    [1546] = {n="Оттук Торговця з Іскаари", d="Купуючи оттука в Таттукіаки, ні в чому не можна бути певним. Принаймні вони милі."},
    [1547] = {n="Золотопанцирний Буфонід", d="Цей броньований буфонід завжди готовий стрибнути в бій... якщо тільки цей бій справді дуже-дуже близько. У скруті він може стрибнути кілька разів і зрештою дістатися до бою."},
    [1549] = {n="Мерехтливий Ауралід", d="Хоч колись його було створено, щоб боронити Гробницю Перших, нині, коли його головне призначення виконано, він слухняно кориться твоїм наказам."},
    [1550] = {n="Глибинний Переслідувач", d="Кількох із цих медуз вивезли із Зерет-Мортіса, але вони загубилися, коли корабель браконьєрів затонув. Вони знайшли новий дім у глибинах Великого Моря."},
    [1551] = {n="Загадковий Ауралід", d="Шифри Перших недоступні розумінню жодного смертного. Дивний вплив цієї мови полягає в тому, що з невідомих причин деяких ауралідів тягне до смертних, які прагнуть розгадати її таємницю."},
    [1552] = {n="Карцинізований Зеретський Скакун", d="Ті нечисленні з цих загадкових створінь, що ще лишилися, видаються неймовірно старими, майже позачасовими. Можливо, їх створили самі Перші, адже досі не знайдено жодної схеми, за якою їх можна було б синтезувати."},
    [1553] = {n="Звільнений Слайверн", d="Через його надмірну лють важко це помітити, але насправді цей слайверн радий, що більше не належить ґнолам."},
    [1556] = {n="Сплутаний Сноткач", d="Останні зі сплячих нарешті прокидаються, повертаючи сни драконів на ці землі."},
    [1563] = {n="Високогірний Дракон", d="Дракони Лазурового Простору дотримуються суворого особистого кодексу честі, наново досліджуючи острови."},
    [1564] = {n="Колосальна Душокрая Пащуряча", d="Неймовірна звитяга, яку ти виявив у Вежі Тюремника, вселила в це грізне створіння достатньо поваги, щоб його можна було використати як їздову тварину."},
    [1565] = {n="Колосальна Тінешкіра Пащуряча", d="Ця тривожно велика пащуряча — аномалія серед свого виду. Такі колосальні пащурячі ховаються лише в найдальших і найтемніших куточках Торгаста."},
    [1566] = {n="Колосальна Чорнокігтя Пащуряча", d="Це люте й хитре створіння виросло до своїх вражаючих розмірів, поглинаючи не лише ослаблені душі у Вежі Тюремника, а й беззахисних пащезв'язаних."},
    [1568] = {n="Загартований Світлом Руїноступ", d="Вірний скакун Загартованих Світлом Дренеїв."},
    [1569] = {n="Терпляча Жабоїда", d="Деякі жабоїди здатні годинами чи навіть днями сидіти нерухомо, якщо їх не турбувати. На щастя, вони достатньо поступливі, щоб не заперечувати, коли вершникові кортить рушати в дорогу частіше."},
    [1570] = {n="Прототип Стрибуна", d="Стародавнє креслення дозволяє втілити цей ранній, але цілком робочий зразок жабоїда."},
    [1571] = {n="Рудувата Жабоїда", d="Рудувата масть — рідкість серед жабоїдів. Зазвичай її можна побачити лише в особин, заплямованих іншими космічними силами, або синтезованих за химерним кресленням, що породжує саме цей колір."},
    [1572] = {n="Пожирач Душ Космічного Гладіатора", d="Погляд цього пожирача душ непокоїть тебе. Краще не дивитися йому в очі надто довго."},
    [1573] = {n="Пурпуровий Хмарний Змій", d="Пурпурові хмарні змії лагідніші за своїх родичів і відомі тим, що міцно прив'язуються до своїх вершників."},
    [1574] = {n="Шкарубкий Повзун", d="Цей рідкісний велетенський краб облишив свої безглузді морські мандри в глибинах і вирушив досліджувати суходіл."},
    [1575] = {n="Квакун", d="Старший (і чомусь ще галасливіший) брат Скрекотуна, схоже, терпить твою присутність. Поки що. Краще запасись сухариками, доки ще маєш нагоду."},
    [1576] = {n="Джиґлсворт ст.", d="Незрозуміло, як сідло тримається на спині цього колишнього котячого друга, але Дім Чуми якось цього домігся. Наука."},
    [1577] = {n="Аш'адар, Провісник Світанку", d="Легенди калдорай шепочуть про невтомного мисливця, що никає серед найглибших тіней Калімдору й ніколи не спить. У сяйві сонця чи місяця Аш'адар тепер полює разом із тобою."},
    [1578] = {n="[DND] Тестовий Верхівець JZB"},
    [1579] = {n="Хвилескат Кораловий Хижак", d="Цей вид скатів, схоже, пристосувався вистежувати здобич серед яскравих коралів морських глибин."},
    [1580] = {n="Серцевірний Вовчик", d="Від самої миті своєї появи цей безпритульний вовк не знав до тебе нічого, окрім найглибшої прихильності й відданості."},
    [1581] = {n="Насичений Нетром Велетворм", d="Мало хто з манавирмів знаходить досить стабільні джерела арканної сили, щоб досягти такого розміру. Апетит велетворма до мани не має рівних."},
    [1582] = {n="Люта Зелена Бойова Черепаха", d="Черепаха надто повільна, щоб наздогнати ворогів? Просто додай гармат. Ніщо не втече від гармати."},
    [1583] = {n="Броньований Облоговий Кодо", d="Лише найсильніших і найбезстрашніших кодо можна вишколити на живу облогову зброю. Навіть найвищі мури не стримають їх надовго."},
    [1584] = {n="Колосальний Чумоплюй-Пащур", d="Ці гризуни стали сумнозвісними вартовими Іски, що розвідують Пащу й розносять її чуму. За їхньою появою йде лише руїна."},
    [1585] = {n="Колосальний Привидозв'язаний Пащур", d="Наповнені енергією змучених душ, ці створіння перейняли примарні здібності, що роблять їх вельми невловимими."},
    [1586] = {n="Броньований Золотий Птерордакс", d="Розмальовані й оздоблені золотом, ці птерордакси патрулюють небеса над гробницею Атал'Дазару."},
    [1587] = {n="Наглядач Зерет", d="Загадкова й відсторонена, ця конструкція Перших ширяє на витонченому потоці досконалого геометричного розуміння."},
    [1588] = {n="Звивистий Зміїстий Дрейк", d="Ці дрейки почуваються як удома і в глибинах землі, і на безкраїх просторах неба."},
    [1589] = {n="Оновлений Протодрак", d="Коли острови пробуджуються, ці протодраки відповідають на поклик линути в небеса поруч зі смертними."},
    [1590] = {n="Вітроносний Велоцидрейк", d="Довгі пазурі велоцідрейка дають йому перевагу на рівнинах."},
    [1591] = {n="Скельний Дикодрейк", d="Часто гніздячись на крутих урвищах Талдраззуса, у час небезпеки вони стрімко злітають у небо."},
    [1594] = {n="Джейд, Осяйний Провидець", d="Присутність цього величного пандаренського кролячого духа дарує радість і щастя та вважається чудовою прикметою. Легенда каже, що в його очах можна вгледіти найбільше щастя твого життя, навіть якщо воно ще попереду."},
    [1595] = {n="Небесно-блакитний Болотний Стрибунець", d="Коли звістка про Торговий Пост дісталася навіть глибин Жаб'ячого Багна, вихід Ґоттума на ринки експорту став неминучим."},
    [1596] = {n="Амальгама Люті", d="Грізний звір, на якому їздив сам Астарот, тепер скоряється твоїм наказам."},
    [1597] = {n="Грімгаул", d="Відомий також як Полум'яний Гавкун, Подавач Вогняного, Найкращий Друг Розплавленого Ядра, Кузнепес Максимус, Найкращий Вогняний Хлопчина та «ой леле, це що, СОКИРА в нього на морді?!»"},
    [1599] = {n="Пожирач Душ Вічного Гладіатора", d="Погляд цього пожирача душ непокоїть тебе. Краще не дивися йому в очі надто довго."},
    [1600] = {n="Невловний Смарагдовий Яструбоступ", d="Багато років його ніхто не бачив, та цей яскраво забарвлений яструбоступ вийшов зі сховку, щоб допомогти захистити Примарні землі від Погибелі. Його звитяга сяє так само сліпуче, як і його пір'я."},
    [1602] = {n="Береговий Планер Тускарів", d="Тускари давно зрозуміли, що деякі кістки морських істот, на яких вони полювали, легкі й плавучі, а тому чудово годяться як матеріал для планерів."},
    [1603] = {n="Підземний Магмамонт", d="Пробуджений після довгого сну, цей звір ще ніколи не бачив денного світла."},
    [1605] = {n="Тестова Модель Дрейка Драконових Островів", d="NYI"},
    [1607] = {n="Швидкий Примарний Дрейк", d="Навіть мертвим часом потрібно когось підвезти."},
    [1612] = {n="Вірний Магмамонт", d="Звільнений від каляші й приборканий твоєю кмітливістю (та твоєю збруєю), цей магмамонт готовий чавити лаву всюди, куди б ти не схотів вирушити."},
    [1614] = {n="Бруффалон Грозового Дотику", d="Навіть зі свого ув'язнення первісна зневага Расзаґет змушувала скорятися наймогутніших звірів."},
    [1615] = {n="Приручена Метушлива Бабка", d="Дідусеві Вусаню не знадобилося багато часу, щоб приручити метушливих бабок довкола табору Драконолуски й змусити їх допомагати перевозити людей і вантажі Експедиції."},
    [1616] = {n="Лазурова Шурхокрилка", d="Щойно Дідусь Вусань нарешті навчив їх носити вершників, лазурові шурхокрилки виявилися здатними на тісний і відданий зв'язок зі своїми вершниками."},
    [1617] = {n="Зелена Шурхокрилка", d="Зелені шурхокрилки — ідеальна їздова тварина для розвідників Експедиції Драконячої Луски, адже вони прудкі й зливаються з листям Драконових островів."},
    [1618] = {n="Дарований Піскоковзень", d="Подарунок від Дідуся Вусаня — ці примхливі шурхокрилки допомагають Хроноходам долати теперішні (і майбутні) піщані часові лиха."},
    [1619] = {n="Прадавній Саламантер", d="Через свою любов до темних печер і каламутних вод цей унікальний різновид саламантера трапляється так рідко, що багато дослідників вважали його вимерлим."},
    [1621] = {n="Коралолуский Саламантер", d="Коли бурі Расзаґет вщухли, цей водяний різновид саламантера став одним із багатьох див, що оселилися на узбережжях услід за ними."},
    [1622] = {n="Штормошкірий Саламантер", d="Інколи, коли енергія бурі сповнює істоту, вона просто... стає більшою і спокійнішою. Мало хто із саламантерів дозволяє себе осідлати, та ці діти бурі — помітний виняток."},
    [1623] = {n="Кипучий Слимак", d="Виведений зі своєї безодні люттю закалі."},
    [1626] = {n="Панцеляск", d="Вигодуваний перемогами й загартований славою, цей равлик — справжня шана майстерності."},
    [1627] = {n="Слизький Равликемент", d="Утворений із залишкової стихійної енергії Первісних Бур, цей чарівний молюск спритніший, ніж здається."},
    [1629] = {n="Задерикуватий Світоравлик", d="Для Світотрощів — переносна підставка для ніг. Для тебе — витривала їздова тварина."},
    [1633] = {n="Дарований Тральний Мамонт", d="Подарунок від розвідниці Томул, щоб на бенкетах Іскаари завжди вистачало риби, аби нагодувати тих, хто потребує."},
    [1634] = {n="Замшілий Мамонт", d="Збережений тисячі років у камені, цей мамонт під бронзовою магією зістарився мало не до стану скам'янілості."},
    [1635] = {n="Степоходець-Носій", d="Мамонти Рівнин Он'агри не звикли носити людей, адже їхні сусіди-кентаври зазвичай не їздять верхи. Та вони можуть навчитися возити вершників. Дехто навіть робить це з охотою."},
    [1638] = {n="Каменошкірий В'ючний Звір Дослідника", d="Справжній дослідник ніколи не затримується на одному місці надовго. Надійний в'ючний звір із міцною спиною та дужими ногами незамінний у мандрах."},
    [1639] = {n="Лізі, Громохребетна Тупотуха", d="Ніщо не спинить Лізі в її місії скуштувати всі плоди світу."},
    [1644] = {n="Лютий Магмамонт", d="Здебільшого лава тече. Ця лава атакує."},
    [1645] = {n="Оновлений Магмамонт", d="Перекутий після знищення руками друїдів Полум'я, цей магмамонт готовий розтоптати будь-яких ворогів на своєму шляху."},
    [1651] = {n="Дарований Оттук-Авангард", d="Дарунок від Брени: іскаарці прислали своїх найвідданіших (і найчарівніших) супутників, щоб ті оберігали Калекґоса та його возз'єднану родину у Валдраккені."},
    [1653] = {n="Бурий Бойовий Оттук", d="Тускари Іскаари не зносять війни ні з ким, та все ж багато тускарів та їхніх союзників узяли до рук списи, маючи поруч бойового оттука."},
    [1654] = {n="Потойбічний Оттук-Носій", d="Декотрі оттуки переймаються справою носіння людей дужче за інших."},
    [1655] = {n="Жовтий Бойовий Оттук", d="Жовті оттуки Лазурового Хребта гнучкі, спритні й розумні. Ті, кого вишколено для війни, стають найкращими кавалерійськими їздовими тваринами тускарів, однаково вправними і на суходолі, і у воді."},
    [1656] = {n="Отто", d="Розслабся. Майбутнє розгорнеться так, як йому судилося, так чи інакше."},
    [1657] = {n="Бурий Розвідницький Оттук", d="Хитрі та грайливі у своєму природному середовищі, оттуки мають гострий зір, що дозволяє їм як видивлятися хижаків, так і вправно вести розвідку на далеких обширах."},
    [1658] = {n="Оттук Торговця Слоновою Кісткою", d="Жоден дорослий не знає, чому деякі оттуки білі, та будь-яка тускарська дитина скаже тобі: це тому, що вони їдять забагато снігу."},
    [1659] = {n="Жовтий Оттук-Розвідник", d="Жовті оттуки-розвідники обожнюють ховатися і чудово зливаються з довкіллям. Коли вони не «грають» у хованки зі своїми вершниками, то стають ідеальними супутниками для розвідки ворожих таборів."},
    [1660] = {n="Дрейк багряного гладіатора", d="Викуваний у вогні завоювань і озброєний до зубів."},
    [1662] = {n="Телікс Грозоріг", d="Колись простий жук із Забороненого Берега, Телікс просякнув магією бур, коли було випущено Расзаґет. Тепер, із загостреними чуттями, Телікс мандрує Драконовими островами разом з експедицією Драконячої Луски — і з тобою!"},
    [1664] = {n="Ворквін-Вартовий", d="Навчені за прадавніми методами драктирів, ці броньовані воркіни — вершина тактичної кінної війни на землі."},
    [1665] = {n="Прудкий Броньований Ворквін", d="Навчені за прадавніми методами драктирів, ці броньовані воркіни — вершина тактичної кінної війни на землі."},
    [1667] = {n="Броньований Ворквін-Ходун Ліній Сили", d="Навчені за прадавніми методами драктирів, ці броньовані воркіни — вершина тактичної кінної війни на землі."},
    [1668] = {n="Величний Броньований Ворквін", d="Навчені за прадавніми методами драктирів, ці броньовані воркіни — вершина тактичної кінної війни на землі."},
    [1669] = {n="Дарована Огуна-Вивідниця", d="Дарунок від Он'ірів, ці огуни — безцінні супутники, коли експедиція Драконячої Луски розвідує нові обрії."},
    [1671] = {n="Сутінокрила Огуна", d="Якщо поглянеш у нічне небо й побачиш, як повз тебе мчать хмари, не лякайся. Можливо, це лише невловима сутінокрила огуна."},
    [1672] = {n="Зенетеня", d="Найлютіші вітри починаються з одного пориву й помаху крил."},
    [1674] = {n="Норовлива Небокігтя", d="Слайверни рідко почуваються затишно в ролі верхових тварин. Лише ті, хто готовий вгамовувати їхній ненажерливий апетит і пильно за ними наглядати, можуть наважитися на них їздити."},
    [1679] = {n="Морозовиводковий Протовірм", d="Та сама магія нежиті, що підняла Морозовий Виводок на службу Королю-Ліху, наповнила цього первісного вірма. Його відданість і лють тепер служать тим, хто боронить Азерот."},
    [1681] = {n="Градовий Бронедон", d="Народжений у самому серці крижаної бурі, цей бронедон полюбляє свої страви напівзамороженими."},
    [1683] = {n="Багряний Ворквін", d="Шановані за свою стійкість у бою, навіть проти драконячого вогню, ці шляхетні створіння є цінними їздовими тваринами кавалерії драктирів."},
    [1684] = {n="Сапфіровий Ворквін", d="Шановані за свою стійкість у бою, навіть проти драконячого вогню, ці шляхетні створіння є цінними їздовими тваринами кавалерії драктирів."},
    [1685] = {n="Бронзовий Ворквін", d="Шановані за свою стійкість у бою, навіть проти драконячого вогню, ці шляхетні створіння є цінними їздовими тваринами кавалерії драктирів."},
    [1686] = {n="Обсидіановий Ворквін", d="Шановані за свою стійкість у бою, навіть проти драконячого вогню, ці шляхетні створіння є цінними їздовими тваринами кавалерії драктирів."},
    [1688] = {n="Лютий Шаблезуб", d="Елітні війська Альянсу, що їздять на цих шаблезубах, мають бойовий клич, який із дарнаського перекладається приблизно як «киць-киць, сюди»."},
    [1690] = {n="Драконеня"},
    [1692] = {n="Дивовижний Хвилевус", d="Кажуть, одна з цих чарівних рибин народжується, коли рибалці сниться та сама, що зірвалася з гачка... і стає більшою з кожним переказом цієї історії."},
    [1698] = {n="Ракетний Шредер 9001", d="Гоблін-торговець завжди розповідає людям про величезне розмаїття насадок для РШ-9001, та чомусь забуває згадати, що ти ніколи не обираєш, які насадки в нього будуть, коли сядеш верхи."},
    [1699] = {n="Осяйний Місячний Звір", d="Закуті в блискуче срібло, ці віддані їздові тварини, як кажуть, є благословенням від самої Елуни."},
    [1725] = {n="Пекельний Бронедон", d="Його хвіст пахне багаттям, а от дихання тхне сіркою."},
    [1727] = {n="Подоба Тарекгози", d="«Прощавай, Тарекгозо. Люба сестро, героїне, ученице й наставнице. Хоч кров і не пов'язує нас, ти завжди будеш родиною. Нехай твоя душа знайде своє місце, ширяючи серед зірок.»"},
    [1729] = {n="Слизький Король Міста", d="Велике серце, великі мрії, великий слизняк."},
    [1730] = {n="Вогняне Сланцекриле", d="Вам пробачать, якщо ви сплутаєте цю істоту з летючим вулканічним каменем. Бо певною мірою це він і є."},
    [1732] = {n="Кобальтове Сланцекриле", d="Виводок Карокти, вирощений у глибинному світлі Печер Заралек."},
    [1733] = {n="Розпечене Сланцекриле", d="Сланцекриле, народжене вслід за руйнівним проривом Фіракка. Прокляте його первісним полум'ям, воно поволі, але невпинно нагрівається. Воно мусить раз у раз занурюватися у воду, щоб охолонути, інакше власний жар його поглине."},
    [1734] = {n="Сланцекриле Тіньового Полум'я", d="Народжене з магми, його панцир спершу був розплавленими грудками, що охололи й перетворилися на темну вулканічну породу. Просочення тіньовим полум'ям лише зміцнило його незламну природу."},
    [1735] = {n="Каталогізоване Сланцекриле", d="Перший в історії знайдений зразок полум'яного сланцекрилого. Дев'ять із десяти дослідників згодні: воно гаряче!"},
    [1736] = {n="Каменевіз", d="Цих сланцекрилих спеціально навчили носити великі купи торгових валунів для торгових справ ніффенів."},
    [1737] = {n="Піщане Сланцекриле", d="Візерунки на крилах цієї істоти нагадують пісок, що сиплеться крізь пісковий годинник. На них можна милуватися цілу вічність..."},
    [1738] = {n="Нюхач Ласощів", d="Порода сланцекрилих, навчена ніффенами знаходити найглибше захований харч."},
    [1739] = {n="Зміїстий Дрейк Обсидіанового Гладіатора", d="Цей пустотливий дрейк полюбляє літати крізь гейзери та вулканічні струмені."},
    [1740] = {n="Лютий Бойовий Слимак", d="Альянс використовує цих ненаситних слимаків — їздових тварин, щоб долати будь-які перешкоди на полях битв."},
    [1742] = {n="Сквернокристалевий Скорпіон", d="Результат досліду з насичення Скверною одного з нащадків Скорпірона."},
    [1744] = {n="Печерний Дрейк Нетерокрилих", d="Помандрувавши до Аутленду й назад, ці дрейки цілком природно прагнуть нових небес."},
    [1772] = {n="Багряний Птеррордакс", d="Цей птеродакс так рвався у небо, що його наглядач не встиг завершити навчання."},
    [1773] = {n="Портовий Грифон", d="Цей грифон був найслабшим у зграї, і його лишили, коли побратимів відправили на навчання. Та сьогодні він готовий довести, чого вартий."},
    [1774] = {n="Звитяга", d="Для більшості мертвих скакунів вершника обирають інші. А ось Звитяга обирає вершника сама."},
    [1776] = {n="Білий Бойовий Вовк", d="Чи можна колись наситити голод вовка? Ці вовчі бестії вистежують і пожирають ворогів Орди."},
    [1777] = {n="Ненажерливий Чорний Грифон", d="Війна спотворила цих колись гордих створінь. Шурхіт їхніх крил тепер шепоче віщування близької загибелі."},
    [1778] = {n="Золотолапий Альбатрос", d="Злетівши з далекого часоплину, цей небачений досі різновид птаха народився у світі порядку."},
    [1779] = {n="Дракон Скверни-Бурі", d="Палаючий Легіон здолав драконів у далекому часоплині. Ці лихі вирми Скверни обрали псування та рабство замість загибелі."},
    [1781] = {n="Сірчаний Гончак", d="Чорна Імперія підкорила цих упокорених і сповнених ненависті гончаків. Цілком слухняні, вони й досі служать сильним."},
    [1782] = {n="Досконалий Колос", d="Досконалість, як і краса, в очах того, хто дивиться. Та зір можна вдосконалити хірургічно."},
    [1783] = {n="Прив'язаний до Погибелі Переможець", d="Колись прив'язані до служіння Погибелі, ці мертві дракони існують лише задля того, щоб сіяти смерть, хвороби й руйнування."},
    [1784] = {n="Королівський Рій", d="Ці трутні рояться навколо кожного, хто наважиться наблизитися до їхньої королеви без запрошення."},
    [1785] = {n="Прадавній Роздвоєнокопит", d="Цей роздвоєнокопит бачив, як спливають епохи, був свідком усього й терпляче навчив верхової їзди багатьох."},
    [1792] = {n="Алґарський Грозовий Вершник", d="Цей сповнений блискавок крумкач літає навіть за найжорсткішої погоди й був навчений ширяти небесами острова Дорн і занурюватися в глибини під ним."},
    [1794] = {n="Петті", d="Зберігачка Катос зустріла Петті під час свого першого завдання у Вол'дуні. Петті полюбила роботу Зберігачів, але прагне копати глибше, допомагаючи шукачам пригод у їхніх розслідуваннях."},
    [1795] = {n="Віщий Деревовирм", d="Проростаючи до життя лише раз на шістдесят років, цей живий дерев'яний дракон поєднує терпіння дерева й граційність дракона в польоті."},
    [1797] = {n="Велетенський Ґррлок", d="Це другий найбільший мурлок, якого ти коли-небудь бачив!"},
    [1798] = {n="Лазурний Світоохолоджувач", d="У найвіддаленіших куточках Азероту розповідають історії про жахливого дракона, що вкрив землю пеленою мук. У деяких версіях цієї історії його вогняна присутність несла катаклізмічну смерть і руйнування по всьому світу. В інших версіях він синій."},
    [1799] = {n="Моторошний Вершник Передодня", d="Улюблений засіб пересування родини Фенлоу (особливо під час Дня всіх стражденних)."},
    [1801] = {n="Зелений Панцеродон", d="Покручені роги цього панцеродона набагато міцніші за кістку."},
    [1808] = {n="Квітучий Сноолень", d="Шкури молодих снооленів розквітають яскравими барвами Сну."},
    [1809] = {n="Сонцеосяйний Сноолень", d="Промениста енергія сонця живить цих снооленів, допомагаючи їм швидко досягти зрілості."},
    [1810] = {n="Відроджений Сноолень", d="Попіл опалого листя — родючий ґрунт, з якого постають сноолені."},
    [1811] = {n="Місячний Сноолень", d="Бліде сяйво місяця відбивається у шкурі цих невловимих нічних створінь."},
    [1812] = {n="Рунозв'язаний Вогнелорд", d="Хай вогонь спопелить усі перешкоди на твоєму шляху!"},
    [1813] = {n="Стрибкові двигуни Мімірона", d="Створені Міміроном як прототип. Деталі викрали з його майстерні, продали, і з часом вони загубилися. Аж до сьогодні..."},
    [1814] = {n="Сутінковий Сновидний Шаблезуб", d="Сновидний шаблезуб блискавично б'є з тіні, хапає дрібних тварин і безшумно зникає в темряві. Ті нечисленні щасливці, яким випало бачити, як сновидний шаблезуб їсть, розповідали, що перед трапезою він залюбки ліниво бавиться зі здобиччю."},
    [1815] = {n="Зимовий Нічний Сновидний Шаблезуб", d="Ці нічні сновидні шаблезуби несуть у собі зимовий холод і часто сплять цілими днями, якщо їх нічим не розбудити."},
    [1816] = {n="Вечірній Сонячний Сновидний Шаблезуб", d="Ці сновидні шаблезуби лютують у бою, та водночас мляві й часто ліниво вилежуються на відкритих полях. Увібравши тепло денного світла, їхнє полум'я палає ще яскравіше."},
    [1817] = {n="Сновидний Шаблезуб Ранкового Цвіту", d="Відомі щедрою енергією, що струмує від них, ці шаблезуби — справжні бешкетники. Їхній рик розганяє ранніх пташок, які їх будять."},
    [1818] = {n="Ану'релос, Дороговказ Полум'я", d="Хоч її пір'я мерехтить руйнівною силою полум'я, воно не обпікає, а лише випромінює приємне тепло."},
    [1819] = {n="Лютий місячний звір", d="На відміну від більшості своїх родичів, цей місячний звір має смак до крові Орди й уподобав синій колір."},
    [1822] = {n="Дрейк Драконічного Гладіатора", d="Його крила затьмарюють небеса тінню завоювання."},
    [1824] = {n="Бурохутрий колючий бакар", d="Який же хороший хлопчик. Чи дівчинка. Інколи важко сказати напевно. Але завжди хороший."},
    [1825] = {n="Тайван", d="Ти не мусиш бути таким, яким тебе очікує бачити світ. Будь таким, яким тебе знає Тайван."},
    [1831] = {n="Звивадрейк зеленого гладіатора", d="Цей дрейк відвідував багатьох героїв у їхніх снах, перш ніж пристати до твоєї справи."},
    [1833] = {n="Весняний Сновидокіготь", d="Сповнений такої енергії та запалу, що будь-кому стане заздрісно."},
    [1834] = {n="Охряний Сновидокіготь", d="Грайливі сновидокогті часто прикрашають себе розмаїттям барв, які дарує лише осінь."},
    [1835] = {n="Сніжнопухнастий Сновидокіготь", d="Безтурботні й лагідні, мов сніг, вони здатні перестрибувати від однієї кучугури до іншої, не лишаючи й сліду."},
    [1837] = {n="Делюген", d="Уяви, що ти настільки поринув у сон, аж він здається справжнім; дехто навіть назвав би це маренням."},
    [1838] = {n="Талонт", d="Деякі мрії сповнені дивовижних можливостей, та розбиваються, щойно нагадаєш собі про межі реальності. Інші ж сни не такі обтяжені — навіть коли несуть на спині вершника."},
    [1839] = {n="Зорепас", d="Мимоволі замислюєшся, як воно — зривати зорі з їхньої небесної опори. Можливо, колись Зорепас покаже нам, як це робиться."},
    [1841] = {n="Багряний Мерехтохутровий", d="Гілнейська легенда каже, що цей червоно-білий лис перетинає Свято Зимового Серпанку лише в одну пору року."},
    [1938] = {n="Мамміф", d="У Сні часом міф реальніший за те, що його породило."},
    [1939] = {n="Уявокрил", d="Немає нічого прекраснішого, ніж бачити, як твоя уява злітає в небо."},
    [1940] = {n="Салатранцер", d="Хоча увага більшості саламантрів вільно перескакує з однієї дивовижі на іншу, ця воліє довгі години глибокого спостереження."},
    [1941] = {n="Серцешукач-манаскат", d="Колись цьому манаскату хтось сказав, що він чарівний. Відтоді він невпинно шукає того приємного відчуття."},
    [1942] = {n="Самоцвітний Мідний Скарабей", d="Правителі пустельних королівств налаштовували кристали на своїх особистих їздових тварин, щоб швидко їх прикликати."},
    [1943] = {n="Інкоґнітро, Незбагненний Скверноцикл", d="Цю демонічну машину сконструював головний інженер Улзік як експеримент із подорожей між вимірами. Попри численні смерті під час випробувань, Улзік лишався переконаний, що цей засіб розкриє таємниці всесвіту, досі недосяжні для пізнання."},
    [1944] = {n="Золотий Величний Скарабей", d="Покритий золотом і оздоблений смарагдами, цей скарабей гідний возити особ королівської крові з усією пишнотою."},
    [1945] = {n="Самоцвітний Сапфіровий Скарабей", d="Подарована юній принцесі тол'вірів, ця оздоблена самоцвітами статуя була оживлена самоцвітними провидцями Рамкагена."},
    [1946] = {n="Самоцвітний Нефритовий Скарабей", d="Тонкі, мов лезо, крила цього скарабея надійно захищені блискучим, але незнищенним панциром, вирізьбленим із нефриту."},
    [1947] = {n="Полумоцикл, Кований Ненавистю", d="Цей розкішний смертоцикл дасть тобі вирушити у власний хрестовий похід на палаючих покришках!"},
    [1948] = {n="Смертоцикл Полум'я Порожнечі", d="Найдорожча власність Геймара Побожного. Незрозуміло, чи був би він бодай кимось без свого епічного мотоцикла Порожнечі. Колись його приставили патрулювати вулиці Стормвінда після його падіння."},
    [1949] = {n="Ґілнейська Нишпорка", d="Сумлінна порода нишпорок, чию лютість здатна перевершити хіба що лютість воргенів. Ці рішучі створіння втілюють дисципліну і стриману жорстокість, якою захоплюються навіть воргени."},
    [1954] = {n="Квітучий примхадрейк", d="Ці пустотливі захисники Смарагдового Сну можуть бути більшими за своїх родичів, чарівних драконів, але вони аж ніяк не менш бешкетливі."},
    [1956] = {n="Лис Дружби", d="Ці чарівні створіння живляться любов'ю і дружбою."},
    [1957] = {n="Небесний Лис, що Ширяє", d="Здіймися в небеса на найвідданішому й найлюблячішому лисі в усьому Азероті."},
    [1958] = {n="Сутінкова Небесна Нишпорка", d="Дехто прозвав його опівнічним пустуном, і чимало пар вважають саме його причиною того, що їхні шляхи перетнулися серед ночі."},
    [1959] = {n="Роза Вітрів", d="Витягнута з велетенської коробки гри Hearthstone."},
    [2023] = {n="Шляхетний Літючий Килим", d="Маги, святкуючи Шляхетний Сад, перетворили звичні святкові прикраси на летючі дива, та розгніваний друїд викрав цей килим."},
    [2035] = {n="Величний Лазуровий Павич", d="Павич славиться приголомшливими барвами свого оперення."},
    [2036] = {n="Осяйний Сонцесяйний Павич", d="З цим птахом пір'я ніколи не вийде з моди."},
    [2038] = {n="Глинолускатий Рогоступ", d="Глинолускаті рогоступи завдячують своєю назвою пилувато-червоному забарвленню. Найчастіше їх можна побачити, як вони мчать багнистими пагорбами Рівнин Он'агрі."},
    [2039] = {n="Дика Синя Бойова Черепаха", d="Не журися, переслідуючи ворогів, — у тебе є гармати. Ніхто не втече від гармати."},
    [2055] = {n="Нескінченний Броньодон", d="Навіть серед броньодонів можливості майбутнього нескінченні."},
    [2056] = {n="Лютий Сновидний Кіготь", d="Улюблена здобич цього котячого звіра — Орда."},
    [2060] = {n="Золотий Диск", d="Стародавній артефакт могу, що його вручають тим, хто щиро відданий усіляким формам грошей."},
    [2063] = {n="Серпанковий Палій Моґу", d="Цей стародавній артефакт могу керує навколишнім туманом, даючи змогу левітувати."},
    [2064] = {n="Небесний Серфер", d="Стародавній артефакт могу, що його вручають тим, хто щиро відданий небесам."},
    [2065] = {n="Денноштормний Вітроскакун", d="Кажуть, що коли блискавка вдарить у сонце, з небес зійде осяйний звір у червоній броні. Денноштормний Вітроскакун ніколи не чув про цю легенду — адже він був тут від самого початку."},
    [2067] = {n="Лісовий Вітроскакун", d="Хутро цього Вітроскакуна не лише забарвлене під його лісову домівку, а й зазвичай ховає в собі шматочки кори та листя."},
    [2068] = {n="Стрімкий Вітроступ", d="Вітроступи напрочуд лагідні й легко піддаються навчанню... якщо вам вдасться спіймати бодай одного."},
    [2069] = {n="Пернатий Вітросерф", d="\"Перед посадкою перевірте поточну швидкість вітру та висоту. Уникайте дерев та інших високих об'єктів. Пошкоджені повітряні змії поверненню та відшкодуванню не підлягають.\" - Посібник користувача вітросерфа"},
    [2070] = {n="Квілен-Охоронець", d="Коли Кван Невблаганний загинув у бою, його вірні пси чекали на його повернення. Минули тисячоліття, а вони все ще терпляче чекають."},
    [2071] = {n="Мармуровий Квілен", d="Створений чаклуном-моґу, що вдихнув життя у свій улюблений камінець."},
    [2072] = {n="Позолочений Їздовий Журавель", d="Кажуть, що колись один імператор заплатив величезну суму за золотого журавля. Виявивши, що журавель лише забарвлений під колір коштовного металу, він на тиждень з сорому сховався у своїх покоях."},
    [2073] = {n="Блідий Їздовий Журавель", d="Я глянув, і ось переді мною блідий... журавель?"},
    [2074] = {n="Рожевий Їздовий Журавель", d="Цього яскраво забарвленого птаха часто плутають із фламінго або марабу."},
    [2075] = {n="Срібний Їздовий Журавель", d="Цей високий птах - один із найграційніших та найелегантніших журавлів, дещо вишуканіший за бронзового журавля, та трохи поступається золотому."},
    [2076] = {n="Розкішний Їздовий Журавель", d="Величний птах, але доволі вибагливий до їжі."},
    [2077] = {n="Тропічний Їздовий Журавель", d="Цей мешканець Нефритового лісу використовує своє забарвлення як маскування."},
    [2078] = {n="Снігова Їздова Коза", d="Гірські кози вершини Кун-Лай відомі тим, що в пошуках бобів кафа та солі здираються навіть на найвищі піки."},
    [2080] = {n="Маленька Руда Їздова Коза", d="Те, чого цій козі бракує в розмірі, вона надолужує впертістю."},
    [2081] = {n="Кривавий Небокрик", d="Цей динозавр досі несе в собі лють своїх предків з часів вторгнення зандаларі."},
    [2083] = {n="Нічний Птеророкрил", d="Учені тлумачать жахливий вереск цієї істоти як «бійтеся мене, я — ніч!»"},
    [2084] = {n="Нефритовий Птеррордакс", d="Ця улюблена їздова тварина зандаларі — чудовий співак, принаймні сама вона так вважає."},
    [2085] = {n="Кобальтовий Велет", d="Те, що починалося як їздова гірничо-лісозаготівельна машина, швидко обернулося на хаос, коли інженери запитали себе, чи можна зробити її ще крутішою."},
    [2086] = {n="Гнилозалізний Велет", d="Цю бойову машину викрали з лінії часу, в якій Ґаррош Хеллскрім приєднався до Палаючого Легіону. Зайве й казати, що від тієї лінії часу мало що лишилося."},
    [2087] = {n="Фіолетовий Їздовий Тигр Шадо-Пан", d="«Будячи тигра, бери довгу палицю. А ще краще — скажи розбудити тигра другові.» — пандаренське прислів'я"},
    [2088] = {n="Річкохід Мушан", d="Мушан — ненажерливий звір. Хоча його й можна приручити, він щодня вимагатиме другого, третього і навіть четвертого сніданку."},
    [2089] = {n="Блідошкірий Звір Мушан", d="Блідошкірий мушан — найсмачніший серед звірів-мушанів, але терпіти не може, коли йому про це нагадують."},
    [2090] = {n="Поллі Роджер", d="Погибель морів, що трохи на північний схід, гігантські папуги на кшталт Поллі можуть жити до 2000 років. Який чудовий спадок для твоїх нащадків."},
    [2091] = {n="Мандрівний Дикунчик", d="Ці грайливі гості з іншого світу розквітають, мандруючи до нових земель з новими друзями."},
    [2114] = {n="Пожирач Душ Зоваала", d="«Чи був я гарним хлопчиком?» — спитала душа в Зоваала. «Ні. Мені казали, що ти був найгіршим.»"},
    [2115] = {n="Злет"},
    [2116] = {n="Згаданий Золотий Грифон", d="У Стормвінді люблять левів, а грифон — наполовину лев. Саме тому ці створіння стали основою повітряних подорожей по всьому Альянсу."},
    [2117] = {n="Згаданий Вітрокрил", d="Сотні битв у десятках походів проведено й виграно на спинах цих шанованих створінь."},
    [2118] = {n="Бурштиновий Птеррордакс", d="Птеррордакс міг би проковтнути тебе за лічені секунди — і неодмінно зробив би це. Ти певен, що сидіти в нього на спині — гарна ідея?"},
    [2119] = {n="Механокостюм Кам'яного Сховку", d="Метал, колись понівечений, повернувся до життя завдяки брухту й пісні."},
    [2140] = {n="Чарівний Посланець", d="Ні сніг, ні дощ, ні спека, ні нічна пітьма не завадять цим чарівним посланцям швидко завершити призначений обхід."},
    [2142] = {n="Величний Фенікс", d="Прекрасні Величні Фенікси благословенні Чі-Джі, щоб сповнювати серця вершників захватом і надією на майбутнє."},
    [2143] = {n="Змій Астрального Імператора", d="Коли вільний від тягарів імператор Шаохао віддав останній подих, щоб захистити свій народ, золотий змій зійшов із небес, аби піднести дух імператора до вершин Кун-Лай."},
    [2144] = {n="Дирижабль Глибинника", d="Цей літальний апарат допоможе тобі поринути просто в пригоду, де б вона не була!"},
    [2145] = {n="Завзятий Кезанський Хвилеріз", d="Якби в кожного був океан, усі каталися б на хвилях на цьому розкішному хвилерізі. Та коли океану немає, можна серфити по небу!\nКатаймо!"},
    [2148] = {n="Тліюча Попеляста Бджола", d="Дещо несподіваний вибір їздової тварини, але Рада Дорноґала запевняє тебе, що їздити на ній безпечно. Здебільшого."},
    [2152] = {n="Перламутровий Гоблінський Хвилеріз", d="Серфи узбережжям Стренглторну стильно!"},
    [2158] = {n="Натовподробарка 2-30", d="Гарантовано вибиває зуби твоїм ворогам одним ударом!"},
    [2159] = {n="Машинний Захисний Блок 1-11", d="Один із багатьох мехокостюмів, створених, щоб охороняти Машину. Після років вірної служби він уже не годиться для бою. Утім, із нього виходить показний засіб пересування."},
    [2161] = {n="Старий Світлокліщ", d="Світлокліщі повільно більшають із віком. Цей прожив довге, насичене життя."},
    [2162] = {n="Блакитний Світлокліщ", d="Світлокліщі добре відомі в Дзвінких Глибинах тим, що з них виходять напрочуд міцні їздові тварини. Цей різновид випромінює м'яке блакитне сяйво, яке кобольди вважають особливо заспокійливим."},
    [2165] = {n="Летюча Медобджола", d="Ця скромна бджола мріє про відкрите небо. А чи буде шукач пригод їхати в неї на спині, чи ні — їй байдуже."},
    [2167] = {n="Шалена Попеляста Бджола", d="Норовом гаряча, як її полум'я, ця порода попелястих бджіл піддається приборканню лише тим, хто поділяє її невгамовну жагу до насильства."},
    [2171] = {n="Глибинний Повзун Вдови", d="Діти, що живуть на поверхні, досягнувши певного віку, нерідко мріють про власного поні чи вовка. Юна Вдова Арак'наї мала схожі прагнення, хоча її смаки за деякими мірками назвали б доволі своєрідними."},
    [2172] = {n="Спадковий Глибинний Повзун", d="Розведення павукоподібних — давня й шанована традиція серед Сил Спадку. Хоча більшість особин використовують для перевезення вантажів або виховують як ударні загони, найкращих представників виводку часом навчають для парадів."},
    [2174] = {n="Глибинний Повзун Королівського Двору", d="У вищому товаристві Кагеті родовідні грамоти слугують для засвідчення історії та цінності чистокровних глибинних повзунів. Утім, ця практика буває непростою, адже згадані повзуни схильні раптово з'їсти своїх же літописців."},
    [2176] = {n="Алуніра", d="Так довго саме втілення хмар лежало в полоні на вершині гори блискавок. І ось нарешті я знову відчуваю вітер за спиною."},
    [2177] = {n="Аквамариновий Ройовик", d="Хоч це й не надто звична річ, представники Розітнутих Ниток запевняють тебе, що ройовики цілком здатні витримати твою вагу, якщо ти вирішиш осідлати такого."},
    [2178] = {n="Гніздовий Ройовик", d="Норники за вдачею, вони часто причаюються в норах дрібних звірят, щоб відкласти яйця або влаштувати засідку на більшу здобич."},
    [2180] = {n="Тіньовий Ройовик", d="Ройовики — звичне видовище і в нетрях Азж-Кагета, і серед неруб'ян, які давно їх приручили, та це не робить їх менш небезпечними для необачних шукачів пригод."},
    [2181] = {n="Ройовий Небесний Мисливець", d="Зазвичай його можна знайти в найменших закутках і щілинах скелястих склепінь, та ройовий небесний мисливець почувається в повітрі затишніше, ніж на спочинку."},
    [2184] = {n="Лютий Щелепоповзун", d="Цей надзвичайно великий щелепоповзун саме того розміру, щоб стати їздовою твариною... тільки тримай руки й ноги подалі від його пащі."},
    [2186] = {n="Синя Риба Прадавніх Богів"},
    [2187] = {n="Підсвітний Прибережний Скрадач", d="Допоможи своєму глибоководному скакуну в полюванні на здобич уздовж океанського дна."},
    [2188] = {n="Ках, Легенда Глибин"},
    [2189] = {n="Зіпсований Бегемот Підсвіту", d="Світло від сідла допомагає приваблювати здобич до цього зіпсованого бегемота."},
    [2190] = {n="Тінь Сумніву", d="З'явившись після зникнення Ксал'атат, сама присутність цієї тіні породжує питання: чи справді її задуми було зірвано? Чи ми лише глибше зіграли їй на руку?"},
    [2191] = {n="Закута Тінь", d="Хто б міг подумати, що тіньовий елементаль стане такою зручною їздовою твариною?"},
    [2192] = {n="Поріддя Беледара", d="Крізь Священне Полум'я шепоти темряви несуть тебе в бій."},
    [2193] = {n="Кіноварна Імперська Рись", d="Імперські рисі вважаються найкращими супутниками араті як на полі бою, так і поза ним. На жаль, попередній власник цієї рисі загинув у бою."},
    [2194] = {n="Безстрашна Імперська Рись", d="З обладунка цієї рисі зірвано майже всі знаки розрізнення. На єдиній уцілілій бирці написано: «Безстрашна»."},
    [2198] = {n="Бойовий Сабельник Кор'крону", d="Знайшовши виводок кошенят нічного сабельника, загін кор'кронських вершників-розвідників виховав із них грізну зграю смертоносних їздових тварин."},
    [2199] = {n="Бойовий Сабельник Блекрок", d="Натрапивши на виводок кошенят нічних сабельників, загін вершників Блекрок виховав із них грізну зграю смертоносних їздових тварин."},
    [2200] = {n="[PH] Nightsaber Horde Mount White"},
    [2201] = {n="Бойовий Вовк Вартової", d="Захоплений під час набігу Вартових, цей вовк віддає свою відданість найсильнішому."},
    [2202] = {n="[PH] Alliance Wolf Mount"},
    [2203] = {n="Бойовий Вовк Калдораї", d="Захоплений під час набігу калдораї, цей вовк віддає свою відданість найсильнішому."},
    [2204] = {n="Гніт", d="Урятований від нещадного наскоку Старого Воскоборода та навислої загрози Темряви, тепер він може спокійно гризти залишки воску."},
    [2205] = {n="Старий Кріт Руфус", d="Мудріший, ніж можна висловити словами, і досі прудкий на ноги. Просто часом трохи втомлюється."},
    [2209] = {n="Багряний Багноніс", d="Багноносів часто використовують кобольди як їздових тварин, і Збори Глибин вирішили надати тобі доступ до одного з найвідданіших своїх багноносів."},
    [2211] = {n="Лютий Небодер", d="Ця істота прагне битви з нікчемною Ордою."},
    [2213] = {n="Сланцевий Рамоліт", d="Земельні здавна використовують рамолітів як в'ючних тварин завдяки їхній витривалій вдачі. Сланцевих рамолітів вважають приязнішими за більшість інших, хоч це й небагато про що говорить."},
    [2214] = {n="Сланцекам'яний Рамоліт", d="Земельні скотарі часто говорять про витривалість цієї істоти й про те, як дощ зіскакує з її лискучої шерсті."},
    [2218] = {n="Скверний Кажан Кованого Гладіатора", d="Пробуджений у печерах посеред поля бою й закутий у броню для січі."},
    [2219] = {n="Небесний Різак Сурекі", d="Небесний різак був одним з найлютіших страхіть, що постали з експериментів королеви Ансурек із Чорною Кров'ю Прадавніх Богів."},
    [2220] = {n="Переприручений Небесний Різак", d="Один з небагатьох небесних різаків, яких сили араті захопили під час сурекійського наступу після падіння королеви Ансурек. Цей звір став дуже корисним у вистежуванні псування Порожнечі як удома, так і в чужих краях."},
    [2222] = {n="Сіесбарг", d="Бідолаха."},
    [2223] = {n="Піднесений Небесний Різак", d="Призначені для найвідданіших із сурекійської еліти, ці небесні різаки були улюбленцями королеви Ансурек за свою хитрість і жорстокість."},
    [2224] = {n="Гіпогриф Пошарпане Перо", d="Цей величний гіпогриф родом із Пошарпаноперого нагір'я у Фераласі. Колись він захищав своїх пташенят, та нині обрав служіння вищій справі."},
    [2225] = {n="Мисливський Ведмідь Амані", d="Тролі амані їздять на цій лютій істоті під час церемоніальних ловів на честь ведмежого бога Налоракка."},
    [2230] = {n="Кістяний Голіатус", d="Ці велетенські жуки проводять життя в найтемніших тунелях Каз Алґару. Хоч їм недоступний навіть найслабший проблиск штучного сонячного світла, вони все одно процвітають."},
    [2232] = {n="Дика Чорна Бойова Черепаха", d="Гармати живить невгамовна лють, що жене її вистежувати ворогів і чинити над ними правосуддя. Ніщо не втече від гарматного пострілу."},
    [2233] = {n="Рамоліт Земного Розпорядника", d="Під кам'яною поверхнею б'ється серце, наснажене порядком, аби звільнити цей світ від темряви."},
    [2235] = {n="Зореторкнутий Хутровик", d="Один з перших вічних мандрівників натрапив на хутровиків і заприязнився з парою з них. Ці хутровикові кошенята повернулися з мандрівником до його володінь і назавжди змінилися, живучи там і супроводжуючи мандрівників."},
    [2237] = {n="Ватажок Зграї з Ґризлі-Гіллз", d="Торговці швидко знайшли в них вельми вправних союзників, стикаючись із небезпеками Нортренда й далі за ним. Вони також дізналися, що ведмеді Ґризлі-Гіллз надзвичайно віддані. Особливо до тих, хто завжди має напоготові імператорського лосося."},
    [2238] = {n="Золотий Кроколіск Володаря Грабунку", d="Що за Володар Грабунку без належного показу награбованого?"},
    [2239] = {n="Осяйний Кроколіск Кеґ Лега", d="Піратський капітан, якого згодом стали звати Кеґ Лег, чудово розумів небезпеку, коли мчав у бій верхи на голодному кроколіску."},
    [2240] = {n="Опівнічний Кроколіск Володаря Грабунку", d="Будь-який вартий свого імені капітан знає, що поряд має бути надійний навігатор."},
    [2241] = {n="Потертий Кроколіск Володаря Грабунку"},
    [2244] = {n="Діамантовий Мехокостюм", d="Ці мехокостюми, що працюють на кристалах, — вершина технологій земних."},
    [2249] = {n="Рука Решкіґаала", d="Решкіґаал вичікувала, поки її родичі один за одним намагалися повалити Вигнанця. Вона прагнула вдарити, коли він втратить пильність, та шпигуни Тюремника вистежили її. Завдяки їхньому застереженню й допомозі Тюремник узяв гору."},
    [2255] = {n="Золотий Попіл Ал'ара", d="Золотий Ал'ар, улюблений супутник Кель'таса Сонстрайдера, доводить, що смерть — лише тимчасова невдача."},
    [2259] = {n="Велетенський Ґрлок", d="Це третій за величиною мурлок, якого ти будь-коли бачив!"},
    [2261] = {n="Буря Холодного Полум'я", d="Народжена з хаосу перших воєн стихій на Азероті, Буря Холодного Полум'я нагадує, що холод хуртовини вічний."},
    [2262] = {n="Ведмідь Гармонійних Вітань", d="Верхи на цій їздовій тварині тебе сповнює спокій і тиша, що рідко притаманні мурлокам чи ведмедям."},
    [2265] = {n="Позолочений Брутозавр Торговця", d="Мортен і Кіллія й гадки не мали, наскільки вигідним виявиться їхнє нове торгове партнерство по обидва боки фракційних кордонів. Аж до того дня, коли вони змогли придбати це чудове створіння, щоб полегшити свої мандри. І, звісно ж, зробити це з позолоченим шиком."},
    [2272] = {n="Багряний Броньований Гарчун", d="Декотрі ґобліни лагідно називають приручених гієн \"гарчунами\". Цей полюбляє копати."},
    [2274] = {n="Костолам Картелю Чорновіддя", d="Краще тримай свої кістки при собі, якщо не хочеш, щоб їх потрощили."},
    [2276] = {n="Жуйноприбирач Картелю Темного Сплаву", d="Вважається ватажком серед Стіксових Гієн Звалища і має щелепи, достатньо потужні, щоб роздробити будь-що — чи будь-кого, — кого Ґаллівікс хоче спекатися."},
    [2277] = {n="Фіолетовий Броньований Гарчун", d="Смакс знає дещо про догляд за гієнами. Правило номер один: тримай руки подалі від цих зубів!"},
    [2278] = {n="Пломендо Лютий", d="Бути VIP-персоною серед VIP-персон Гелладжіо має свої переваги, зокрема ключі від цього колишнього Короля Різанини. Найсучасніша гоблінська технологія дозволяє йому долати понад 100 ярдів на галон!"},
    [2279] = {n="Осічка Громового Барабана", d="Знайдено на трибунах Казана після особливо моторошної сутички. Коли оператора Торка запитали, чи це невибух, він просто відповів: «Мабуть?»"},
    [2280] = {n="Спецвипуск «Верхоліт»", d="Смакс упевнений, що ця ракета не вибухне посеред польоту. Абсолютно. Цілком. На 100%. Точно."},
    [2281] = {n="Постачальник Картелю Стімвідл", d="Забезпечить тебе швидкою подорожжю, а твоїх ворогів — гучним вибухом!"},
    [2283] = {n="Дослідник Інновацій", d="Коли найкращий шлях до гарної ідеї — мчати дуже швидко."},
    [2284] = {n="Вохриста Доставна Ракета", d="Доправляй посилки й пасажирів з точки А в точку Б зі смаком!"},
    [2286] = {n="Подрібнювач Картелю Чорновіддя «Делюкс» Мод. 2", d="Краще не питати, що сталося з Мод. 1."},
    [2287] = {n="Руйнівник Картелю Темного Сплаву", d="Чудово вміє наводити безлад. Не так добре дає раду з прибиранням."},
    [2288] = {n="Персональний Гоблінський С.К.Р.А.П.ер", d="Гоблінські подрібнювачі раз по раз доводили свою користь у багатьох справах, як-от лісозаготівля чи перевезення. Цю модель переобладнали для потреб С.К.Р.А.П.у."},
    [2289] = {n="Координатор Венчурної Компанії", d="Збудований, щоб керувати будь-якою операцією Венчурної Компанії із передової."},
    [2290] = {n="Захисник Активів", d="Запевняє інших, що ваші активи саме там, де їм належить бути."},
    [2291] = {n="Відновлена Літальна Машина Гоблінського Мільярдера", d="Колись ця літальна машина була предметом гордості ґоблінської еліти, та, на жаль, опинилася на звалищі брухту, щойно на ринку з'явилося щось більше, яскравіше й вибуховіше."},
    [2292] = {n="Маніпулятор Маржі", d="Дбає про те, щоб між вами й самим дном завжди лишалася бодай невелика відстань."},
    [2293] = {n="Око-Шпигун Даркф'юз", d="Ідеально для амбітного кар'єриста, який хоче піднятися щаблями, зробивши чужі справи СВОЇМИ справами."},
    [2294] = {n="Зловісна Зелена Літальна Машина", d="Найкращі інженери картелю Стімвідл запевняють, що саме вони винайшли це механічне диво, а решта картелів лише скопіювала їхні креслення."},
    [2295] = {n="Бомбардувальник Білджвотер", d="Для швидкого перевезення торгових товарів картелю та інших вкрай нестабільних речовин."},
    [2296] = {n="Гоб-Скакун Глибинника", d="Цей літальний апарат допоможе вам пірнути просто в пригоду, якщо не вибухне раніше!"},
    [2298] = {n="Кажан Скверни Шанованого Гладіатора", d="Пробуджений у печерах посеред поля бою й закутий у броню для битви."},
    [2299] = {n="Лютий Електровугор", d="Ці водяні чудовиська полюбляють катувати Альянс своїми електричними розрядами."},
    [2301] = {n="Нестабільна ракета", d="Брак захисних засобів вона з лишком надолужує швидкістю та стилем. Не для слабкодухих."},
    [2303] = {n="Фіолетовий Гоблінський Подрібнювач", d="Цей подрібнювач дбайливо пофарбовано нержавкою фарбою, щоб блиск зберігався надовго."},
    [2304] = {n="Гриф, Кований Хаосом", d="Народжена і вирощена у часи великого хаосу, ця їздова тварина пережила випробування, відомі небагатьом."},
    [2305] = {n="Гіпогриф, Кований Хаосом", d="Народжений і вирощений у часи великого хаосу, ця тварина пережила випробування, відомі лише небагатьом."},
    [2307] = {n="Жахокрил, Кований Хаосом", d="Народжений і вирощений у часи великого хаосу, ця тварина пережила випробування, відомі лише небагатьом."},
    [2308] = {n="Вершник Вітру, Кований Хаосом", d="Народжений і вирощений у часи великого хаосу, ця тварина пережила випробування, відомі лише небагатьом."},
    [2313] = {n="Магнітомех Маестро Брухту", d="Чудово пасує для стискання сміття в кулі, які можна котити. Апокрифи Маестро Брухту твердять, що з них могли б постати власні світи, якби ж вони тільки виросли достатньо великими."},
    [2315] = {n="Дерев'яний Небесний Змій", d="Живий, що дихає, летючий витвір мистецтва."},
    [2317] = {n="Зачарований Чаротканий Килим", d="Маги Даларану створили вишукане чароткання та ауру самозшивання на додачу до цього летючого килима. Тож будь-хто зможе впоратися з будь-якими розпущеними нитками й літати зі смаком."},
    [2321] = {n="Вчасна Дзумбджілка", d="Дзумкочучи крізь час, як завжди, пунктуально, ці Дзумбджілки збирають заблукалі піщинки часу й безпечно повертають їх до Часоплинів."},
    [2322] = {n="Трайїр, Очі Сирени", d="У нападі люті й відчаю Трайїр викликав бурю, що мала спустошити землю та знищити ворогів Сирсе. Майже десять тисяч років по тому морелютий шторм досі вирує, наче відлуння його сили."},
    [2324] = {n="Гаченіготь", d="Колись Гаченіготь плавав із Піратами Кривавого Вітрила, а згодом — із Розбійниками Чорних Вод, та зрештою подався геть, щоб дізнатися, яку здобич можна знайти за межами відкритого моря."},
    [2326] = {n="Сквернокажан Астрального Гладіатора", d="Пробуджений із печер на полі бою та закутий у броню для битви."},
    [2327] = {n="Місячний Метальник", d="Коли ти на Місячному Метальнику — це завжди свято."},
    [2328] = {n="Мітла Відьми Кохання", d="Первісний взірець серії чарівних мітел «Рух від Почуттів», що працюють на емоціях. Ця їздова тварина неодмінно домчить тебе куди треба миттю!"},
    [2329] = {n="Мітла Сільвермун", d="Сільвермунська барвиста гама для «Руху від почуттів» здобула успіх по всьому Азероту."},
    [2330] = {n="Мітла Сутінкової Відьми", d="Темніший вигляд для серії чарівних мітел-їздових тварин «Рух від почуттів». Поціновувачі цього кольору знають, що він має чудовий вигляд незалежно від часу доби."},
    [2331] = {n="Мітла Небесної Відьми", d="Жодних меж угорі, коли осідлаєш цю чарівну мітлу серії «Рух від почуттів»."},
    [2332] = {n="Пісня Хвилеріза", d="Рідко трапляється в історії, щоб моряк вирізьбив на носі свого корабля те саме чудовисько, яке покинуло його гинути на мілині. Народ ми блюзнірський і нікчемний. Сама думка про те, що хтось із нас матиме смирення вшанувати таку істоту, межує з безумством."},
    [2333] = {n="Старосвітський Хвилеріз Совізі", d="Ця гарненька штучка вилискує чудовим платиновим блиском. Вона за лічені секунди підійме тебе попід небеса! Танцюватимеш довкола сонця, скільки душа забажає, і все це за сміховинно низьку ціну в десять тисяч дзвінких монеток."},
    [2334] = {n="Бронзовий Гоблінський Хвилеріз", d="Навіть працівники картелю час від часу заслуговують на відпочинок."},
    [2339] = {n="Сміттєва Купа Джані", d="Для одного мона це сміття, а для іншого мона цілий лоа! Хек-хек-хек..."},
    [2342] = {n="Кудлохутро Меексі", d="Кудлохутра грайливі, незграбні й одержимі чистотою. Це небезпечне поєднання рис."},
    [2343] = {n="М'яколап Меексі", d="М'яколапи дають чорний чай, що ідеально пасує для ранкової бадьорості або щоб не заснути до пізньої ночі."},
    [2344] = {n="Котолап Меексі", d="Котолапи дуже пишаються своїм обов'язком носити чай. Вони завжди готові пригостити теплою чашкою чаю своїх супутників у мандрах."},
    [2345] = {n="Чаєхвіст Меексі", d="Чаєхвости славляться своїми запашними чаями. Утім, їхня грайлива вдача може призвести до того, що чаю розіллється більше, ніж вип'ється."},
    [2346] = {n="Пивокрад Меексі", d="Попри свою пустотливу й грайливу вдачу, ці створіння стають вірними та надійними супутниками в мандрах."},
    [2347] = {n="Дика Алебастрова Бойова Черепаха", d="Мудрість, нагромаджена за віки, вилилася у відомий вислів: «Ніхто не втече від гарматного ядра»."},
    [2469] = {n="Призматичний Кусач-дракон", d="Хамелеоноподібні створіння нерідко вміють підлаштовувати свої клітини під колір довколишнього світу. Цей кусач-дракон перейняв таку здатність, але лише для того, щоб набувати кольору вмісту власного шлунка, виводячи приказку «ти — те, що ти їси» на цілком новий рівень."},
    [2470] = {n="Сутінковий Небодер", d="Зриваючись на здобич глупої ночі, ці небодери своїм криком колись наганяли жах на всіх дітей Дренору."},
    [2471] = {n="Ур'зул М'ясодер", d="Цей жахливий ур'зул вбирає в себе своїх останніх жертв, обертаючись на майже нездоланне чудовисько. Добре, що ти з ним лагідний, бо інакше міг би стати його наступним ласощем."},
    [2473] = {n="Виплодок Сінестри", d="Після падіння Бастіону Сутінків кілька розрізнених сутінкових драконенят вислизнули з-під влади Вексіони. Деякі з цих драконенят уклали союз зі смертними й готові носити їх на собі як вершників."},
    [2474] = {n="Мідногривий Квілен", d="Вирощені у стайнях Залізного Кона, ці їздові тварини непохитно віддані й ніколи не покидають свого поста, навіть коли відчувають загибель своїх господарів."},
    [2476] = {n="Спотворений Ша Хмарний Змій", d="Ша спотворило цього хмарного змія, зробивши його ще грізнішим створінням. Емоції, що струмують крізь нього, роблять його безпомильним провісником загибелі."},
    [2477] = {n="Спотворений Ша Їздовий Тигр", d="Ша спотворило цього тигра, зробивши його ще грізнішим створінням. Емоції, що струмують крізь нього, роблять його безпомильним провісником загибелі."},
    [2478] = {n="Палаючий Королівський Вогняний Яструб", d="Лише найпристрасніші душі й найзапекліші серця можуть назвати Палаючого Королівського Вогняного Яструба своєю їздовою твариною."},
    [2480] = {n="Багряний Шматувальний Танк", d="Експериментальний подрібнювач, створений радше для вбивства, ніж для збору деревини."},
    [2481] = {n="Опівнічний Скакун Тьмяного Місяця"},
    [2482] = {n="Жвавий Скакун Тьмяного Місяця", d="Огорнута подертими цирковими прапорами, ця моторошна їздова тварина — досконале поєднання тіні й видовища."},
    [2483] = {n="Фіолетовий Скакун Тьмяного Місяця", d="Цей скакун несе на своїй спині таємницю й магію Ярмарку Тьмяного Місяця."},
    [2484] = {n="Сніжний Скакун Тьмяного Місяця"},
    [2487] = {n="Великий Ґ", d="На вигляд під капотом нічого надзвичайного, та зачекай-но, поки ґобліни по сусідству побачать, як ти під'їжджаєш на ньому до наступної вечірки біля басейну."},
    [2488] = {n="Вільний Бігун Мерехтливого Туману", d="Звільнені від сідла й вудил, ці долинні бігуни справді вільні."},
    [2489] = {n="Перламутровий Метелик", d="Здійнися в небеса на блискучому, мерехтливому, перламутровому метелику."},
    [2491] = {n="Рубіновий Метелик", d="Невловимого Рубінового Метелика дуже прагнуть здобути Сутінкові Відьми."},
    [2492] = {n="Весняний Метелик", d="Здійнися в небеса на блискучому, мерехтливому, весняному метелику."},
    [2494] = {n="Опівнічний Метелик"},
    [2495] = {n="Смарагдовий Слимак", d="Цей слимак береже свої скарби з лютістю дракона, хоч, мабуть, і не з його швидкістю."},
    [2496] = {n="Грифон зі Шрамами Порожнечі", d="Покинутий своїми наглядачами, грифон зі шрамами Порожнечі живився будь-якими рештками їжі, що лишалися, а більшість з них була зіпсована Порожнечею. Тепер, коли Порожнеча живить їх, вони сідають на землю лише тоді, коли їхні мінливі смаки вдовольняє чиста їжа, насолоду від якої вони ще пам'ятають."},
    [2497] = {n="Жеребець, Викуваний Порожнечею", d="Викувані так само, як колись їхні підкови, ці звірі вже не стільки коні, скільки енергія Порожнечі в їхній подобі."},
    [2498] = {n="Мати Зграї зі Шрамами Порожнечі", d="Борючись зі своїми зіпсованими наглядачами, ця мати зграї звільнила себе й своїх дитинчат. Однак свобода від наглядачів не звільнила їх від Порожнечі цього загубленого місця. Вона навчила своїх дитинчат бути ще небезпечнішими звірами, і тепер вони нишпорять по всьому Оґриммару, добуваючи їй їжу, поки всі змагаються за виживання."},
    [2499] = {n="Вітрогон, посічений Порожнечею", d="Коли вивільнилися енергії Порожнечі, більшість вітрогонів збожеволіла. Вони повбивали одне одного і своїх приборкувачів. Ті, хто вцілів, замкнули ворота до їхнього гнізда. Кількох уцілілих вітрогонів досі видно вгорі, та ніхто не наважується повернутися в їхні нові смертоносні володіння, щоб побачити, що там лишилося."},
    [2500] = {n="Ньялотський Тіньовий Хробак", d="Уламок минулого Чорної Імперії, ці предтечі хробаків безодні знову повертаються з піднесенням Ньялоти."},
    [2501] = {n="Скверна Аспектів", d="З тріумфом Н'Зота справдилося те, що почалося з Галакронда. Коли Аспекти зникли, скверна їхнього виду завершилася."},
    [2502] = {n="Пантера з Кристалу Порожнечі", d="Хоча багато коштовних самоцвітів було вражено енергіями Порожнечі в жахливих видіннях, майстри ювелірної справи досі можуть використати їх, щоб виготовити могутніх пантер-скакунів."},
    [2504] = {n="Плямиста Чорна Їздова Коза", d="Якось повз цю козу пройшов наймит, не погладивши її. Цього вистачило, щоб коза сприйняла все як особисту образу."},
    [2505] = {n="Осяйний Каррок", d="Технологічне диво в плоті, цей каррок уособлює надію на світліший К'ареш."},
    [2507] = {n="Прототип A.S.M.R.", d="Уособлюючи вершину ґоблінської пропагандистської технології, Ґаллівікс замовив Автоматичний Звуковий Машинний Резонатор, щоб переконати навіть найзапекліших критиків."},
    [2508] = {n="Заповзятливий Подрібнювач-Танк", d="Оптимізований подрібнювач, створений для максимальної ефективності подрібнення."},
    [2510] = {n="Жах Пустищ", d="Він не настільки лихий, щоб пожирати світи, просто його ніхто не зрозумів."},
    [2511] = {n="Жах Ночі", d="Не дайте його яскравим барвам ввести вас в оману, він здатен підкрастися до будь-кого (чи будь-чого)."},
    [2512] = {n="Манолет глибинника", d="Цей літальний апарат допоможе вам поринути просто в пригоду, а може, і в інші виміри!"},
    [2518] = {n="Хронокорсар", d="Завжди у пошуках наступної золотої нагоди, цей пірат Нескінченної зграї драконів промчав крізь часові шляхи, щоб зібрати команду для бездоганного нальоту."},
    [2519] = {n="Сяйлива Імперська Рись", d="Сяйлива Імперська Рись утілює незламну силу й відвагу, потрібні, щоб відігнати темряву. Ці звірі несуть нас уперед, аби ми високо тримали свої смолоскипи для всіх, хто шукає прихистку від навали мороку."},
    [2520] = {n="Весняний Жнивний Дикобраз", d="Весняний Жнивний Дикобраз найжвавіший рано-вранці. Майже весь день він проводить, винюхуючи їжу або гучно скликаючи інших жнивних дикобразів."},
    [2521] = {n="Літній Жнивний Дикобраз", d="Літній Жнивний Дикобраз любить вилежуватися на сонці або поплавати в чистому озері. Він чудово вміє знаходити їжу, та спершу його треба до цього вмовити."},
    [2522] = {n="Зимовий Жнивний Дикобраз", d="Зимові Жнивні Дикобрази переважно нічні створіння. Вони трохи повільніші за інших жнивних дикобразів, зате їхня витривалість не має собі рівних."},
    [2523] = {n="Осінній Жнивний Дикобраз", d="Осінні Жнивні Дикобрази неперевершені у винюхуванні їжі в холодніші місяці. Гострий нюх робить їх чудовими супутниками для пошуків харчу в лісі, проте їх важко вгамувати там, де багато запахів."},
    [2524] = {n="Кормера Холодного Полум'я", d="Під час війни володарів стихій кормер часто використовували як в'ючних тварин найвірніші підлеглі Володаря Вогню."},
    [2525] = {n="Великий Крук Пророка", d="Будучи Пророком, Медів передавав свої послання в образі чорного крука. Хай цей птах і не такий вражаючий, як перевтілення, та все ж він несе всю велич того, чиє ім'я носить."},
    [2526] = {n="Скверноджерна Кормера", d="Кормери були одним із ранніх видів Азероту, який привласнили собі володарі стихій."},
    [2527] = {n="Розплавлена Кормера", d="У найдавніші дні Азероту ці стихійні хижаки панували в охоплених полум'ям небесах володінь Рагнароса."},
    [2528] = {n="Лавороджена Кормера", d="Під оком володарів стихій багатьох кормер спотворили їхні сили, і ті стали вірними їздовими тваринами й товаришами."},
    [2529] = {n="Великий Крук Архімага", d="Можливо, трохи старіший і радше сивий, аніж звичної опівнічної темряви, цей крук усе ж уособлює одного з наймогутніших арканних майстрів Азероту — Вартового Хадґара."},
    [2531] = {n="Тиранотортя", d="Вінні Ласунчик тримав цю рідкісну білу черепаху-альбіноса в таємниці, аж доки не настав час прорекламувати Підступні Дуети."},
    [2532] = {n="Вісник Са'бака", d="Тол'віри розповідають про легендарного Са'бака, велетенського кроколіска, що, як вважають, вийшов зі священної долини кратера Ун'Ґоро. Хоч мало хто бачив Са'бака на власні очі, багато хто вірить, що його благословили Хранителі-Титани, аби він оберігав широкі водні шляхи Ульдуму."},
    [2535] = {n="Рись, посічена Порожнечею", d="Приборкання рисей — мистецтво, яке араті відточували роками. І хоч культисти Нічної Навали лишаються відданими своїй справі, цю традицію вони все ж передають далі."},
    [2542] = {n="Кровомисливський Кажан Скверни", d="Звір із невідомого світу в надрах Викрученого Нетеру, приборканий жорстокою і невблаганною волею."},
    [2544] = {n="Попелочумний Кажан Скверни", d="Лише найзапекліші з героїв вирушають у бій верхи на цій потворі, народженій зі скверни й нежиті."},
    [2546] = {n="Жалюгідний Кажан Скверни", d="Здається, її наручі трохи затісні."},
    [2549] = {n="Тіньовий Каррок", d="Дикий каррок, що чудово пристосований до полювання у вічних сутінках К'ареша."},
    [2550] = {n="Каррок Бистрокрил", d="Цей каррок, отриманий у подарунок за надані послуги, пережив чимало небезпечних польотів."},
    [2552] = {n="Лавандовий Каррок", d="Попередній господар цього напрочуд войовничого каррока загинув, досліджуючи Відв'язаний Простір. Можливо, він прийме тебе натомість... а може, й ні."},
    [2555] = {n="Кісткомороз", d="Запеклий суперник Кісткоплава, цей повзун був вигнаний зі свого лігва поблизу манакузні Омега після нищівної поразки. Тепер він прагне навчитися в того, хто скинув з трону його найбільшого ворога."},
    [2556] = {n="Рубіновий Повзун Порожнечі", d="«Врятований» Спілкою К'ареша задля досліджень, цей повзун Порожнечі виявився надзвичайно витривалою їздовою твариною."},
    [2557] = {n="Їдкий Повзун Порожнечі", d="Цей повзун живився отруйними випарами, через що його тіло просякло потужними кислотами."},
    [2560] = {n="Синій Баррі", d="Особливо рідкісний різновид сланцеспина, «Синій Баррі» раніше слугував в'ючною твариною."},
    [2561] = {n="Допитлива Сланцеспина", d="Ця допитлива сланцеспина якимось чином примудрилася застрягти в ящику. Як вона взагалі туди влізла — досі загадка."},
    [2566] = {n="Багряний Каскад Лана'тель", d="Володіння кривавими мистецтвами дозволило Королеві Крові закликати моторошного слугу, щоб той ніс її в бій. Вбраний у барви, гідні її двору, він прикритий жахливою личиною та оздоблений крилами й пазурами, що нагадують про гнів своєї володарки."},
    [2567] = {n="Драконояструб крила Порожнечі", d="Розтинаючи небеса, він летить на безшумних крилах, а його очі сяють відлунням забутих зірок."},
    [2568] = {n="Світлокрилий драконояструб", d="Випромінюючи тепло й грацію, він ширяє на крилах зі світла."},
    [2569] = {n="Вільний Зореїд", d="У позначеному Порожнечею сліді Всепожирача та його роду викривлені рештки далеких світів і забутих епох знаходять свій шлях крізь Велику Темряву."},
    [2570] = {n="Лютий Повзун Порожнечі", d="Родом із К'ареша, ці створіння люблять зариватися в землю й нападати із засідки на необачних членів Орди."},
    [2572] = {n="Крижаний Бойовий Кінь Банші"},
    [2573] = {n="Грандіозний Ґррлок", d="Це четвертий за величиною мурлок, якого ти бачив!"},
    [2574] = {n="Сніжний орел Високогір'я", d="Знайти перо сніжного орла у Високогір'ї — прикмета мінливих вітрів і падіння температури."},
    [2575] = {n="Пророча Дошка Гросмейстера", d="Шаховий захід не вдалося стримати. Тож Медів змайстрував цей засіб пересування, щоб брати його з собою в мандри."},
    [2576] = {n="Темно-Синя Дошка Гросмейстера"},
    [2577] = {n="Королівська Дошка Гросмейстера", d="Завжди рухайся вперед, щоб піднятися над пішаками внизу."},
    [2578] = {n="Димчаста Дошка Гросмейстера"},
    [2579] = {n="Гротескний Бойовий Кінь Покинутих", d="Труп є труп, авжеж, авжеж."},
    [2580] = {n="Бойовий Кінь Банші-Плакальниці", d="Ці осінені тінню скакуни безшумно несуть жерців Забутої Тіні крізь темні ліси Тірісфаля."},
    [2581] = {n="Огидний Бойовий Кінь Банші"},
    [2582] = {n="Мудрий Змій Шаохао", d="Уроки, які Шаохао засвоїв у житті та смерті, і любов, яку він плекав до своєї домівки, злилися воєдино в цьому ефірному змії — відображенні мудрості імператора."},
    [2586] = {n="Місячний Нічний Шаблезуб", d="\"Її біле сяйво на їхньому посрібленому хутрі, її яскраво-блакитний погляд у їхніх осяяних місяцем очах. О, як місяці всміхаються цим створінням.\" — Мати Кало'тера, Верховна жриця Елуни, «Благословення в Гаджирі»"},
    [2587] = {n="Кістяна Лютогрива", d="За легендою раптарі, під час першого сходження Дазара схилами Зандалару майбутнього короля вело крізь темряву мерехтіння кістяної луски та палаючих червоних очей."},
    [2593] = {n="Шлаковий Василіск", d="Шлакові василіски споконвіку жили глибоко під землею, де живилися обсидіаном і базальтом, але вибралися на поверхню, коли Легіон сплюндрував їхні домівки."},
    [2595] = {n="Швидкий Примарний Драконояструб", d="Навіть мертвим час від часу треба підкинути куди їхати."},
    [2598] = {n="Сплеск світла Порожнечі", d="Він переливається між осяйним світлом і ненаситною Порожнечею, мчить крізь небеса в танці рівноваги."},
    [2600] = {n="Неброньований Скверний Вепр Смертоіклий", d="Блукає галявинами Скверноліса, маючи незмінний раціон із проклятих трюфелів і заблукалих мандрівників. Не гладити."},
    [2601] = {n="Перламутровий Кролуск", d="Завезені на К'ареш як інвазивний вид, кролуски знайшли собі застосування як в'ючні тварини."},
    [2602] = {n="Переміщений Ненажера", d="Випадково перенесений, коли Посередники зрушили Тазавеш, цей ненажера знайшов новий світ, повний потенційних джерел енергії — як-от маяки аніми... та вершники."},
    [2603] = {n="Останній Обід Стаарбса", d="Коли одна космічна загроза-загарбник зустрічає іншу, менша часом опиняється в меню більшої. Принаймні космічні спостерігачі не завжди жують свою їжу."},
    [2604] = {n="Колісниця OC91", d="Бойовий мехокостюм «Колісниця OC91» перевантажений силою Титанів. Подейкують, що ця посилена міць загострює рефлекси та вміння пілота."},
    [2605] = {n="Бойовий Кінь Інаріуса", d="Символ помсти в усіх відомих світах."},
    [2606] = {n="Королівське Крило Порожнечі", d="Космічний жах, спотворений і загартований жорстокістю Короля-Нексуса, нині присягою зв'язаний служити тобі."},
    [2607] = {n="Попіл Бело'рена", d="Один з останнього виводку Ал'ара, Бело'рена відвезли на острів Кель'Данас і виростили, щоб він власним життям захищав Сонячний Колодязь від усіх, хто йому загрожуватиме. Кажуть, що смерть ніколи його не забере."},
    [2608] = {n="Загартований Світлом Мехокостюм", d="Співпраця між щойно пробудженими земельними Ординантами та ковалями Святолому дала вдосконалений, загартований Світлом земельний мехокостюм."},
    [2612] = {n="Наглядач, Викуваний Порожнечею", d="Після того, як Мавзолей Перших було відкрито, цей витвір Перших викрали Посередники та продали ефіріалам під час оборудки на Завуальованому Ринку. Завдяки винахідливим змінам ефіріалів він увібрав таємниці Етеру й тепер ширяє в повітрі з надзвичайною грацією, лишаючи по собі слід мерехтливого зоряного пилу."},
    [2614] = {n="Лютий грімрись", d="Цей грімрись пережив чимало битв проти створінь у Розломі Альну."},
    [2615] = {n="Грімрись-кореневий переслідувач", d="З хутром, що пасує до глибокого коріння, і бронею під стать пишному листю, ці грімрисі споряджені бути одними з найкращих мисливців Гарандара."},
    [2616] = {n="Кістяний грімрись", d="Кістяні грімрисі мають сильну вдачу до незалежності. Аби осідлати такого, потрібен особливо хоробрий гаранір."},
    [2618] = {n="Громовогребеневий Елекк", d="Навіть просочення демонічною магією не зламало дух цих величних звірів, і їхні спотворені тіла так і не влилися на службу Легіону."},
    [2619] = {n="Жариноопалений Елекк", d="Палаючий Легіон прагнув знищити, викрасти чи спаплюжити все, що приносило радість дренеям, і елекки Дренору не стали винятком."},
    [2620] = {n="Елекк, Спустошений Порожнечею", d="Їхня вдача така ж дика, як спотворені сили, що скривили саме їхнє створення, і служать вони лише тим, кого оберуть самі."},
    [2621] = {n="Елекк, Викуваний Легіоном", d="Палаючий Легіон заздрив зв'язку дренеїв з елекками Дренору. Чимало демонічних повелителів звірів спотворили цю породу, щоб служила їхнім потребам, та приборкати їх не зміг жоден."},
    [2622] = {n="Крижаний Бойовий Кінь Безголового Вершника", d="Крізь небо ти полетиш, на ворогів зійдеш згори, і цей бойовий кінь понесе тебе, щоб згубу їм принести."},
    [2623] = {n="Моторошний Бойовий Кінь Безголового Вершника", d="Капості зіграно, ворогів подолано, цей моторошний бойовий кінь чекає на ласощі, друже."},
    [2624] = {n="Палаючий Бойовий Кінь Безголового Вершника", d="Вогні палають у серці й душі цього скакуна, тож здіймайся в небо — на тебе чудово дивитися."},
    [2625] = {n="Священний Бойовий Кінь Безголового Вершника", d="Майбутнє твоє невідоме, а минуле повне привидів. Із цим скакуном поруч — чи довго ти протримаєшся?"},
    [2626] = {n="Оздоблений Нордеронський Грифон", d="Старійшини-вершники грифонів та верховні шамани Нордеронських Дикомолотів часто прикрашали своїх грифонів вигадливим, вкритим пір'ям оздобленням, що вказувало на їхній ранг і статус."},
    [2627] = {n="Гірський Грифон Верховного Шамана", d="Стародавні шамани Дикомолотів, які першими зустріли грифонів, вважали їх стихійними духами у смертній подобі. Ця зустріч назавжди закарбувалася в клані Дикомолотів на покоління вперед."},
    [2628] = {n="Жаринопірий Верховинний Грифон", d="За легендою Дикомолотів, помаранчеве оперення грифонів вважають спадковою рисою, переданою від їхніх стихійних предків."},
    [2629] = {n="Небесний Проводир Жаринокрилих", d="\"Від передгір'їв Каз Модану ми йшли за його осяяними жаринами крилами — смолоскипом, що линув на північ крізь темне літнє небо.\" - Проща Першого Дикомудреця"},
    [2630] = {n="Норовистий Вітроступ", d="Цей талбук — уперта, норовлива їздова тварина, навіть коли вже знає свого вершника. Вершникам варто стерегтися."},
    [2631] = {n="Багряний Летун Порожнечі", d="Збожеволілі від Порожнечі, ці крилаті створіння — вихор кігтів і зубів."},
    [2632] = {n="Астральний Тур", d="Перемога — це не просто питання сили, а й мудрості та вміння спрямувати силу туди, де вона потрібна найбільше."},
    [2633] = {n="Блакитний Летун Порожнечі", d="Спотворені Порожнечею, ці крилаті створіння нині панують у небі К'ареша."},
    [2634] = {n="Палка Звитяга", d="Декого не стримати й не приборкати. Палка Звитяга прагне величі й служитиме лише тим, хто здатен прислужитися її пошукам."},
    [2640] = {n="Бомбардувальник Бровфесту", d="Стережися, щоб не зжерти набої."},
    [2645] = {n="Ріг-Гребінь Калу'ак", d="Тускари звуть цих Ріг-Гребенів «Калу'ак» не для того, щоб привласнити їх, а як попередження: вони більше не терпітимуть, щоб когось забирали браконьєри, що полюють на їхні неповторні роги."},
    [2649] = {n="Ріг-Гребінь, Випробуваний Акулами", d="Ріг-Гребеня часто вабить попастися на рослинах, що ростуть у морі. Дехто з них здолав там найлютіших хижаків, ставши справжніми Калу'ак."},
    [2650] = {n="Ріг-Гребінь Кригоходця", d="Цього рідкісного мешканця Блакитного Поясу тускари краю вважають благословенним."},
    [2651] = {n="Ріг-Гребінь Скелелаза", d="Тускарів нечасто зустрінеш у Високогір'ї, але ріг-гребені часто спускаються до берегів у пошуках рідкісних ласощів у прибережних водах."},
    [2653] = {n="Моторошний Ур'зул", d="Ненажерливий різновид демона, моторошний ур'зул роздирає зів'ялу плоть і кістки так, ніби скубе салат."},
    [2655] = {n="Загублений у Фазі Сланцеспин", d="Цей Сланцеспин заблукав, мандруючи різними фазами, поки йшов слідом за ефіріалами."},
    [2660] = {n="Лейстоунний базиліск", d="Цього прекрасного базиліска часто полюють заради магічних властивостей його органів. На щастя для базиліска, зв'язок із лей-лініями дає йому передчуття наближення хижаків."},
    [2661] = {n="Базиліск скверносланцю", d="Колись поширені на Зламаних островах, базиліски скверносланцю зазнали запеклого полювання з боку рудокопів, що жадали їхньої коштовної шкіри."},
    [2662] = {n="Аквамариновий Базиліск", d="Попри свою назву, аквамаринові базиліски ласують найрізноманітнішими прибережними кристалами та океанічним камінням."},
    [2663] = {n="Жахоступ Іллідарі", d="Попри свій смак до плоті й неприродну здатність чути запах страху, цих нижчих демонів іллідарі підкорили й приручили, наче мисливських супутників."},
    [2664] = {n="Гнилоступ Іллідарі", d="Ці демони пожирають заразу й тішаться розкладом. Хто тільки додумався їздити на них верхи?"},
    [2665] = {n="Високогірний старорог", d="Шкура високогірного старорога неймовірно товста. За всю писану історію жоден високогірний старорог навіть оком не змигнув у відповідь на образи, кинуті йому в обличчя."},
    [2666] = {n="Високогірний Орел з Верхівок Дерев", d="Величний орел — символ гордості племен Високогір'я. Здатність цього могутнього звіра носити тауренів на спині свідчить про неабияку силу й розмір створінь Високогір'я."},
    [2670] = {n="Манасабр Арканоягоди", d="Названі за схожість із яскравими ягодами, з яких роблять арканне вино, ці горді коти гостро відчувають лінії сили, що пролягають під ними."},
    [2671] = {n="Манаскат Зі Шрамами Скверни", d="Вижити на Аргусі — справа непроста. Зі шкірястою шкурою, посіченою скверною, цей манаскат схильний до нападів люті ще більше, ніж зазвичай."},
    [2672] = {n="Кривавозубий Манаскат", d="Розкол Аргуса довів цей різновид манаскатів до жаги крові. Тепер він живиться зіпсутою кров'ю будь-яких створінь, у яких лише може встромити свої численні зуби."},
    [2673] = {n="Манаскат-Альбінос", d="Розкол Аргуса змусив манаскатів мутувати й пристосовуватися до довкілля. Деякі з них зреклися своїх барв заради загострення чуттів."},
    [2674] = {n="Осяйний Манаскат", d="Манаскати здатні випромінювати яскраве сяйво, щоб приваблювати здобич."},
    [2675] = {n="Сутінковий Бігун", d="Щоб уникнути хижаків, цей бігун приглушує сяйво свого рогу, коли ховається, і спалахує сліпучим сяйвом, коли його роздратувати."},
    [2676] = {n="Золотий Сонцебіг", d="Ця вільна душа полюбляє довгі прогулянки берегом і пустощі серед різнобарвних квіткових полів."},
    [2677] = {n="Бірюзовий Скакун", d="Названий за неповторний колір очей, що ніби пронизують саму душу, бірюзовий скакун розумніший за своїх родичів-мрієбігів і славиться вмінням чудово розбиратися в людях."},
    [2678] = {n="Морочний Кошмар", d="Торкнута Смарагдовим Кошмаром, ця істота у снах віщує лихо. Побачити її наяву провіщає цілковиту катастрофу."},
    [2679] = {n="Кістяний Кінь Тріумфу", d="Добрий бойовий кінь вірний до самих кісток. Скинувши тлінну оболонку, цей кінь став провісником сміливих звитяг."},
    [2681] = {n="Кістяний Кінь Кровопролиття", d="Добрий бойовий кінь вірний до самих кісток. Скинувши тлінну оболонку, цей кінь став провісником вічної борні."},
    [2682] = {n="Кістяний Кінь Чуми", d="Добрий бойовий кінь вірний до самих кісток. Скинувши тлінну оболонку, цей кінь став провісником хвороб і страждань."},
    [2683] = {n="Кістяний Кінь Забуття", d="Добрий бойовий кінь вірний до самих кісток. Скинувши тлінну оболонку, цей кінь став провісником нестатків і смерті."},
    [2686] = {n="Довгорогий Соболиний Талбук", d="Талбуки Аргуса відростили довге грубе хутро яскравих кольорів, що відбиває барви їхньої зруйнованої планети."},
    [2688] = {n="Гранатовий Руїнохід", d="Споряджені міцною попоною, аргуські руїноходи безстрашно несуть своїх вершників крізь зруйновані пустища Аргуса й далі за його межі."},
    [2689] = {n="Довгорогий Похмурокопитий Талбук", d="Укритий шрамами від хаосу десятиліть війни, цей пройнятий скверною талбук — ідеальний супутник для безстрашного шукача пригод."},
    [2690] = {n="Довгорогий Аргуський Талбук", d="Мало хто з талбуків зумів лишитися неушкодженим попри те, що Легіон нещадно визискував їхній рідний світ. Така незламність гідна шляхетного скакуна."},
    [2691] = {n="Довгорогий Берилієвий Талбук", d="Цей дикий талбук, знайдений серед руїн Аргуса, вистояв і витримав десятиліття чвар."},
    [2693] = {n="Сонцепер амані", d="Народжені з Достатку й оновлення лісу, ці орли виблискують у промінні призахідного сонця — живий знак відродженої сили амані."},
    [2694] = {n="Вітрокликач амані", d="Швидкі, мов буря, і гострі, мов блискавка, ці священні орли несуть мітку Акіл'зона й піднімають своїх вершників на вітрах її благословення."},
    [2696] = {n="Нагірний Індик", d="Лютих і вельми великих індиків тепер часом можна побачити в глибоких лісах Тірісфаля після пошесті часів Четвертої війни."},
    [2697] = {n="Дивакуватий Індик", d="Ця істота, може, й не велична, та неодмінно приверне погляди!"},
    [2698] = {n="Загадковий Індик", d="Ще ніхто не наважився зробити з цієї їздової тварини собі обід."},
    [2699] = {n="Призовий Індик", d="Цей надзвичайно великий індик здобув перше місце не лише завдяки бездоганному пір'ю, а й завдяки своєму більшому за середній розміру."},
    [2700] = {n="Морозопадний Гайволет", d="Ці високолетні мешканці найвищих дерев Азероту відростили густу шовковисту шерсть, щоб призвичаїтися навіть до найхолодніших країв."},
    [2701] = {n="Жаротілий Гайволет", d="Родом із Гіджалу, ці пустотливі деревні мешканці зазнали приголомшливого перетворення, коли в краї з'явилися Вогняні Землі."},
    [2702] = {n="Похмурогілковий Гайволет", d="Похмурогілкові мають не лише унікальне темне забарвлення, а й ведуть цілковито нічний спосіб життя, тож побачити їх на власні очі — рідкісна удача."},
    [2703] = {n="Квітогілковий Гайволет", d="Ці чарівні гайволети відомі своїм забарвленням, що нагадує деякі з улюблених квітучих дерев Пандарії."},
    [2705] = {n="Каштановий Скакун", d="Скакуни — чудові верхові тварини. Тільки не намагайся злізти з них спереду."},
    [2706] = {n="Сірчаний Скакун", d="Полум'я на копитах скакуна виказує його прихильність до певної школи магії."},
    [2707] = {n="Осяйний Пелюсткокрил", d="Цей звір сяє блиском, який не здатна притлумити жодна Порожнеча."},
    [2708] = {n="Барвистий пелюсткокрил", d="Барвистий пелюсткокрил, що сповнює небо Гарандара яскравим рожевим відтінком, набув свого помітного забарвлення завдяки нектару різноманітних рослин, якими живиться."},
    [2710] = {n="Лазуровий спорокрил", d="Цей спорокрил любить ніжно тулитися до своїх вершників."},
    [2713] = {n="Рудуватий спорокрил", d="Цей спорокрил набув свого вражаючого відтінку від унікального грибка, що росте довкола коренів Тельдрассилу."},
    [2716] = {n="Верхівець Legion Remix (заглушка)", d="Талбуки Аргуса відростили довге, цупке хутро яскравих кольорів, що відбивають відтінки їхньої розбитої планети."},
    [2717] = {n="Механічний Прототип Пантери MK-0", d="Коли мешканці Ґаджетзана зламали підземну лабораторію палацу Ґазлоу, рев замкнених у клітках звірів був нестерпним. Технологія Нижнього Краю вживила цим пантерам бойові модулі, наділивши їх надлюдською силою та швидкістю. Інженери Іржаболта перепрограмували їх виключно для воїнів, що ведуть кампанію в К'ареші. Не забудь поміняти модулі біля Форуму Трансформації перед розгортанням."},
    [2718] = {n="Сталевий Прототип Пантери MK-0", d="Перші солдати Сталевої Орди, що перетнули Темний Портал, захопили лютого нічного шаблезуба. Майстри Блекрок озброїли його магмовою бронею, перетворивши на бойову зброю. Воїни можуть налаштувати його частини біля Форуму Трансформації, щоб пасувати своєму стилю бою та панувати на полі битви."},
    [2719] = {n="Зореіскровий Нетердрейк", d="Пронісши тебе до самих країв Аутленду й навіть далі, нетеркрилий дрейк зрештою теж відчув потяг до блакитних небес Азерота."},
    [2720] = {n="Скверноспалений Винищувач Лихоплоддя", d="Це летюче поєднання сил смерті та Скверни пронизує небеса крижаним до кісток вереском."},
    [2721] = {n="Скверноспалений Верескун Душогуба", d="Зірваний з небес лише найхитрішими з Мисливців на демонів."},
    [2723] = {n="Скверноспалений Вовкосокіл", d="Позначений шрамами війни на Розбитих островах, цей вовкосокіл заслуговує на добру домівку."},
    [2724] = {n="Скверноспалений Диск Архімага", d="Дехто з магів каже, що магія Скверни «нестабільна», «згубна» чи «заборонена». Дехто з магів помиляється."},
    [2725] = {n="Опалений Скверною Супутник Великого Магістра", d="Спотворене обличчя улюбленого супутника."},
    [2726] = {n="Опалений Скверною Скакун Верховного Лорда", d="Цього коня назавжди понівечила згубна магія Легіону."},
    [2727] = {n="Опалений Скверною Шукач Верховного Жерця", d="Цей пронизаний скверною пернатий друг шалено б'є крилами, аби триматися високо над хаосом унизу."},
    [2728] = {n="Опалене Скверною Передвістя Тіньового Клинка", d="Твої вороги пізнають страх, перш ніж зустріти свій кінець."},
    [2729] = {n="Опалена Скверною Буря Далекозорця", d="Лють із присмаком скверни."},
    [2730] = {n="Опалений Скверною Скакун Жаху Володаря Нижнього Світу", d="Просто переповнений могутністю."},
    [2731] = {n="Опалений Скверною Бойовий Вірм", d="Небеса тремтять в очікуванні твоєї появи."},
    [2732] = {n="Кобальтовий Фазовий Мисливець", d="Завдяки потойбічним енергіям, що опромінили Дренор, ці створіння можуть будь-коли зміщуватися крізь простір. Тому їх рідко помічають... доки не стане запізно."},
    [2733] = {n="Лиховісне Стерво", d="Несучи на собі найлютіших вершників Зул'Амана, воно своїми тінистими крилами вражає всіх, хто посміє чинити опір."},
    [2734] = {n="Одужне Стерво", d="Кружляючи над помираючими й приреченими, його крила провіщають чуму, руїну й непохитну певність: ніщо в його тіні не підведеться знову."},
    [2742] = {n="Громокопитий Небесник", d="Після падіння Громового Короля його затяжний грім злився з духом білого дракона. Він ступає по блакитних блискавках, лишаючи за собою вихор хмар, — там, де колись панувала тиранія, тепер сяє захисне світло."},
    [2743] = {n="Грозозолочений Небесник", d="Огорнутий громом, обраний долею. Золоті блискавки оплітають його копита, пронизуючи небо, мов розтинаючи ніч. Легенди тісно пов'язують його з імператором Шаохао."},
    [2747] = {n="Незаплямований повзун гаю", d="Якимось дивом цей повзун гаю лишився недоторканим жахіттями, що захопили селище Фунґара."},
    [2749] = {n="Відлуння Альн'шарана", d="Уважно слухай Пісню Богині."},
    [2751] = {n="Підсилений штормоскат", d="Спійманий на К'ареші й змінений Харонусом, цей штормоскат утік з Арени Шраму Порожнечі й відтоді блукає Войдштормом."},
    [2753] = {n="Вогняний драконояструб", d="Драконояструб, чиї крила сяють так само яскраво, як листя його рідного Лісу Вічної Пісні."},
    [2754] = {n="Перидотовий драконояструб", d="Перидотових драконояструбів вручають лише тим, хто звершив великі діяння на службі Сільвермуну."},
    [2755] = {n="Тінявий драконояструб", d="Огорнутий чорнильними тонами, цей драконояструб ширяє зі спокійною точністю, а похмуре забарвлення надає йому подих тихої вишуканості."},
    [2756] = {n="Багряний драконояструб", d="Драконояструб разюче яскравого забарвлення, яким захоплюються по всьому Кель'Таласу: його жагуче-червоні крила креслять світлі дуги в небі, доки він плине з плавною, невимушеною грацією."},
    [2758] = {n="Кобальтовий драконояструб", d="Рідкісна порода драконояструбів, що здіймається в таласійське небо на блакитних крилах, відколи втекла з Гнізда Сонячних Крил."},
    [2760] = {n="Гострокіготь амані", d="Рідкісний різновид орла амані: гострокігті б'ють із жахливою точністю й літають із незрівнянною грацією."},
    [2761] = {n="Багряний яструбоступ із Сільвермуна", d="Гордість двору Сільвермуна, ці яструбоступи цінуються за яскраве червоне оперення та чистокровну елегантність."},
    [2762] = {n="Лазуровий яструбоступ", d="Яструбоступ із блискучим оперенням, що втік зі стайень Сільвермуна. Хтозна, де у Лісі Вічної Пісні він може ховатися?"},
    [2764] = {n="Сутінковий Мучитель", d="Цих мучителів вабить невпинний бойовий клич і кровопролиття по всьому Височині Вбивць."},
    [2767] = {n="Приборканий захисник Штормаріону", d="Хоч Мучителі часто бувають агресивними, декого з них можна приборкати й навчити допомагати в оборонній військовій справі. Цей Мучитель пильнує Ядро Штормаріону, щоб ніхто не зміг до нього пробитися."},
    [2769] = {n="Зарозумілість шукача здобичі", d="Більших манавирмів ельфи крові іноді використовують як верхових тварин, але частіше тримають їх як символ статусу."},
    [2770] = {n="Гнів Ловця здобичі", d="Манавирми, достатньо великі й сильні, щоб нести повну збрую та вершника, доволі рідкісні й високо цінуються."},
    [2771] = {n="Жах Ловця здобичі", d="Золоті манавирми — рідкісна мутація. Серед побічних дослідів Асталора були й спроби збільшити їхню чисельність."},
    [2772] = {n="Благословенна нориця амані", d="Створіння, благословенне дикою природою, рухається з тією непохитною вдачею та лагідною силою, які амані вважають священними."},
    [2773] = {n="Гіганто Маніс", d="Перекази шепочуть про Гіганто Маніса — велетенське створіння, яке нібито мешкає в самих жилах Азероту. Ті, хто запевняє, що бачив його, говорять про пазурі, достатньо величезні, щоб пронизати серце дракона, і достатньо гострі, щоб розтяти найкращу броню, виковану смертними руками."},
    [2775] = {n="Панголін Візербарків", d="Цей доволі норовливий панголін утік від племені Візербарків після того, як на нього начепили броню. Хто знайшов — того й є!"},
    [2776] = {n="Благословенний ведмідь амані", d="Колись символи завоювання, ці бойові ведмеді знову крокують землею, відроджені благословенням Налоракка та оновленим духом амані."},
    [2778] = {n="Бойовий ведмідь предків", d="Його хода відлунює пам'яттю прадавніх воїнів — живий символ непохитної люті, яку шанують амані."},
    [2779] = {n="Ведмедиця-матір Візербарків", d="Цю бойову ведмедицю-матір захопив Клинок Сутінків, коли вона захищала своє ведмежа. Тривала розлука з малям тільки дужче її лютить. Той, кому вдасться повернути їй ведмежа, здобуде її вічну відданість."},
    [2785] = {n="Покинутий багряний бойовий кінь", d="Більше не знаряддя Багряного хрестового походу, цей бойовий кінь тепер з оновленою метою провадить новобранців шляхом Світла."},
    [2786] = {n="Заврочений орел Лихопера", d="Колись горда небесна мисливиця, тепер вона ширяє на висхлих крилах, а її дух спотворений невідступними некромантськими прокльонами, що сочаться крізь кожне гниле перо й кожне око з примарним відсвітом."},
    [2789] = {n="Ненажерливий дряпокіготь", d="Швидкі й надійні, дряпокогті стали одними з перших створінь, приборканих у Войдштормі. Їхні власники швидко засвоїли, що краще не лишати їх наодинці зі своїми улюбленцями."},
    [2790] = {n="Невситимий дряпокіготь", d="Дряпокіготь сповна перейняв шлях Порожнечі: ніколи не вдоволений, він безперестанку шукає нової сили, щоб панувати, і нової здобичі, щоб поглинати."},
    [2791] = {n="Крадькуватий шматокіготь", d="За словами розвідників рен'дорей, дряпокогтів часто бачать на полюванні зграями."},
    [2792] = {n="Шалений шматокіготь", d="Щойно гине один із зграї, ці дряпокогті впадають у несамовиту лють, яку не спинить навіть здоровезний ультрадон."},
    [2793] = {n="Лютий кусючий ящір", d="Цих створінь бачать, як вони крадуться полем бою й видираються на перешкоди, готові завдати клопоту Альянсу."},
    [2795] = {n="Бронзовий Дикодрак", d="Величні дикодраки звиваються в небі, вільні, наче нескута магія, що тримає їх у польоті."},
    [2796] = {n="Бронзовий Аквілон", d="Надійні скакуни Бастіону покликані відображати гордих і шляхетних воїнів Вознесених."},
    [2797] = {n="Бронзова Трупна Муха", d="Прикрасити трупну муху коштує неабияких зусиль, але дехто сказав би, що воно того варте."},
    [2798] = {n="Бронзове Могильне Крило", d="Хоч мешканці Ревендрету й воліють темну та лиховісну естетику, є й ті, хто досі полюбляє сяйливий блиск."},
    [2801] = {n="Кривавий дрейк галактичного гладіатора", d="Постав із Порожнечі, повністю споряджений і готовий до бою."},
    [2802] = {n="Шестерногриз Mk. 11", d="З кожним вибухом проходить нову ітерацію!"},
    [2803] = {n="Небеснолапий Мерехтохутрий", d="Хутро мерехтохутрого переймає властивості свого довкілля, наче маскування. Візерунки яскраво-блакитного неба та величних білих хмар принесли цьому мерехтохутрому прізвисько «Небеснолапий»."},
    [2804] = {n="Багряний Люпин", d="Колись Первинні прагнули створінь із палкою відданістю, яких могли б формувати на свій лад. Люпини Зерет-Мортіса — одне з їхніх численних творінь, і кажуть, що ті з них, хто має багряну подобу, наймогутніші з усіх."},
    [2805] = {n="Примарний яструбоступ", d="Розбивач фаланг кінноти Сільвермуна, цей супутник минулих днів незмінно жене свого вершника вперед."},
    [2807] = {n="Бійцівський Бруно", d="Кажуть, він стрункіший і, можливо, ще лютіший за поважного Брюса. Спадщину Бруно ще тільки належить вписати в історію."},
    [2808] = {n="Балістичний Мустанг", d="Ідеальний транспорт для бійця, який завжди влучає в ціль."},
    [2815] = {n="Сніголапий Мерехтлехутрий Блукач", d="Сніголапі мешкають у крижаних потойбіччях Тіньових земель, тішачись своїм морозним середовищем. Подорожніх, яких вважали загиблими в смертоносних завірюхах Нортренда, часом дивом знаходили живими, і вони запевняли, що завдячують життям загадковим лисам, котрі їх оберігали."},
    [2817] = {n="Блискучий яструбоступ", d="Віддане створіння таласійської знаті, воно знаходить затишок, причаївшись на Терасі магістрів."},
    [2818] = {n="Смарагдовий Яструбоступ", d="Його вершник загинув у битві, тож сідло переходить до тебе."},
    [2823] = {n="Дика Багряна Бойова Черепаха", d="Ця дика черепаха повсякчас бачить усе в червоному. Хоч вона й повільна, варто пам'ятати: від гарматного пострілу не втечеш."},
    [2825] = {n="Хмаронароджений Гострокрил", d="Дуже рідкісне кортіанське створіння — через обмежений хмарний покрив."},
    [2827] = {n="Кривавий мучитель", d="Жорстокий повітряний хижак Войдшторму, кривавий мучитель надолужує брак непомітності моторошною подобою та мисливською вправністю."},
    [2828] = {n="Зв'язаний Порожнечею штормоскат", d="Своїми гострими, мов лезо, зубами зв'язаний Порожнечею штормоскат, здається, аж прагне тебе вкусити. І вкусить — але тільки якщо дозволиш."},
    [2829] = {n="Вирощений у лабораторії штормоскат", d="Завдяки наполегливим дослідженням у Порожнечі науковці змогли повернути цього штормоската до життя, цілком приборканим."},
    [2831] = {n="Морочний гнобитель", d="Найлютіші гнобителі Войдшторму часто спотворені Порожнечею і скуті волею Ксал'атат."},
    [2833] = {n="Деревна Псевдомушля", d="Рослини глибинних земель часто наслідують створінь Азероту. Призначення цієї мімікрії невідоме, та видовище буває доволі моторошним, коли наземні молюски опиняються по той бік деревної трапези."},
    [2834] = {n="Капустяна Псевдомушля", d="Рослини глибинних земель часто наслідують створінь Азероту. Призначення цієї мімікрії невідоме, та видовище буває доволі моторошним, коли наземні молюски опиняються по той бік деревної трапези."},
    [2835] = {n="Лавандова Псевдомушля", d="Рослини глибинних земель часто наслідують створінь Азероту. Призначення цієї мімікрії невідоме, та видовище буває доволі моторошним, коли наземні молюски опиняються по той бік деревної трапези."},
    [2836] = {n="Оздоблена Псевдомушля", d="Рослини глибинних земель часто наслідують створінь Азероту. Призначення цієї мімікрії невідоме, та видовище буває доволі моторошним, коли наземні молюски опиняються по той бік деревної трапези."},
    [2838] = {n="Фантастичний Гоблінський Хвилеруб", d="Коли ти готовий до розваг — ти готовий до Фантастичного Гоблінського Хвилеруба. Веселощі гарантовано.\n\n\n\n*Застереження: веселощі не гарантовано"},
    [2840] = {n="Чародійний захисник Сільвермуна", d="Позолочений різновид Арканного Вартового, якого найчастіше можна побачити на варті в розкішніших районах Сільвермуна."},
    [2841] = {n="Ельфійський Арканний Вартовий", d="Присяжний захисник ельфійського народу, оживлений арканною силою і незламною волею боронити."},
    [2842] = {n="Чародійно-порожнечний конструкт", d="Вплив Порожнечі сягає так далеко й буває настільки нездоланним, що навіть Арканного Вартового можна змусити вклякнути."},
    [2843] = {n="Примаравка", d="Цей слимак свідомо вирішив зануритися у слизові канали Андерсіті. Він виринув більшим і сильнішим, та не швидшим, ніж раніше."},
    [2845] = {n="Злостива Хапкоплетениця", d="Хапкоплетениці завжди були небезпечні, але ми й не здогадувалися, що глибинні різновиди самостійні й уміють літати. Ця хапкоплетениця завжди прагне побачити більше світу і добряче попоїсти."},
    [2846] = {n="Люта Хапкоплетениця", d="Хапкоплетениці завжди були небезпечні, але ми й не здогадувалися, що глибинні різновиди самостійні й уміють літати. Плоди цього звіра особливо смачні, коли спекти з них пиріг."},
    [2847] = {n="Кривава Хапкоплетениця", d="Хапкоплетениці завжди були небезпечні, та ми й не здогадувалися, що глибинні різновиди самостійні й здатні літати. Виразне, насичене забарвлення означає, що істота нещодавно поїла."},
    [2848] = {n="Дика Хапкоплетениця", d="Хапкоплетениці завжди були небезпечні, та ми й не здогадувалися, що глибинні різновиди самостійні й здатні літати. Кому взагалі спаде на думку шукати таке, а тим паче їздити на ньому? Та плоди в неї смачні."},
    [2849] = {n="Гіпошвидкість X6000", d="Набір гайок, болтів, шестерень та обробленої дерев'яної обшивки дарує напрочуд швидку поїздку."},
    [2850] = {n="Пухнаста Затишна Летюча Ковдра", d="Виткана найкращими магами Даларану, ця летюча ковдра славиться своїм затишком і пухнастими подушками."},
    [2851] = {n="Шорстка Затишна Летюча Ковдра", d="Виткана найбурчливішими магами Даларану, ця летюча ковдра славиться своїм затишком і пухнастими подушками."},
    [2852] = {n="Затишна Летюча Ковдра Бел'амета", d="Ковдри ручної роботи Айндеру Саммерліф популярні серед дітей Бел'амета."},
    [2853] = {n="Затишна Летюча Ковдра Сільвермуну", d="Зачаровані ковдри швачки Амбершайн стали обов'язковою покупкою для шляхетних дітей Сільвермуну."},
    [2912] = {n="Жвавий хлороцерос", d="Упіймати на льоту листок із гриви хлороцероса вважається серед гаранірів доброю прикметою. Що жвавіший листок, то більша удача."},
    [2913] = {n="Яскравий хлороцерос", d="Що здоровіший хлороцерос, то яскравіше його листя."},
    [2914] = {n="Скверний Шпилястий Яструб", d="Зазирнути в очі цьому містичному звіру — наче глянути в серце сонця, ураженого Скверною. Під час їзди радимо вдягати окуляри."},
    [2915] = {n="Вільний Манавирм", d="Бурхлива магія Порожнечі, що охопила Сонячний Колодязь, приваблює рідкісних великих манавирмів і псує їх, поки ті живляться вивільненою магією."},
    [2917] = {n="Ану'шалла, Провідниця Тіні", d="Її крила розтинають небо, мов тіні місячної ночі."},
    [2926] = {n="Ґілнеаський Залізний Бойовий Кінь", d="Цей шляхетний кінь пройшов чимало битв під час повстання, спричиненого прокляттям."},
    [2927] = {n="Ґілнеаський Мідний Бойовий Кінь", d="Мчи крізь ніч на цьому вірному й незламному скакуні."},
    [2928] = {n="Верховий Кінь Повстанця Вогнолісу", d="Після старанного вишколу під вершниками і в подобі ворґена, і в людській подобі ці коні тепер несуть будь-якого вершника в гілнеаському вбранні."},
    [2929] = {n="Верховий Кінь Лояліста Ґілнеасу", d="Стійкий і гордий, цей скакун несе свого вершника з тихою гідністю та непохитною рішучістю."},
    [2930] = {n="Квітоспинний Арбун", d="Колись арбуни були звичним видовищем у горах довкола Нефритового лісу. Їхнє повернення може означати, що ліс зцілюється."},
    [2931] = {n="Бурштиноспинний Арбун", d="Золоті квіти бурштиноспинного арбуна — це знак його віку й мудрості. Рідкість серед рідкостей: навіть побачити такого вважається доброю прикметою."},
    [2933] = {n="Чаклунська Бджола Магістра", d="Кілька магістрів Сільвермуна колись присвятили свою арканну працю вивченню того, як насичення місцевої флори пилком з домішкою аркани впливає на види-запилювачі. Для Великого Магістра це був успіх. Для садівників Сільвермуна — ні."},
    [2935] = {n="Яструбоступ, торкнутий Порожнечею", d="Майже жодна тварина не має імунітету до дотику Порожнечі. Кількох яструбоступів наших розвідників торкнулася Порожнеча. Я вже певний час спостерігаю за ними, і вони досі придатні до служби. У дечому вони навіть краще пасують до тієї роботи, яку ти затіваєш. — Сержант Ворнін"},
    [2939] = {n="[PH] Giant Eagle Sunwalker Mount Blue"},
    [2940] = {n="Сонячний Рух, Розмальований Сутінками", d="Колись давно розмальовані сутінками силуети цих сонячних рухів надихали чимало історій біля багаття. Їхнє повернення до Калімдору знову розпалило забуті оповіді про цих провісників Ан'ше."},
    [2941] = {n="Сонячний Рух, Розмальований Полум'ям", d="У минулі віки сонячних рухів Калімдору вважали посланцями Ан'ше, бо вони несли з собою перше полум'я перед світанком і останнє світло надвечір'я."},
    [2942] = {n="[PH] Giant Eagle Sunwalker Mount White"},
    [2948] = {n="Золотий Попелястий Катаклізм", d="У різних куточках Азероту переказують історії про страхітливого дракона, що оповив землю саваном муки. У деяких версіях цієї історії його вогняна присутність несла катаклізмічну смерть і руйнування всьому світу. В інших версіях він синій. А ще в інших — золотий."},
    [2961] = {n="Зіпсований Порожнечею врочений орел", d="Мерзенний ритуал може дарувати великий хист тому, хто його проводить. Але може дарувати велику силу й тому, на кого ритуал спрямовано. Іноді для проводиря ритуалу це обертається на добро, а іноді — на лихо."},
    [2964] = {n="Торкнутий Порожнечею Кусач-дракон", d="Кусач-дракон — істота витривала й вірна за своєю природою. Саме тому наги обрали їх за улюблених супутників. Та останній ритуал зробив цього кусач-дракона готовим до нової домівки."},
    [2965] = {n="Зіпсована Порожнечею рись", d="Вічноспівні рисі відомі своєю цікавістю, а ця — надто. Звичка прокрадатися до сховищ припасів і скринь зі скарбами поблизу ритуальних місць змінила її назавжди. Той, кому вдасться накинути на неї поводок, дістане запальну їздову тварину."},
    [3005] = {n="Лазуровий Смертоходець"},
